-- FLL-Naturteich · engineer hints on every field, equation and compliance requirement (hint wave 2026-10-05).
-- Each description now carries a German hint and an English part after the marker "[EN] " (src/lib/eval/hint-text.ts; the form
-- renders the part of the page locale; the approval refusal prints the whole text as "Hinweis" for a block gate without its inputs).
-- Content authored from the printed guideline pages (rendered PDF read in the authoring session; the authoring JSON in the vault
-- carries a source string with the printed page per hint); every number / limit / clause in a hint is traceable to those pages.
-- SAFETY: text only (fields.description, equations.description, compliance_requirements.description); no field, equation, gate,
-- value or severity changes. The pre-block descriptions (encoder notes) are restored by the rollback and kept in the inventory JSON.
-- STAGED — not applied. Apply: node scripts/apply-migration.mjs scripts/migrations/20261005171000_fll_naturteich_hints.sql
-- Rollback: scripts/migrations/rollback-20261005171000_fll_naturteich_hints.sql
BEGIN;
UPDATE fields x SET description = 'Bestätigung, dass Standort und Baugrund untersucht sind: Umgebungsbedingungen (Hochwasserrisiko, Schutzgebiete, Freileitungen, Topografie, Nachbarnutzung), Lage im Grundstück und Baugrund. Die Richtlinie nennt für Voruntersuchungen (Bohrungen, Sondierungen) Bodenart, Steifigkeit, Tragfähigkeit, Schichtaufbau, erwartete Setzungen, Grundwasserstand, Schichtenwasser und vorhandene Leitungen (§ 8.1.1–8.1.3). Beim Aushub muss der Untergrund tragfähig sein, sonst verdichten oder verbessern; Grund- oder Schichtenwasser verlangt Drainage (§ 9.1). Tor REQ-03 blockiert ohne Haken.
[EN] Attest that the site and the subsoil have been assessed: surrounding conditions (''risk of flooding'', protected areas, overhead lines, topography, adjacent use), location within the property and subsoil. For pilot surveys (boreholes, probes) the guideline lists soil type, stiffness, load-bearing capacity, composition of layers, expected settling, groundwater level, stratum water and existing supply lines (§ 8.1.1–8.1.3). At excavation the subsoil must be load-bearing, otherwise compacted or improved; groundwater or stratum water requires drainage (§ 9.1). Gate REQ-03 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'attest_fllnt_01_req_03';
UPDATE fields x SET description = 'Bestätigung, dass die Verkehrssicherungspflicht (''legal duty to maintain safety'') mit dem Eigentümer geklärt ist und die Schutzmaßnahmen festliegen. Sie trifft jeden Grundstückseigentümer, in der Bauphase zusätzlich den Planer/Lieferanten, und gilt auch nach Fertigstellung; gegenüber Kindern besteht sie auch bei unbefugtem Zutritt, daher i. d. R. Einfriedung (§ 8.1.4). Zäune: Mindesthöhe 1 m, waagerechte Latten ≤ 4 cm, senkrechte ≤ 11 cm, Bodenfreiheit ≤ 11 cm, abschließbares Tor, keine Klettermöglichkeit; Warnschilder genügen nicht (gedr. S. 38). Tor REQ-04 blockiert ohne Haken.
[EN] Attest that the ''legal duty to maintain safety'' has been settled with the owner and the protective measures are fixed. It applies to every property owner, during construction also to the planner/supplier, and continues after completion; towards children it applies even to unauthorised entry, hence usually an enclosure (§ 8.1.4). Fences: minimum height 1 m, horizontal slats ≤ 4 cm, vertical slats ≤ 11 cm, ground clearance ≤ 11 cm, lockable gate, no climbing aids; warning signs alone are insufficient (printed p. 38). Gate REQ-04 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'attest_fllnt_01_req_04';
UPDATE fields x SET description = 'Postanschrift des Auftraggebers (Bauherr). Reine Verwaltungsangabe für Berichtsköpfe und die Zusammenfassung (FLLNT-15); keine fachliche Prüfung.
[EN] Postal address of the client (owner). Administrative only; carried into report headers and the summary sheet (FLLNT-15); no technical check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'client_address';
UPDATE fields x SET description = 'Name des Auftraggebers bzw. Eigentümers des Naturteichs. Verwaltungsangabe für Berichte, Abnahme (FLLNT-13) und Instandhaltung (FLLNT-14). Der Eigentümer trägt die Verkehrssicherungspflicht (§ 8.1.4); der Zweck der Richtlinie ist Vertragssicherheit zwischen Käufer, Planer, Lieferant und Ausführendem (§ 1.2).
[EN] Name of the client / owner of the natural pool. Administrative; used in reports, acceptance (FLLNT-13) and maintenance (FLLNT-14). The owner carries the legal duty to maintain safety (§ 8.1.4); the guideline''s purpose is contractual security between purchasers, planners, suppliers and installation firms (§ 1.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'client_name';
UPDATE fields x SET description = 'Haken, wenn die Checkliste zur Kundenberatung (Anhang 3, informativ) durchgearbeitet ist: a) Standortbedingungen, b) Gesetze/Richtlinien, c) Kundeninformation (Nutzungsintensität, Nutzerprofil, Wasseraufbereitung, Teichtyp), d) Projektdaten (Flächen, Proportionen, Wassertiefen, Technik), e) Instandhaltung, f) Ausführungsplanung, g) Kosten, h) Kundenunterlagen. § 5 verlangt in der Typwahl eine umfassende Beratung mit Verweis auf Anhang 3. Tor REQ-02 blockiert ohne Haken.
[EN] Tick when the checklist for customer consultation (Appendix 3, informative) has been worked through: a) conditions on site, b) laws/directives, c) customer information (intensity of use, user profile, water purification, pool type), d) project-related information (areas, proportions, water depths, technical equipment), e) maintenance, f) implementation planning, g) costs, h) customer handouts. § 5 requires extensive consultation when choosing the type and refers to Appendix 3. Gate REQ-02 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'consultation_checklist_completed';
UPDATE fields x SET description = 'Ausführender Garten- und Landschaftsbaubetrieb. Verwaltungsangabe für Berichte und Abnahme (FLLNT-13). In der Bauphase ist neben dem Eigentümer auch derjenige verkehrssicherungspflichtig, dem die Bauleitung übertragen ist (§ 8.1.4).
[EN] Garden / landscape construction firm executing the works. Administrative; used in reports and acceptance (FLLNT-13). During construction the person to whom site management has been transferred is responsible for safety in addition to the owner (§ 8.1.4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'contractor_name';
UPDATE fields x SET description = 'Erwartete Nutzungsintensität (gering / mittel / hoch — Skala des Werkzeugs, nicht gedruckt). Art und Größe von Schwimm- und Regenerationsbereich müssen dem Nutzerverhalten angepasst sein; empfohlen wird ein Wasservolumen von mindestens 10 m³ je Nutzer (§ 6.5). Nutzungsintensität, Regenerationsbereich und Technik sind aufeinander abzustimmen (§ 5). Wird in FLLNT-04 und FLLNT-06 berücksichtigt.
[EN] Expected intensity of use (low / medium / high — the tool''s scale, not printed). Type and size of the swimming and regeneration areas must be adapted to the users'' behaviour; a minimum water volume of 10 m³ per user is recommended (§ 6.5). Intensity of use, regeneration area and technical installations must be coordinated (§ 5). Used by FLLNT-04 and FLLNT-06.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'intended_use_intensity';
UPDATE fields x SET description = 'Verantwortlicher Planer (Planungsexperte / Landschaftsarchitekt). Verwaltungsangabe für Berichte und Abnahme. Während der Bauphase haftet der Planungsexperte oder Lieferant, dem die Bauleitung übertragen ist, neben dem Eigentümer für die Verkehrssicherheit (§ 8.1.4).
[EN] Responsible planning expert / landscape architect. Administrative; used in reports and acceptance. During the construction phase the planning expert or supplier entrusted with site management is responsible for safety in addition to the owner (§ 8.1.4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'planner_name';
UPDATE fields x SET description = 'Datum des Planungsbeginns. Verwaltungsangabe für Berichtsköpfe und die Zusammenfassung; keine Prüfung.
[EN] Date the planning phase commenced. Administrative; report headers and summary only; no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'planning_date';
UPDATE fields x SET description = 'Nutzungsform: privat (Einzelhaushalt) oder privat (mehrere Haushalte) — beides ist Privatnutzung. Die Richtlinie gilt nur für Naturteiche, die ''exclusively used for private purposes'' sind, speziell zum Schwimmen gebaut, gegen den Untergrund abgedichtet, mit Wasserqualitätsanforderungen, biologischer Aufbereitung und ohne dauerhaften Zu-/Ablauf (§ 1.1). Gewerbliche oder öffentliche Anlagen nach § 37 IfSG (z. B. Hotelteiche) fallen unter die Richtlinie für öffentliche Schwimmteiche. Tor REQ-01 verlangt eine der beiden Optionen.
[EN] Form of use: private (single household) or private (multi-household) — both are private use. The guideline applies only to natural pools ''exclusively used for private purposes'', specifically built for swimming, sealed against the subsoil, subject to water-quality requirements, with biological purification and without permanent inflows or outflows (§ 1.1). Commercial or public installations under § 37 IfSG (e.g. hotel pools) fall under the public natural-pool guidelines. Gate REQ-01 requires one of the two options.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'pool_use_type';
UPDATE fields x SET description = 'Eindeutige Projektkennung des Büros. Wird in FLLNT-02, FLLNT-03 und FLLNT-15 übernommen; keine fachliche Prüfung.
[EN] Unique project identifier of the office. Carried into FLLNT-02, FLLNT-03 and FLLNT-15; no technical check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'project_id';
UPDATE fields x SET description = 'Lesbarer Projekttitel für Berichte und die Zusammenfassung. Verwaltungsangabe; keine Prüfung.
[EN] Human-readable project title for reports and the summary sheet. Administrative; no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.symbol = 'project_name';
UPDATE compliance_requirements x SET description = 'Besteht, wenn als Nutzungstyp eine der beiden privaten Optionen gewählt ist. Die Richtlinie gilt nur für Naturteiche im Freien, die ausschließlich privat genutzt werden, speziell zum Schwimmen gebaut, gegen den Untergrund abgedichtet, biologisch aufbereitet und als geschlossenes System ohne dauerhafte Zu-/Abläufe betrieben werden (§ 1.1). Gewerbliche/öffentliche Anlagen (§ 37 IfSG) fallen unter die Richtlinie für öffentliche Schwimmteiche — dann nicht anwendbar.
[EN] Passes when one of the two private options is chosen as use type. The guideline applies only to open-air natural pools exclusively used for private purposes, specifically built for swimming, sealed against the subsoil, biologically purified and operated as a closed system without permanent inflows or outflows (§ 1.1). Commercial/public installations (§ 37 IfSG) fall under the public natural-pool guidelines — then not applicable.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.code = 'REQ-01';
UPDATE compliance_requirements x SET description = 'Besteht, wenn ''Beratungs-Checkliste abgeschlossen'' angehakt ist. Die Typwahl muss in Abstimmung mit dem Planungsexperten nach Abwägung der Wünsche des Eigentümers und der Standortbedingungen erfolgen; ''extensive consultation must take place'' mit Verweis auf Anhang 3 (§ 5). Die Checkliste deckt Standort, Recht, Kundenwünsche, Dimensionierung, Instandhaltung, Kosten und Kundenunterlagen ab (Anhang 3).
[EN] Passes when ''Consultation checklist completed'' is ticked. The choice of type must be made in consultation with the planning expert after weighing the owner''s requirements against the site conditions; ''extensive consultation must take place'' with reference to Appendix 3 (§ 5). The checklist covers site, law, customer wishes, dimensioning, maintenance, costs and customer handouts (Appendix 3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.code = 'REQ-02';
UPDATE compliance_requirements x SET description = 'Besteht, wenn der Nachweis § 8.1.3 / § 9.1 angehakt ist. Dafür müssen Umgebung, Lage im Grundstück und Baugrund bewertet sein — ggf. mit Bohrungen/Sondierungen zu Bodenart, Tragfähigkeit, Schichtaufbau, Setzungen, Grundwasser, Schichtenwasser und Leitungen (§ 8.1.1–8.1.3) — und der Untergrund muss tragfähig sein oder verdichtet/verbessert werden (§ 9.1). Maßgebende Regeln: ATV DIN 18300, DIN 1054, DIN 18196, DIN 4020, DIN 4124, DIN EN ISO 14688-1.
[EN] Passes when the attestation § 8.1.3 / § 9.1 is ticked. This requires surroundings, location within the property and subsoil to be assessed — with boreholes/probes where needed for soil type, load-bearing capacity, layers, settling, groundwater, stratum water and supply lines (§ 8.1.1–8.1.3) — and the subsoil to be load-bearing or compacted/improved (§ 9.1). Governing rules: ATV DIN 18300, DIN 1054, DIN 18196, DIN 4020, DIN 4124, DIN EN ISO 14688-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.code = 'REQ-03';
UPDATE compliance_requirements x SET description = 'Besteht, wenn der Nachweis § 8.1.4 angehakt ist. Die Verkehrssicherungspflicht gilt für jeden Eigentümer, in Bau- und Betriebsphase; Kinder sind auch bei unbefugtem Zutritt zu schützen, i. d. R. durch Einfriedung; Schutz muss umso wirksamer sein, je attraktiver der Teich für Kinder ist (BGH 20.09.1994). Zaun, sofern die Landesbauordnung nichts anderes verlangt: ≥ 1 m hoch, Latten ≤ 4 cm / ≤ 11 cm, Bodenfreiheit ≤ 11 cm, abschließbares Tor. Sicherheitshinweise nach DIN EN 16582-1 gehören in die Betriebsanleitung.
[EN] Passes when the attestation § 8.1.4 is ticked. The legal duty to maintain safety applies to every owner, during construction and operation; children must be protected even against unauthorised entry, usually by enclosing the property; measures must be more effective the greater the pool''s appeal to children (BGH 20/9/1994). Fence, unless the state building code says otherwise: ≥ 1 m high, slats ≤ 4 cm / ≤ 11 cm, ground clearance ≤ 11 cm, lockable gate. Safety information per DIN EN 16582-1 belongs in the operating manual.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-01' AND x.code = 'REQ-04';
UPDATE fields x SET description = 'Haken, wenn eine Einfriedung bzw. gleichwertige Sicherung gegen unbeaufsichtigten Zutritt von Kindern vorhanden oder geplant ist. Die Richtlinie empfiehlt Zäune mit Mindesthöhe 1 m, waagerechten Lattenabständen ≤ 4 cm, senkrechten ≤ 11 cm, Bodenfreiheit ≤ 11 cm und abschließbarem Tor, ohne Klettermöglichkeiten, soweit die Landesbauordnung nichts anderes bestimmt; eine Hecke oder vergleichbare Barriere kann genügen, wenn bisher keine Kinder unbefugt auf dem Grundstück gespielt haben und es klar abgegrenzt ist (OLG Hamm 23.05.2001). Wird in FLLNT-07 und FLLNT-13 weiterverwendet.
[EN] Tick when an enclosure or an equivalent safeguard against unsupervised access by children exists or is planned. The guideline recommends fences with a minimum height of 1 m, horizontal slat spacing ≤ 4 cm, vertical ≤ 11 cm, ground clearance ≤ 11 cm and a lockable gate, without climbing opportunities, unless the state building code stipulates otherwise; a hedge or comparable barrier can suffice if children have not so far played on the property without authorisation and it is clearly set apart (OLG Hamm 23/5/2001). Used by FLLNT-07 and FLLNT-13.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-02' AND x.symbol = 'enclosure_provided';
UPDATE fields x SET description = 'Haken, wenn eine Bestandsanlage umgebaut oder saniert wird. Dann ist die Checkliste für Bestandsanlagen (Anhang 4, informativ) aufzunehmen: Flächen und Wassertiefen, zugeordneter Teichtyp I–V, verwendete Substrate und Baustoffe mit Prüfberichten, Zustand (Sichttiefe, Temperatur, Algen/Biofilm, Nährstoffablagerungen), vorhandene Unterlagen, Nutzung, Filter, Hydraulik/Technik, Bauweise, Pflanzen, Pflege. Wird in FLLNT-07 berücksichtigt.
[EN] Tick when an existing pool is being remodelled or refurbished. The checklist for existing systems (Appendix 4, informative) then has to be recorded: areas and water depths, assigned pool type I–V, substrates and building materials used with test reports, condition (transparency, temperature, algae/biofilm, nutrient deposits), existing documentation, use, filter, hydraulics/technology, structure, plants, care. Used by FLLNT-07.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-02' AND x.symbol = 'existing_system';
UPDATE fields x SET description = 'Grundwasserstand als Tiefe unter Geländeoberkante in m, aus der Baugrunduntersuchung (Bohrung/Sondierung) oder langjährigen Beobachtungen. Die Richtlinie nennt Grundwasserstand und Schichtenwasser als Gegenstand der Voruntersuchung (§ 8.1.3); ist Grund- oder Schichtenwasser zu erwarten, sind Maßnahmen wie Drainagen erforderlich (§ 9.1), und die Abdichtung muss das Eindringen von Grund-/Schichtenwasser verhindern (§ 9.3). Wird in FLLNT-07 weiterverwendet.
[EN] Groundwater level as depth below ground surface in m, from the subsoil survey (borehole/probe) or many years'' observations. The guideline lists groundwater level and stratum water among the pilot-survey items (§ 8.1.3); if groundwater or stratum water is expected, measures such as drainage systems must be taken (§ 9.1), and the seal must prevent groundwater or stratum water from entering (§ 9.3). Used by FLLNT-07.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-02' AND x.symbol = 'groundwater_level';
UPDATE fields x SET description = 'Haken, wenn die schriftliche Betriebsanleitung erstellt ist. Sie muss enthalten: erforderliche Kontrollen, Pflege- und Wartungsarbeiten mit Intervallen, Bedienungsanleitungen der technischen Produkte (z. B. Umwälzpumpe, Skimmer, Technikeinheit) und Nutzungshinweise; der Käufer ist zusätzlich mündlich und praktisch einzuweisen (§ 8.1.5). Die Sicherheitshinweise nach DIN EN 16582-1 sind beizufügen (§ 8.1.4). Tor REQ-05 blockiert ohne Haken; wird in FLLNT-13/14 weiterverwendet.
[EN] Tick when the written operating manual has been created. It must include: required checks, required maintenance and care work with intervals, instruction manuals for the technical products used (e.g. circulation pump, skimmer, technical unit) and instructions for use; the purchaser must additionally be instructed verbally and practically (§ 8.1.5). The safety-related information per DIN EN 16582-1 must be attached (§ 8.1.4). Gate REQ-05 blocks until ticked; used by FLLNT-13/14.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-02' AND x.symbol = 'operating_manual_provided';
UPDATE fields x SET description = 'Adresse des Grundstücks, auf dem der Naturteich entsteht. Verwaltungsangabe; dient zugleich als Bezug für die Umgebungsbedingungen (Hochwasserrisiko, Klima, Schutzgebiete, Freileitungen, Topografie, Nachbarnutzung), die § 8.1.1 für Bau, Pflege und Nutzung verlangt.
[EN] Address of the property where the natural pool is built. Administrative; it also anchors the surrounding conditions (risk of flooding, climate, protected areas, overhead lines, topography, adjacent use) that § 8.1.1 requires to be considered for construction, maintenance and use.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-02' AND x.symbol = 'site_address';
UPDATE fields x SET description = 'Vorherrschender Baugrund am Standort (Fels, Kies, Sand, Ton, Lehm, Mischboden, Auffüllung — Klassen des Werkzeugs), aus der Baugrunduntersuchung. Die Richtlinie verlangt Voruntersuchungen zu gewachsenem oder geschüttetem Boden, Bodenart, Steifigkeit, Tragfähigkeit und Schichtaufbau sowie zu Setzungen und Grundbruchgefahr (§ 8.1.3); Bodenklassifikation nach DIN 18196 / DIN EN ISO 14688-1. Nicht tragfähiger Boden ist zu verdichten oder zu verbessern (§ 9.1). Wird in FLLNT-07 weiterverwendet.
[EN] Predominant subsoil at the site (rock, gravel, sand, clay, loam, mixed soil, fill — the tool''s classes), from the subsoil survey. The guideline requires pilot surveys of grown or heaped subsoil, soil type, stiffness, load-bearing capacity and composition of layers, plus expected settling and risk of ground breakage (§ 8.1.3); soil classification per DIN 18196 / DIN EN ISO 14688-1. Non-load-bearing soil must be compacted or improved (§ 9.1). Used by FLLNT-07.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-02' AND x.symbol = 'subsoil_type';
UPDATE compliance_requirements x SET description = 'Besteht, wenn ''Betriebsanleitung erstellt'' angehakt ist. Für die ordnungsgemäße Planung und Ausführung eines Naturteichs muss eine schriftliche Betriebsanleitung erstellt werden mit Kontrollen, Pflege- und Wartungsarbeiten samt Intervallen, Bedienungsanleitungen der Technik und Nutzungshinweisen; der Käufer ist mündlich und praktisch einzuweisen (§ 8.1.5). Sicherheitshinweise nach DIN EN 16582-1 sind beizufügen (§ 8.1.4).
[EN] Passes when ''Operating manual provided'' is ticked. A written operating manual must be created for the proper planning and construction of a natural pool, covering required checks, maintenance and care work with intervals, instruction manuals of the technical products and instructions for use; the purchaser must be instructed verbally and practically (§ 8.1.5). Safety information per DIN EN 16582-1 must be attached (§ 8.1.4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-02' AND x.code = 'REQ-05';
UPDATE fields x SET description = 'Gewählter Naturteich-Typ nach Tab. 1: Typ I ''without technology for water purification'' (ohne Aufbereitungstechnik, natürliche Zirkulation), Typ II ''with surface water purification'' (Oberflächenabzug, Skimmer zeitweise), Typ III langsam durchströmter Substratfilter mit nachgeschalteter P-Bindung, Typ IV schnell durchströmter Substratfilter (Dauerbetrieb), Typ V Durchströmung einer technischen Filtereinheit. Die Typen unterscheiden sich nach Art und Umfang der Technik für die Durchströmung von Schwimm- und Regenerationsbereich (§ 5). Steuert Mindestanteil, Tab.-8-P-Grenzen und die Bemessungsblätter FLLNT-06, 09–12, 14.
[EN] Selected natural pool type per Tab. 1: Type I ''without technology for water purification'' (natural circulation), Type II ''with surface water purification'' (surface discharge, skimmer intermittently), Type III controlled slow flow through a substrate filter with downstream P-binding unit, Type IV controlled quick flow through a substrate filter (permanent operation), Type V controlled flow through a technical unit. Types are distinguished by the type and scope of technical systems used to achieve a flow through the swimming and regeneration areas (§ 5). Drives the minimum share, the Tab. 8 P-limits and the sizing sheets FLLNT-06, 09–12, 14.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-03' AND x.symbol = 'natural_pool_type';
UPDATE fields x SET description = 'Haken, wenn der Regenerationsbereich einen langsam durchströmten Substratfilter enthält: solche Filter ''must be equipped with a downstream phosphorous-binding purification stage'' — ein submerses hydrobotanisches System oder adsorbierendes Filtermaterial (§ 10.2.2). Typ III heißt in Tab. 1 ausdrücklich ''with controlled slow flow through the substrate filter and downstream P-binding unit''. Wird in FLLNT-10 und FLLNT-11 geprüft.
[EN] Tick when the regeneration area contains a substrate filter with a controlled slow flow: such filters ''must be equipped with a downstream phosphorous-binding purification stage'' — a submergent hydrobotanical system or adsorbing filter material (§ 10.2.2). Type III is named in Tab. 1 explicitly ''with controlled slow flow through the substrate filter and downstream P-binding unit''. Checked in FLLNT-10 and FLLNT-11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-03' AND x.symbol = 'p_binding_required';
UPDATE fields x SET description = 'Geplanter Anteil des Regenerationsbereichs an der Gesamtwasserfläche in %, aus dem Flächenplan (Regenerationsfläche ÷ (Schwimm- + Regenerationsfläche) × 100; Ergänzungsflächen wie Wege und Liegeflächen gehören nicht zum Teich, § 3). Tab. 1 verlangt ≥ 50 % für Typ I und II und ≥ 30 % für Typ III; Tab. 2/3 schreiben ''> 50%'', davon mindestens die Hälfte als submerses hydrobotanisches System. Für Typ IV/V ist die Prozentangabe ''irrelevant, design-related'' (Tab. 5/6). Tor REQ-07 prüft den Wert.
[EN] Planned share of the regeneration area in the total water area in %, from the area plan (regeneration area ÷ (swimming + regeneration area) × 100; supplementary areas such as paths and rest areas do not belong to the pool, § 3). Tab. 1 requires ≥ 50 % for Types I and II and ≥ 30 % for Type III; Tab. 2/3 print ''> 50%'', of which at least half as a submerged hydrobotanical system. For Types IV/V the percentage is ''irrelevant, design-related'' (Tab. 5/6). Gate REQ-07 checks the value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-03' AND x.symbol = 'regeneration_area_share';
UPDATE fields x SET description = 'Hauptverfahren der Wasseraufbereitung im Regenerationsbereich. Tab. 1: Typ I/II hydrobotanisches System; Typ III Substratfilter (meist mineralisch, mit oder ohne Pflanzen) plus hydrobotanisches System oder Technikeinheit zur Phosphorelimination; Typ IV Substratfilter; Typ V Trägermaterial in einer technischen Einheit. Hydrobotanische Systeme sind submers (Unterwasserpflanzen) oder emers (Sumpfpflanzen) ausgeführt (§ 3). Physikalisch-chemische Verfahren sind nur ergänzend zu biologischen zulässig (§ 10.2.5). Steuert FLLNT-09, 10 und 11.
[EN] Main purification technique in the regeneration area. Tab. 1: Types I/II hydrobotanical system; Type III substrate filter (usually mineral, with or without plants) plus hydrobotanical system or technical unit for phosphorus elimination; Type IV substrate filter; Type V carrier material in a technical unit. Hydrobotanical systems are designed submerged (underwater plants) or emersed (marsh plants) (§ 3). Physical/chemical techniques may only be used in conjunction with biological ones, as supplementary methods (§ 10.2.5). Drives FLLNT-09, 10 and 11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-03' AND x.symbol = 'regeneration_technique';
UPDATE fields x SET description = 'Wird aus Tab. 1 zum gewählten Typ gefüllt: Mindestanteil des Regenerationsbereichs an der Gesamtfläche — 50 % für Typ I, 50 % für Typ II, 30 % für Typ III (''≥ 50 %'', ''≥ 50 %'', ''≥ 30 %'', gedr. S. 22). Für Typ IV und V ist das Feld ausgeblendet, weil Tab. 1 statt eines Prozentsatzes auf die bauartabhängigen Angaben in Tab. 5 bzw. Tab. 6 verweist. Dient als Vergleichswert für den eingegebenen Anteil (Tor REQ-07).
[EN] Filled from Tab. 1 for the selected type: minimum share of the regeneration area compared to the total area — 50 % for Type I, 50 % for Type II, 30 % for Type III (''≥ 50 %'', ''≥ 50 %'', ''≥ 30 %'', printed p. 22). Hidden for Types IV and V because Tab. 1 refers to the design-related information in Tab. 5 and Tab. 6 instead of a percentage. Serves as the reference value for the entered share (gate REQ-07).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-03' AND x.symbol = 'regeneration_share_min_pct';
UPDATE fields x SET description = 'Wird gefüllt: die Zelle ''Dimension of the regeneration area compared to the total area'' aus Tab. 1 für den gewählten Typ, wie gedruckt — ''≥ 50%'' (Typ I), ''≥ 50%'' (Typ II), ''≥ 30%'' (Typ III), ''information on construction based on design refer to Tab. 5'' (Typ IV) bzw. ''refer to Tab. 6'' (Typ V). Nur zur Anzeige; keine Eingabe.
[EN] Filled automatically: the cell ''Dimension of the regeneration area compared to the total area'' of Tab. 1 for the selected type, as printed — ''≥ 50%'' (Type I), ''≥ 50%'' (Type II), ''≥ 30%'' (Type III), ''information on construction based on design refer to Tab. 5'' (Type IV) or ''refer to Tab. 6'' (Type V). Display only; no entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-03' AND x.symbol = 'regeneration_share_tab1_text';
UPDATE fields x SET description = 'Wird gefüllt: die Zeile ''Flow'' aus Tab. 1 für den gewählten Typ, wie gedruckt — ''natural circulation'' (I), ''Surface discharge and natural circulation'' (II), ''Surface discharge and slow controlled flow through the regeneration area'' (III), ''… quick controlled flow through the regeneration area'' (IV), ''… quick or slow controlled flow through the technical unit'' (V). Nur zur Anzeige; die Durchströmungsart des Filters wird in FLLNT-10 gewählt.
[EN] Filled automatically: the ''Flow'' row of Tab. 1 for the selected type, as printed — ''natural circulation'' (I), ''Surface discharge and natural circulation'' (II), ''Surface discharge and slow controlled flow through the regeneration area'' (III), ''… quick controlled flow through the regeneration area'' (IV), ''… quick or slow controlled flow through the technical unit'' (V). Display only; the filter flow type is chosen in FLLNT-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-03' AND x.symbol = 'flow_tab1_text';
UPDATE fields x SET description = 'Wird gefüllt: die Zeile ''Filter operation during swimming season'' aus Tab. 1 für den gewählten Typ, wie gedruckt — ''no filter'' (I), ''no filter, skimmer operation intermittently'' (II), ''intermittent/permanent'' (III), ''permanent'' (IV), ''dependent on system'' (V). Tab. 4/5 konkretisieren: Typ III Filterbetrieb > 12 h/Tag, maximale Stillstandszeit 1 h; Typ IV 24 h/Tag. Nur zur Anzeige.
[EN] Filled automatically: the row ''Filter operation during swimming season'' of Tab. 1 for the selected type, as printed — ''no filter'' (I), ''no filter, skimmer operation intermittently'' (II), ''intermittent/permanent'' (III), ''permanent'' (IV), ''dependent on system'' (V). Tab. 4/5 add detail: Type III filter operation > 12 h/day, maximum downtime 1 h; Type IV 24 h/day. Display only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-03' AND x.symbol = 'filter_operation_tab1_text';
UPDATE compliance_requirements x SET description = 'Besteht, sobald ein Naturteich-Typ I–V gewählt ist. Die Zuordnung zu einem Typ nach Tab. 1 ist Grundlage aller weiteren Anforderungen (Regenerationsfläche, Filterbetrieb, Tab.-8-Grenzen, Bemessung); § 5 verlangt, dass die Entscheidung mit dem Planungsexperten unter Abwägung der Eigentümerwünsche und der Standortbedingungen getroffen wird. Anhang 3 fordert eine ''project description with distinct allocation of the type of natural pool''.
[EN] Passes as soon as a natural pool type I–V is selected. The allocation to a type per Tab. 1 underlies all further requirements (regeneration area, filter operation, Tab. 8 limits, sizing); § 5 requires the decision to be taken with the planning expert after weighing the owner''s requirements against the site conditions. Appendix 3 asks for a ''project description with distinct allocation of the type of natural pool''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-03' AND x.code = 'REQ-06';
UPDATE compliance_requirements x SET description = 'Gilt nur für Typ I, II und III. Besteht, wenn der eingegebene Regenerationsflächenanteil über 50 % (Typ I/II) bzw. über 30 % (Typ III) liegt — das Tor prüft streng ''größer als''. Gedruckt: Tab. 1 ''≥ 50 %'' / ''≥ 50 %'' / ''≥ 30 %'' (S. 22); Tab. 2/3 ''> 50%'' (S. 23–24); Tab. 4 ''≥ 30%'' (S. 25). Einzugeben: Naturteich-Typ und Regenerationsflächenanteil (Regenerationsfläche ÷ Wasserfläche aus Schwimm- + Regenerationsbereich). Grund: Die Wasserreinigung der Typen I–III beruht auf dem hydrobotanischen/Substratfilter-Bereich, der daher eine Mindestgröße braucht (§ 5, § 8.2.2).
[EN] Applies only to Types I, II and III. Passes when the entered regeneration-area share exceeds 50 % (Type I/II) or 30 % (Type III) — the gate checks strictly ''greater than''. Printed: Tab. 1 ''≥ 50 %'' / ''≥ 50 %'' / ''≥ 30 %'' (p. 22); Tab. 2/3 ''> 50%'' (pp. 23–24); Tab. 4 ''≥ 30%'' (p. 25). Enter: natural pool type and regeneration area share (regeneration area ÷ water area of swimming + regeneration area). Reason: purification in Types I–III relies on the hydrobotanical/substrate-filter area, which therefore needs a minimum size (§ 5, § 8.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-03' AND x.code = 'REQ-07';
UPDATE compliance_requirements x SET description = 'Besteht, wenn alle neun Schwimmbereichswerte (FLLNT-04) die Richtwerte der Tab. 8 einhalten: Ammonium ≤ 0,3 mg/l; Gesamthärte ≥ 1,0 mmol/l; Leitfähigkeit ≤ 1000 µS/cm (20 °C); Nitrat ≤ 30,0 mg/l; Nitrit ≤ 0,01 mg/l; pH 7,0–9,0; Säurekapazität KS 4,3 ≥ 2 mmol/l; Gesamtphosphor und Orthophosphat (als P) ≤ 0,03 mg/l bei Typ I–III bzw. ≤ 0,01 mg/l bei Typ IV/V. Einzugeben: Naturteich-Typ hier und die swimming_test_*-Werte in FLLNT-04 (Referenzverfahren Anhang 1). Bei Abweichungen sind die biologischen Prozesse zu beobachten, ggf. eine erweiterte Gesamtwasseranalyse und Maßnahmen (§ 7.1.2).
[EN] Passes when all nine swimming-area values (FLLNT-04) meet the approximate values of Tab. 8: ammonium ≤ 0.3 mg/l; total hardness ≥ 1.0 mmol/l; conductivity ≤ 1000 µS/cm (20 °C); nitrate ≤ 30.0 mg/l; nitrite ≤ 0.01 mg/l; pH 7.0–9.0; acid capacity KS 4.3 ≥ 2 mmol/l; total phosphorus and orthophosphate (as P) ≤ 0.03 mg/l for Types I–III or ≤ 0.01 mg/l for Types IV/V. Enter: the pool type here and the swimming_test_* values in FLLNT-04 (reference method Appendix 1). If results deviate, the biological processes must be observed, if applicable an advanced total water analysis and measures (§ 7.1.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-03' AND x.code = 'REQ-10';
UPDATE fields x SET description = 'Säurekapazität KS 4,3 des Wassers im Schwimmbereich in mmol/l (entspricht der Karbonathärte), aus der Laboranalyse nach dem Referenzverfahren in Anhang 1. Richtwert Tab. 8: ≥ 2 mmol/l (≥ 5,6 °dH). Geprüft in Tor REQ-10.
[EN] Acid capacity KS 4.3 of the swimming-area water in mmol/l (corresponds to carbonate hardness), from the laboratory analysis per the reference method in Appendix 1. Approximate value Tab. 8: ≥ 2 mmol/l (≥ 5.6 dH°). Checked by gate REQ-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'swimming_test_acid_capacity_ks43';
UPDATE fields x SET description = 'Ammoniumkonzentration im Schwimmbereich in mg/l aus der Wasseranalyse (Referenzverfahren Anhang 1). Richtwert Tab. 8: ≤ 0,3 mg/l — strenger als beim Füllwasser (≤ 0,5 mg/l, Tab. 7). Geprüft in Tor REQ-10.
[EN] Ammonium concentration in the swimming area in mg/l from the water analysis (reference method Appendix 1). Approximate value Tab. 8: ≤ 0.3 mg/l — stricter than for fill-up water (≤ 0.5 mg/l, Tab. 7). Checked by gate REQ-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'swimming_test_ammonium';
UPDATE fields x SET description = 'Elektrische Leitfähigkeit des Schwimmbereichswassers in µS/cm, bezogen auf 20 °C, aus der Analyse. Richtwert Tab. 8: ≤ 1000 µS/cm at 20°C. Geprüft in Tor REQ-10.
[EN] Electrical conductivity of the swimming-area water in µS/cm at 20 °C, from the analysis. Approximate value Tab. 8: ≤ 1000 µS/cm at 20°C. Checked by gate REQ-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'swimming_test_conductivity';
UPDATE fields x SET description = 'Gesamthärte (Erdalkalien, ''total alkaline earth'') des Schwimmbereichswassers in mmol/l aus der Analyse. Richtwert Tab. 8: ≥ 1,0 mmol/l, entspricht ≥ 5,6 °dH. Geprüft in Tor REQ-10.
[EN] Total hardness (''total alkaline earth'') of the swimming-area water in mmol/l from the analysis. Approximate value Tab. 8: ≥ 1.0 mmol/l, corresponding to ≥ 5.6 dH°. Checked by gate REQ-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'swimming_test_hardness';
UPDATE fields x SET description = 'Nitratkonzentration im Schwimmbereich in mg/l aus der Analyse. Richtwert Tab. 8: ≤ 30,0 mg/l (Füllwasser: ≤ 50,0 mg/l, Tab. 7). Geprüft in Tor REQ-10.
[EN] Nitrate concentration in the swimming area in mg/l from the analysis. Approximate value Tab. 8: ≤ 30.0 mg/l (fill-up water: ≤ 50.0 mg/l, Tab. 7). Checked by gate REQ-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'swimming_test_nitrate';
UPDATE fields x SET description = 'Nitritkonzentration im Schwimmbereich in mg/l aus der Analyse. Richtwert Tab. 8: ≤ 0,01 mg/l; für Füllwasser nennt Tab. 7 keinen Nitritwert. Geprüft in Tor REQ-10.
[EN] Nitrite concentration in the swimming area in mg/l from the analysis. Approximate value Tab. 8: ≤ 0.01 mg/l; Tab. 7 has no nitrite row for fill-up water. Checked by gate REQ-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'swimming_test_nitrite';
UPDATE fields x SET description = 'Orthophosphat, angegeben als P, im Schwimmbereich in mg/l aus der Analyse. Richtwert Tab. 8 nach Teichtyp: ≤ 0,03 mg/l (Typ I–III) bzw. ≤ 0,01 mg/l (Typ IV, V); der zum gewählten Typ gültige Wert erscheint in swimming_orthophosphate_limit. Die Biomasseproduktion des Gewässers ist phosphorlimitiert (§ 3 ''Trophic state'', gedr. S. 16). Geprüft in Tor REQ-10.
[EN] Orthophosphate, indicated as P, in the swimming area in mg/l from the analysis. Approximate value Tab. 8 by pool type: ≤ 0.03 mg/l (Types I–III) or ≤ 0.01 mg/l (Types IV, V); the value for the selected type is shown in swimming_orthophosphate_limit. Biomass production in the pool is phosphorus-limited (§ 3 ''Trophic state'', printed p. 16). Checked by gate REQ-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'swimming_test_orthophosphate';
UPDATE fields x SET description = 'Gesamtphosphor [P_total] im Schwimmbereich in mg/l aus der Analyse. Richtwert Tab. 8 nach Teichtyp: ≤ 0,03 mg/l (Typ I–III) bzw. ≤ 0,01 mg/l (Typ IV, V); der zum gewählten Typ gültige Wert erscheint in swimming_p_total_limit. Geprüft in Tor REQ-10.
[EN] Total phosphorus [P_total] in the swimming area in mg/l from the analysis. Approximate value Tab. 8 by pool type: ≤ 0.03 mg/l (Types I–III) or ≤ 0.01 mg/l (Types IV, V); the value for the selected type is shown in swimming_p_total_limit. Checked by gate REQ-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'swimming_test_p_total';
UPDATE fields x SET description = 'pH-Wert des Schwimmbereichswassers aus der Analyse. Richtwert Tab. 8: 7,0–9,0 (Füllwasser: 6,0–9,0, Tab. 7). Vorübergehende Schwankungen durch Umwelteinflüsse sind möglich (§ 7.1.2). Geprüft in Tor REQ-10.
[EN] pH value of the swimming-area water from the analysis. Approximate value Tab. 8: 7.0–9.0 (fill-up water: 6.0–9.0, Tab. 7). Temporary fluctuations due to environmental influences can occur (§ 7.1.2). Checked by gate REQ-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'swimming_test_ph';
UPDATE fields x SET description = 'Herkunft des Füll- und Nachspeisewassers. Leitungs-, Brunnen- und Regenwasser sind grundsätzlich geeignet, aber: Trinkwasser kann durch die Aufbereitung zu viel Phosphor enthalten; Brunnenwasser erhöhte Nährstoffe oder Eisen; Regenwasser darf nicht direkt eingeleitet werden (Deposition auf Dächern, kein Zink/Kupfer; aus Zisternen mit Schwimmentnahme). Oberflächenwasser aus Flüssen und Seen darf nicht verwendet werden. Die Eignung ist immer zu prüfen, ggf. mit Aufbereitung (§ 7.1.1).
[EN] Source of the fill-up and top-up water. Tap, well and rainwater are all potentially suitable, but: drinking water may already contain too much phosphorus due to its purification; well water increased nutrients or iron; rainwater cannot be introduced directly (deposition on roofs, no zinc/copper; from cisterns with floating discharge). Surface water from rivers and lakes cannot be introduced. Suitability must always be checked, if necessary with purification (§ 7.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'water_source';
UPDATE fields x SET description = 'Säurekapazität KS 4,3 des Füllwassers in mmol/l (entspricht der Karbonathärte), aus der Füllwasseranalyse (Referenzverfahren Anhang 1; ggf. nach Aufbereitung). Richtwert Tab. 7: ≥ 2 mmol/l (≥ 5,6 °dH). Geprüft in Tor REQ-09.
[EN] Acid capacity KS 4.3 of the fill-up water in mmol/l (corresponds to carbonate hardness), from the fill-up water analysis (reference method Appendix 1; if applicable after purification). Approximate value Tab. 7: ≥ 2 mmol/l (≥ 5.6 dH°). Checked by gate REQ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'water_test_acid_capacity_ks43';
UPDATE fields x SET description = 'Ammoniumkonzentration des Füllwassers in mg/l aus der Analyse. Richtwert Tab. 7: ≤ 0,5 mg/l. Geprüft in Tor REQ-09.
[EN] Ammonium concentration of the fill-up water in mg/l from the analysis. Approximate value Tab. 7: ≤ 0.5 mg/l. Checked by gate REQ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'water_test_ammonium';
UPDATE fields x SET description = 'Elektrische Leitfähigkeit des Füllwassers in µS/cm bei 20 °C aus der Analyse. Richtwert Tab. 7: ≤ 1000 µS/cm at 20°C. Geprüft in Tor REQ-09.
[EN] Electrical conductivity of the fill-up water in µS/cm at 20 °C from the analysis. Approximate value Tab. 7: ≤ 1000 µS/cm at 20°C. Checked by gate REQ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'water_test_conductivity';
UPDATE fields x SET description = 'Gesamthärte (Erdalkalien) des Füllwassers in mmol/l aus der Analyse. Richtwert Tab. 7: ≥ 1,0 mmol/l, entspricht ≥ 5,6 °dH. Geprüft in Tor REQ-09.
[EN] Total hardness (alkaline earths) of the fill-up water in mmol/l from the analysis. Approximate value Tab. 7: ≥ 1.0 mmol/l, corresponding to ≥ 5.6 dH°. Checked by gate REQ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'water_test_hardness';
UPDATE fields x SET description = 'Eisenkonzentration des Füllwassers in mg/l aus der Analyse; vor allem Brunnenwasser kann hohe Eisengehalte haben (§ 7.1.1). Richtwert Tab. 7: ≤ 0,2 mg/l. Nur für Füllwasser; Tab. 8 nennt kein Eisen. Geprüft in Tor REQ-09.
[EN] Iron concentration of the fill-up water in mg/l from the analysis; well water in particular can have high iron contents (§ 7.1.1). Approximate value Tab. 7: ≤ 0.2 mg/l. Fill-up water only; Tab. 8 has no iron row. Checked by gate REQ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'water_test_iron';
UPDATE fields x SET description = 'Mangankonzentration des Füllwassers in mg/l aus der Analyse. Richtwert Tab. 7: ≤ 0,05 mg/l. Nur für Füllwasser; Tab. 8 nennt kein Mangan. Geprüft in Tor REQ-09.
[EN] Manganese concentration of the fill-up water in mg/l from the analysis. Approximate value Tab. 7: ≤ 0.05 mg/l. Fill-up water only; Tab. 8 has no manganese row. Checked by gate REQ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'water_test_manganese';
UPDATE fields x SET description = 'Nitratkonzentration des Füllwassers in mg/l aus der Analyse; Brunnenwasser kann durch landwirtschaftliche Einträge belastet sein (§ 7.1.1). Richtwert Tab. 7: ≤ 50,0 mg/l. Geprüft in Tor REQ-09.
[EN] Nitrate concentration of the fill-up water in mg/l from the analysis; well water can be loaded by agricultural runoffs (§ 7.1.1). Approximate value Tab. 7: ≤ 50.0 mg/l. Checked by gate REQ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'water_test_nitrate';
UPDATE fields x SET description = 'Orthophosphat, angegeben als P, im Füllwasser in mg/l aus der Analyse. Richtwert Tab. 7: ≤ 0,01 mg/l — gleich streng wie Tab. 8 für Typ IV/V; das Füllwasser spielt beim Erstfüllen und Nachspeisen eine sehr wichtige Rolle (§ 7.1.1). Geprüft in Tor REQ-09.
[EN] Orthophosphate, indicated as P, in the fill-up water in mg/l from the analysis. Approximate value Tab. 7: ≤ 0.01 mg/l — as strict as Tab. 8 for Types IV/V; fill-up water plays a very important role both at first filling and at top-up (§ 7.1.1). Checked by gate REQ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'water_test_orthophosphate';
UPDATE fields x SET description = 'Gesamtphosphor [P_total] des Füllwassers in mg/l aus der Analyse. Richtwert Tab. 7: ≤ 0,03 mg/l. Trinkwasser kann wegen der Aufbereitung zu hohe Phosphorwerte haben, die über das Jahr schwanken; dann ist eine weitergehende Aufbereitung nötig (§ 7.1.1). Geprüft in Tor REQ-09.
[EN] Total phosphorus [P_total] of the fill-up water in mg/l from the analysis. Approximate value Tab. 7: ≤ 0.03 mg/l. Drinking water may contain phosphorus levels too high because of the way it is purified, varying over the year; further purification is then required (§ 7.1.1). Checked by gate REQ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'water_test_p_total';
UPDATE fields x SET description = 'pH-Wert des Füllwassers aus der Analyse. Richtwert Tab. 7: 6,0–9,0. Geprüft in Tor REQ-09.
[EN] pH value of the fill-up water from the analysis. Approximate value Tab. 7: 6.0–9.0. Checked by gate REQ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'water_test_ph';
UPDATE fields x SET description = 'Register der Wasseranalysen: eine Zeile je Probe mit Datum, Entnahmeort (Füllwasser oder Schwimmbereich) und den Messwerten Ammonium, Eisen, Gesamtphosphor, Härte, Leitfähigkeit, Mangan, Nitrat, Nitrit, Orthophosphat, Säurekapazität, pH. Füllwasserzeilen werden gegen Tab. 7 verglichen (Eisen/Mangan nur hier), Schwimmbereichszeilen gegen Tab. 8 (Nitrit nur hier; P-Werte nach Teichtyp). Aus dem Register werden Anzahl (FLLNT-04-D2) und Verletzungen (FLLNT-04-D1) berechnet; die Tore REQ-09/REQ-10 prüfen weiterhin die Einzelfelder.
[EN] Register of water analyses: one row per sample with date, sampling point (fill-up water or swimming area) and the measured values ammonium, iron, total phosphorus, hardness, conductivity, manganese, nitrate, nitrite, orthophosphate, acid capacity, pH. Fill-up rows are compared with Tab. 7 (iron/manganese only there), swimming-area rows with Tab. 8 (nitrite only there; P values by pool type). The register yields the sample count (FLLNT-04-D2) and the violation count (FLLNT-04-D1); gates REQ-09/REQ-10 still check the scalar fields.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'wasserproben';
UPDATE fields x SET description = 'Berechnet (FLLNT-04-D2): Anzahl der vollständigen Zeilen im Register Wasseranalysen. Bezugsgröße für die Zahl der Verletzungen; keine Eingabe.
[EN] Computed (FLLNT-04-D2): number of complete rows in the water-analyses register. Reference quantity for the violation count; no entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'sample_count';
UPDATE fields x SET description = 'Berechnet (FLLNT-04-D1): Anzahl der Wasseranalysen, bei denen mindestens ein Messwert den Richtwert der Tab. 7 (Füllwasser) bzw. Tab. 8 (Schwimmbereich) verfehlt. Jede Verletzung verlangt nach § 7.1.2 Beobachtung der biologischen Prozesse, ggf. eine erweiterte Gesamtwasseranalyse und Maßnahmen. Keine Eingabe.
[EN] Computed (FLLNT-04-D1): number of water analyses in which at least one value misses the approximate value of Tab. 7 (fill-up water) or Tab. 8 (swimming area). Each violation calls, per § 7.1.2, for observing the biological processes, if applicable an advanced total water analysis and measures. No entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'sample_violations';
UPDATE fields x SET description = 'Wird aus Tab. 8 zum Naturteich-Typ (FLLNT-03) gefüllt: Richtwert für Gesamtphosphor im Schwimmbereich — 0,03 mg/l bei Typ I–III, 0,01 mg/l bei Typ IV und V. Vergleichswert für swimming_test_p_total; keine Eingabe.
[EN] Filled from Tab. 8 for the pool type (FLLNT-03): approximate value for total phosphorus in the swimming area — 0.03 mg/l for Types I–III, 0.01 mg/l for Types IV and V. Reference value for swimming_test_p_total; no entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'swimming_p_total_limit';
UPDATE fields x SET description = 'Wird aus Tab. 8 zum Naturteich-Typ (FLLNT-03) gefüllt: Richtwert für Orthophosphat (als P) im Schwimmbereich — 0,03 mg/l bei Typ I–III, 0,01 mg/l bei Typ IV und V. Vergleichswert für swimming_test_orthophosphate; keine Eingabe.
[EN] Filled from Tab. 8 for the pool type (FLLNT-03): approximate value for orthophosphate (as P) in the swimming area — 0.03 mg/l for Types I–III, 0.01 mg/l for Types IV and V. Reference value for swimming_test_orthophosphate; no entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.symbol = 'swimming_orthophosphate_limit';
UPDATE equations x SET description = 'Zählt die Zeilen des Registers Wasseranalysen, deren Zeilenprüfung sample_ok = 0 ergibt, d. h. mindestens ein Messwert liegt außerhalb der Richtwerte: Füllwasser gegen Tab. 7 (Ammonium ≤ 0,5; Eisen ≤ 0,2; P_total ≤ 0,03; Härte ≥ 1,0 mmol/l; Leitfähigkeit ≤ 1000 µS/cm; Mangan ≤ 0,05; Nitrat ≤ 50,0; Orthophosphat ≤ 0,01; pH 6,0–9,0; KS 4,3 ≥ 2 mmol/l), Schwimmbereich gegen Tab. 8 (P-Werte nach Typ). Ergebnis: sample_violations (Anzahl, dimensionslos).
[EN] Counts the rows of the water-analyses register whose row check gives sample_ok = 0, i.e. at least one value lies outside the approximate values: fill-up water against Tab. 7 (ammonium ≤ 0.5; iron ≤ 0.2; P_total ≤ 0.03; hardness ≥ 1.0 mmol/l; conductivity ≤ 1000 µS/cm; manganese ≤ 0.05; nitrate ≤ 50.0; orthophosphate ≤ 0.01; pH 6.0–9.0; KS 4.3 ≥ 2 mmol/l), swimming area against Tab. 8 (P values by type). Result: sample_violations (count, dimensionless).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.equation_number = 'FLLNT-04-D1';
UPDATE equations x SET description = 'Zählt alle vollständigen Zeilen des Registers Wasseranalysen. Ergebnis: sample_count (Anzahl), die Bezugsgröße zu sample_violations. Keine gedruckte Formel — reine Zählhilfe des Werkzeugs.
[EN] Counts all complete rows of the water-analyses register. Result: sample_count (number), the reference quantity for sample_violations. No printed formula — a counting aid of the tool.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.equation_number = 'FLLNT-04-D2';
UPDATE compliance_requirements x SET description = 'Besteht, wenn alle zehn Füllwasserwerte die Richtwerte der Tab. 7 einhalten: Ammonium ≤ 0,5 mg/l; Eisen ≤ 0,2 mg/l; Gesamtphosphor ≤ 0,03 mg/l; Gesamthärte ≥ 1,0 mmol/l; Leitfähigkeit ≤ 1000 µS/cm (20 °C); Mangan ≤ 0,05 mg/l; Nitrat ≤ 50,0 mg/l; Orthophosphat (als P) ≤ 0,01 mg/l; pH 6,0–9,0; Säurekapazität KS 4,3 ≥ 2 mmol/l. Einzugeben: alle water_test_*-Felder aus einer Analyse nach Anhang 1 — ggf. nach Aufbereitung. Grund: Die Eignung des Füllwassers ''must always be checked''; ungeeignetes Wasser trägt bei jedem Nachfüllen Phosphor und Nährstoffe ein (§ 7.1.1).
[EN] Passes when all ten fill-up water values meet the approximate values of Tab. 7: ammonium ≤ 0.5 mg/l; iron ≤ 0.2 mg/l; total phosphorus ≤ 0.03 mg/l; total hardness ≥ 1.0 mmol/l; conductivity ≤ 1000 µS/cm (20 °C); manganese ≤ 0.05 mg/l; nitrate ≤ 50.0 mg/l; orthophosphate (as P) ≤ 0.01 mg/l; pH 6.0–9.0; acid capacity KS 4.3 ≥ 2 mmol/l. Enter: all water_test_* fields from an analysis per Appendix 1 — if applicable after purification. Reason: the suitability of fill-up water ''must always be checked''; unsuitable water imports phosphorus and nutrients with every top-up (§ 7.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-04' AND x.code = 'REQ-09';
UPDATE fields x SET description = 'Haken, wenn der Beton die Anforderungen des § 7.2.1 erfüllt: Beton muss vor dem Einfüllen des Wassers ausgehärtet sein; Beton und Mörtel sind so einzusetzen, dass keine Kalkausfällungen entstehen; Betonanforderungen nach DIN EN 206-1; erforderlicher Potentialausgleich nach DIN VDE 0100-410. Grundlage: Lieferschein/Betonsortenverzeichnis und Ausführungsplanung. Geprüft in Tor REQ-11.
[EN] Tick when the concrete meets § 7.2.1: concrete must have hardened before filling in water; concrete and mortar must be used in a manner that prevents calcareous deposits; concrete requirements per DIN EN 206-1; required potential equalization per DIN VDE 0100-410. Basis: delivery note / concrete specification and the execution design. Checked by gate REQ-11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'concrete_spec_compliant';
UPDATE fields x SET description = 'Eluierbarer Phosphor des Filtersubstrats in mg P/kg Trockensubstanz aus dem Prüfbericht des Lieferanten oder Labors nach Anhang 2 (normativ): Elution mit 1 M HCl, Lösung-Feststoff-Verhältnis 2:1, 24 h Schütteln bei 20 ± 2 °C nach DIN 19529; A = c · V_L / m_e. Der Wert ''should not exceed 5 mg P/kg'' (§ 7.2.3; Tab. 9: ≤ 5 mg P/kg für Filtersubstrat Typ III und IV). Rückstellproben empfohlen. Geprüft in Tor REQ-12.
[EN] Elutable phosphorus of the filter substrate in mg P/kg dry substance from the supplier''s or laboratory''s test report per Appendix 2 (normative): elution with 1 M HCl, solution-solid ratio 2:1, 24 h shaking at 20 ± 2 °C based on DIN 19529; A = c · V_L / m_e. The level ''should not exceed 5 mg P/kg'' (§ 7.2.3; Tab. 9: ≤ 5 mg P/kg for filter substrate Types III and IV). Retained samples are recommended. Checked by gate REQ-12.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'filter_substrate_elutable_p';
UPDATE fields x SET description = 'Abschlämmbare Anteile (< 0,063 mm, Schluff und Ton) des Filtersubstrats in Gewichts-%, aus der Korngrößenanalyse des Lieferanten. Grenzen: ≤ 0,5 % für Substrate in schnell durchströmten Filtern (Typ IV), ≤ 2 % für alle anderen Filtersubstrate (§ 7.2.3; Tab. 9; Tab. 11 Zeile 7: ≤ 2 %; Tab. 12 Zeile 7: ≤ 0,5 %). Wird in FLLNT-10 gegen den gewählten Filtertyp geprüft.
[EN] Elutriated parts (< 0.063 mm, silt and clay) of the filter substrate in % by weight, from the supplier''s grain-size analysis. Limits: ≤ 0.5 % for substrates in quick-flow filters (Type IV), ≤ 2 % for all other filter substrates (§ 7.2.3; Tab. 9; Tab. 11 row 7: ≤ 2 %; Tab. 12 row 7: ≤ 0.5 %). Checked in FLLNT-10 against the selected filter type.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'filter_substrate_elutriated_pct';
UPDATE fields x SET description = 'Überkornanteil des Filtersubstrats in Gewichts-% (Anteil über der oberen Sieblinie), aus der Korngrößenanalyse. ''The percentage of oversized grain must not exceed 15% by weight'' (§ 7.2.3); Tab. 9, Tab. 11 Zeile 6 und Tab. 12 Zeile 6: ≤ 15 % für Typ III und IV. Wird in FLLNT-10 geprüft.
[EN] Oversized grain of the filter substrate in % by weight (share above the upper sieve line), from the grain-size analysis. ''The percentage of oversized grain must not exceed 15% by weight'' (§ 7.2.3); Tab. 9, Tab. 11 row 6 and Tab. 12 row 6: ≤ 15 % for Types III and IV. Checked in FLLNT-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'filter_substrate_oversize_pct';
UPDATE fields x SET description = 'Haken, wenn alle im Wasser oder unmittelbar daneben eingebauten Materialien keine biozide oder desinfizierende Wirkung auf die limnische Biozönose haben und nicht zu einer länger als drei Wochen andauernden Verschlechterung der Wasserqualität führen; die Richtwerte der Tab. 8 sind einzuhalten (§ 7.2). Auch Abdichtungen und Schutzlagen dürfen nicht biozid behandelt sein (§ 9.3). Grundlage: Produktdatenblätter. Geprüft in Tor REQ-11.
[EN] Tick when all materials installed in the water body or directly adjacent to it have no biocidal or disinfecting effect on the limnological biocoenosis and do not cause a negative effect on water quality lasting longer than three weeks; the approximate values of Tab. 8 must be adhered to (§ 7.2). Sealings and protective layers may not be treated with biocides either (§ 9.3). Basis: product data sheets. Checked by gate REQ-11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'materials_biocide_free';
UPDATE fields x SET description = 'Haken, wenn das Pflanzsubstrat § 7.2.4 und Tab. 9 entspricht: möglichst frei von organischen Anteilen (Fäulnis, unkontrollierte Nährstofffreisetzung), feinkörnig, Größtkorn 8 mm (Tab. 9: ''Recommended maximum grain size 8 mm''; für Überkorn, Abschlämmbares, k_f, Frost und eluierbaren P ''no requirement''); bei hohem Schluff-/Tonanteil Abdeckung mit mineralischem Material (z. B. Kies 2/8 mm); ein gewisser eluierbarer P-Anteil ist erwünscht, ggf. mit Sperrschicht. Wird in FLLNT-09/12 weiterverwendet; Tor REQ-11.
[EN] Tick when the plant substrate meets § 7.2.4 and Tab. 9: as free as possible from organic parts (decay, uncontrolled nutrient release), fine-grained, largest grain 8 mm (Tab. 9: ''Recommended maximum grain size 8 mm''; oversized grain, elutriated parts, permeability, frost and elutable P ''no requirement''); with a high silt/clay share a cover of granular mineral material (e.g. gravel 2/8 mm); a certain elutable P share is preferable, with a cap if necessary. Used by FLLNT-09/12; gate REQ-11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'plant_substrate_compliant';
UPDATE fields x SET description = 'Haken, wenn Holz und Holzwerkstoffe im und am Teich § 7.2.2 entsprechen: keine Abgabe von Gerbstoffen oder biozid wirkenden Stoffen; berücksichtigt sind Oberfläche (Rutschfestigkeit, Splittern), Festigkeits- und Dauerhaftigkeitsklasse, Quellen/Schwinden, Ausbluten von Harz, konstruktiver Holzschutz, Holzschutzmittel/Oberflächenbehandlung ohne gesundheits- oder biologieschädliche Stoffe, dauerhaft korrosionsfreie Befestigungen; Regeln: DIN EN 350, Fachregel 02 ''Balkone und Terrassen''. Geprüft in Tor REQ-11.
[EN] Tick when wood and wood substitutes in and around the pool meet § 7.2.2: no release of tanning agents or substances with a biocidal effect; considered are surface structure (slip resistance, splintering), strength and durability classes, expanding/shrinking, resin bleeding, constructive wood preservation, preservatives/surface treatment free of substances harmful to health or to the pool biology, durably corrosion-free fastenings; rules: DIN EN 350, Technical carpentry regulation 02 ''Balconies and terraces''. Checked by gate REQ-11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'wood_treatment_compliant';
UPDATE fields x SET description = 'Wählen Sie, welche Spalte der Tab. 9 für das zu prüfende Substrat gilt: ''Filter substrate natural pool type III'' (langsam durchströmter Filter), ''Filter substrate natural pool type IV'' (schnell durchströmter Filter) oder ''Plant substrate'' (Pflanzsubstrat ohne Durchströmung, in jedem Teichtyp möglich). Die Wahl füllt die sechs Anforderungsfelder *_tab9 (Größtkorn, Überkorn, Abschlämmbares, k_f, Frost, eluierbarer P). Der Naturteich-Typ aus FLLNT-03 legt die Rolle nicht allein fest.
[EN] Select which column of Tab. 9 applies to the substrate under review: ''Filter substrate natural pool type III'' (slow-flow filter), ''Filter substrate natural pool type IV'' (quick-flow filter) or ''Plant substrate'' (no flow through, possible in every pool type). The choice fills the six requirement fields *_tab9 (max. grain size, oversized grain, elutriated parts, permeability, frost, elutable P). The pool type from FLLNT-03 does not determine the role on its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'substrate_role';
UPDATE fields x SET description = 'Wird aus Tab. 9 zur gewählten Substratrolle gefüllt: ''Recommended maximum grain size'' 16 mm (Filtersubstrat Typ III), 32 mm (Filtersubstrat Typ IV), 8 mm (Pflanzsubstrat). Tab. 11/12 wiederholen ≤ 16 mm bzw. ≤ 32 mm für die Filterschicht. Vergleichswert für das gemessene Größtkorn; keine Eingabe.
[EN] Filled from Tab. 9 for the selected substrate role: ''Recommended maximum grain size'' 16 mm (filter substrate Type III), 32 mm (filter substrate Type IV), 8 mm (plant substrate). Tab. 11/12 repeat ≤ 16 mm and ≤ 32 mm for the filter layer. Reference value for the measured maximum grain; no entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'grain_size_max_tab9';
UPDATE fields x SET description = 'Wird aus Tab. 9 zur gewählten Substratrolle gefüllt: zulässiger Überkornanteil ≤ 15 Gewichts-% für Filtersubstrat Typ III und Typ IV; für Pflanzsubstrat ''no requirement'' (Feld bleibt leer). Vergleichswert für filter_substrate_oversize_pct; keine Eingabe.
[EN] Filled from Tab. 9 for the selected substrate role: permissible oversized grain ≤ 15 % by weight for filter substrate Types III and IV; for plant substrate ''no requirement'' (field stays empty). Reference value for filter_substrate_oversize_pct; no entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'oversize_max_tab9';
UPDATE fields x SET description = 'Wird aus Tab. 9 zur gewählten Substratrolle gefüllt: zulässige abschlämmbare Anteile (< 0,063 mm) ≤ 2 Gewichts-% für Filtersubstrat Typ III, ≤ 0,5 Gewichts-% für Filtersubstrat Typ IV; für Pflanzsubstrat ''no requirement'' (leer). Vergleichswert für filter_substrate_elutriated_pct; keine Eingabe.
[EN] Filled from Tab. 9 for the selected substrate role: permissible elutriated parts (< 0.063 mm) ≤ 2 % by weight for filter substrate Type III, ≤ 0.5 % by weight for filter substrate Type IV; for plant substrate ''no requirement'' (empty). Reference value for filter_substrate_elutriated_pct; no entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'fines_max_tab9';
UPDATE fields x SET description = 'Wird aus Tab. 9 zur gewählten Substratrolle gefüllt: Mindest-Durchlässigkeitsbeiwert ≥ 10⁻⁴ m/s für Filtersubstrat Typ III, ≥ 10⁻³ m/s für Filtersubstrat Typ IV; Pflanzsubstrat ''no requirement'' (leer). Die Sieblinie muss diesen k_f mit dem vorgegebenen Kornbereich erreichen; bei Abweichung ist k_f dauerhaft zu halten und die Filterstabilität zu sichern (Fußnote 1 Tab. 11/12). Vergleichswert für den k_f des Filters in FLLNT-10; keine Eingabe.
[EN] Filled from Tab. 9 for the selected substrate role: minimum permeability coefficient ≥ 10⁻⁴ m/s for filter substrate Type III, ≥ 10⁻³ m/s for filter substrate Type IV; plant substrate ''no requirement'' (empty). The grain distribution curve must achieve this permeability with the specified grain-size range; on deviation the coefficient must be maintained continuously and filter stability given (footnote 1, Tab. 11/12). Reference value for the filter''s k_f in FLLNT-10; no entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'kf_min_tab9';
UPDATE fields x SET description = 'Wird aus Tab. 9 zur gewählten Substratrolle gefüllt: Frostbeständigkeit ''is mandatory'' für Filtersubstrat Typ III und Typ IV, ''no requirement'' für Pflanzsubstrat. Der Nachweis kommt aus dem Lieferanten-Datenblatt; keine Eingabe.
[EN] Filled from Tab. 9 for the selected substrate role: frost resistance ''is mandatory'' for filter substrate Types III and IV, ''no requirement'' for plant substrate. Evidence comes from the supplier''s data sheet; no entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'frost_resistance_tab9';
UPDATE fields x SET description = 'Wird aus Tab. 9 zur gewählten Substratrolle gefüllt: höchstens 5 mg P/kg eluierbarer Phosphor für Filtersubstrat Typ III und Typ IV; Pflanzsubstrat ''no requirement'' (leer) — dort ist ein gewisser P-Anteil sogar erwünscht (§ 7.2.4). Prüfverfahren Anhang 2. Vergleichswert für filter_substrate_elutable_p (Tor REQ-12); keine Eingabe.
[EN] Filled from Tab. 9 for the selected substrate role: at most 5 mg P/kg elutable phosphorus for filter substrate Types III and IV; plant substrate ''no requirement'' (empty) — there a certain P share is even preferable (§ 7.2.4). Test method Appendix 2. Reference value for filter_substrate_elutable_p (gate REQ-12); no entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'elutable_p_max_tab9';
UPDATE compliance_requirements x SET description = 'Besteht, wenn die vier Bestätigungen Beton (§ 7.2.1), Holz (§ 7.2.2), biozidfreie Materialien (§ 7.2) und Pflanzsubstrat (§ 7.2.4, Tab. 9) angehakt sind. Grund: Materialien im oder am Wasser dürfen keine länger als drei Wochen andauernde Verschlechterung der Wasserqualität bewirken, die Richtwerte der Tab. 8 müssen eingehalten bleiben, und sie dürfen nicht biozid oder desinfizierend auf die Biozönose wirken (§ 7.2). Die Zahlenwerte der Filtersubstrate prüft REQ-12 bzw. FLLNT-10.
[EN] Passes when the four confirmations concrete (§ 7.2.1), wood (§ 7.2.2), biocide-free materials (§ 7.2) and plant substrate (§ 7.2.4, Tab. 9) are ticked. Reason: materials in or directly adjacent to the water cannot lead to a negative effect on water quality lasting longer than three weeks, the approximate values of Tab. 8 must be adhered to, and they must not have a biocidal or disinfecting effect on the biocoenosis (§ 7.2). Numeric filter-substrate limits are checked by REQ-12 and FLLNT-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.code = 'REQ-11';
UPDATE compliance_requirements x SET description = 'Besteht, wenn der eluierbare Phosphor des Filtersubstrats ≤ 5 mg P/kg ist. Einzugeben: filter_substrate_elutable_p aus einem Prüfbericht nach Anhang 2 (normativ): Elution mit 1,0 M HCl, Lösung-Feststoff-Verhältnis 2:1, 24 h im Überkopfschüttler bei 20 ± 2 °C, Probe ≤ 32 mm, Ergebnis auf Trockensubstanz; A = c · V_L / m_e in mg/kg. Grund: § 7.2.3 ''should not exceed 5 mg P/kg'' und Tab. 9 (≤ 5 mg P/kg für Filtersubstrat Typ III und IV) — das Verfahren erfasst den pflanzen- und algenverfügbaren Phosphor (Anhang 2). Für Pflanzsubstrat nennt Tab. 9 keine Anforderung.
[EN] Passes when the elutable phosphorus of the filter substrate is ≤ 5 mg P/kg. Enter: filter_substrate_elutable_p from a test report per Appendix 2 (normative): elution with 1.0 M HCl, solution-solid ratio 2:1, 24 h in an overhead shaker at 20 ± 2 °C, sample ≤ 32 mm, result on dry substance; A = c · V_L / m_e in mg/kg. Reason: § 7.2.3 ''should not exceed 5 mg P/kg'' and Tab. 9 (≤ 5 mg P/kg for filter substrate Types III and IV) — the method captures the phosphorus available to plants and algae (Appendix 2). For plant substrate Tab. 9 states no requirement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.code = 'REQ-12';
UPDATE fields x SET description = 'Bestätigung, dass der Aushub § 9.1 entspricht: Der Untergrund ist tragfähig oder wurde verdichtet bzw. verbessert (z. B. geeignete Bodenschicht), ggf. mit statischem Nachweis; bei zu erwartendem Grund- oder Schichtenwasser sind Maßnahmen wie Drainagen vorgesehen; Planung nach ATV DIN 18300, DIN 1054, DIN 18196, DIN 4020, DIN 4124, DIN EN ISO 14688-1; Aushubsohle und -böschungen sind so hergestellt, dass das vorgesehene Abdichtungsmaterial nicht beschädigt wird (§ 9.1, Verweis auf § 9.3). Tor REQ-14 blockiert ohne Haken.
[EN] Attest that the excavation complies with § 9.1: the subsoil is load-bearing or has been compacted or improved (e.g. a suitable ground layer), structurally verified where necessary; drainage or similar measures are provided where groundwater or stratum water is expected; planning per ATV DIN 18300, DIN 1054, DIN 18196, DIN 4020, DIN 4124, DIN EN ISO 14688-1; bottom and sides of the excavation are built so that the designated sealing material is not damaged (§ 9.1, cross-reference to § 9.3). Gate REQ-14 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'attest_fllnt_06_req_14';
UPDATE fields x SET description = 'Bestätigung, dass der Schwimmbereich § 9.5 entspricht: Oberflächen (Boden, Wände, Einbauten) leicht zu pflegen und zu reinigen, keine scharfen Kanten, möglichst keine Pflanzen (§ 9.5.1); Bodenbeläge, Stufen und Leitern trittsicher und rutschhemmend, Boden auch im gefüllten Zustand reinigbar, Sand/Kies nur gewaschen, Bodengefälle ohne Materialwanderung (§ 9.5.2); mindestens ein Ein-/Ausstieg, rutschhemmend, Stege ohne Behinderung der Reinigung, Metallleitern nach DIN VDE 0100-702 geerdet; Sprungbretter nach DIN EN 13451-10 / DGUV 107-001 (§ 9.5.3). Tor REQ-18 blockiert ohne Haken.
[EN] Attest that the swimming area complies with § 9.5: surfaces (bottom, walls, installed components) easy to maintain and clean, no sharp edges, preferably no plants (§ 9.5.1); ground coverings, steps and ladders safe to walk on and slip resistant, bottom cleanable even when filled, only washed sand/gravel, bottom slope without shifting of material (§ 9.5.2); at least one entry/exit point, non-slip, walkway supports not hindering cleaning, metal ladders earthed per DIN VDE 0100-702; diving boards per DIN EN 13451-10 / DGUV 107-001 (§ 9.5.3). Gate REQ-18 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'attest_fllnt_06_req_18';
UPDATE fields x SET description = 'Größte Wassertiefe im Schwimmbereich in m, aus dem Schnitt der Ausführungsplanung. Die Richtlinie macht keine allgemeingültige Vorgabe, empfiehlt aber für Typ I bis III eine Wassertiefe > 2 m (gegen Verlandung und für mehr Wasservolumen); flachere Tiefen erhöhen den Pflegeaufwand, größere Volumen dämpfen Temperaturschwankungen (§ 8.2.1). Wird in FLLNT-07 und FLLNT-10 weiterverwendet.
[EN] Maximum water depth in the swimming area in m, from the section of the execution design. The guideline makes no generally applicable specification but recommends for Types I to III a water depth > 2 m (to avoid silting and to enlarge the water volume); shallower depths increase the maintenance effort, larger volumes limit temperature fluctuations (§ 8.2.1). Used by FLLNT-07 and FLLNT-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'pool_depth_max';
UPDATE fields x SET description = 'Summe der besonnten, überstauten Teichflächen in m² — Bodenfläche plus Unterwasser-Wandflächen des Schwimmbereichs (aus Grundriss und Schnitt; EQ-PUWS berechnet sie aus Boden- und Wandfläche). Für Typ IV soll die besiedelbare Kornoberfläche des Filtermaterials mindestens das 50-Fache dieser Flächen betragen (§ 10.2.3, Tab. 5); Beispiel Anhang 5: 50 m² Boden + 45 m² Wand = 95 m², × 50 = 4750 m² Filteroberfläche. Wird in FLLNT-10 und FLLNT-11 weiterverwendet.
[EN] Sum of the pool surfaces exposed to light and inundated in m² — bottom area plus submerged wall areas of the swimming area (from plan and section; EQ-PUWS computes it from ground and wall area). For Type IV the colonisable grain surface of the filter material should amount to at least 50 times these surfaces (§ 10.2.3, Tab. 5); example Appendix 5: 50 m² ground + 45 m² wall = 95 m², × 50 = 4750 m² filter surface. Used by FLLNT-10 and FLLNT-11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'pool_underwater_surface';
UPDATE fields x SET description = 'Wasserfläche des Regenerationsbereichs in m² aus dem Flächenplan — der Bereich zur biologischen, physikalischen und physikalisch-chemischen Wasserreinigung, der Schwimmern nicht zugänglich ist, bestehend aus Pflanzzone und/oder Filterzone samt Wasser darüber (§ 3). Seine Größe hängt vom Teichtyp ab (§ 8.2.2 → § 5, Tab. 1: ≥ 50 % Typ I/II, ≥ 30 % Typ III). Voraussetzung der Wirksamkeit ist eine vollständige Durchströmung; Kontrollschächte und Probenahmestellen werden empfohlen (§ 9.6). Wird in FLLNT-09, 10, 15 verwendet.
[EN] Water surface of the regeneration area in m² from the area plan — the area used for biological, physical and physical/chemical purification of the water which is not accessible to swimmers, consisting of the plant zone and/or filtration zone and the water therein (§ 3). Its size depends on the pool type (§ 8.2.2 → § 5, Tab. 1: ≥ 50 % Types I/II, ≥ 30 % Type III). A fully engaged flow is a prerequisite for its efficacy; inspection shafts and sample points are recommended (§ 9.6). Used by FLLNT-09, 10, 15.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'regeneration_area_m2';
UPDATE fields x SET description = 'Fläche der Ergänzungsbereiche in m² — Flächen, die nicht unmittelbar zum Naturteich gehören, sondern seiner Nutzung dienen: Wege und Zugänge, Ruhe- und Liegeflächen, Kinderspielflächen (§ 3). Zugänge müssen trittsicher und rutschhemmend sein und so gestaltet, dass kein Schmutz in den Teich eingetragen wird (§ 8.2.3). Zählt nicht zur Wasserfläche und nicht zum Regenerationsanteil.
[EN] Area of the supplementary areas in m² — areas which do not belong directly to the natural swimming pool but are added for its use: paths and access routes, rest areas and areas for lying down, playing areas for children (§ 3). Access options must be safe to walk on with a non-slip surface and designed to prevent dirt from being brought into the pool (§ 8.2.3). Not part of the water area and not counted in the regeneration share.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'supplementary_area_m2';
UPDATE fields x SET description = 'Wasserfläche des Schwimmbereichs in m² aus dem Flächenplan — der zum Schwimmen bestimmte Bereich einschließlich Schwimmer-/Nichtschwimmerzonen und Einstiege (§ 3). Richtwert: mindestens 8,0 × 4,0 m (4 × 1,5 m Schwimmzüge + 2,0 m Körperlänge); bei runden Becken Durchmesser mindestens 5,0 m; andere Größen sind möglich (§ 8.2.1). Schwimm- und Regenerationsbereich müssen durch eine mindestens überstaute Barriere getrennt sein (§ 9.2). Wird in FLLNT-07, 10, 15 verwendet.
[EN] Water surface of the swimming area in m² from the area plan — the area designated for swimming, including areas for swimmers and non-swimmers and entry points (§ 3). Guide value: at least 8.0 × 4.0 m (4 × 1.5 m strokes + 2.0 m body length); for a round pool a minimum diameter of 5.0 m; other sizes are possible (§ 8.2.1). Swimming and regeneration areas must be separated by at least an inundated barrier (§ 9.2). Used by FLLNT-07, 10, 15.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'swimming_area_m2';
UPDATE fields x SET description = 'Gesamtwasserfläche des Naturteichs in m² — Schwimmbereich plus Regenerationsbereich, die beiden Teile, aus denen die Richtlinie den Schwimmteich definiert (§ 3 ''Natural swimming pool''); Tab. 2–6 beziehen den Regenerationsanteil auf diese ''total water area''. Ergänzungsflächen (Wege, Liegeflächen) sind keine Wasserfläche. Das Register ''Zonen'' summiert in total_pool_area_calc (D1) alle Zeilen einschließlich Ergänzungsflächen; beide Werte stimmen nur überein, wenn keine Ergänzungszeile eingetragen ist. Tor REQ-13 verlangt den Wert.
[EN] Total water area of the natural pool in m² — swimming area plus regeneration area, the two parts from which the guideline defines the natural swimming pool (§ 3 ''Natural swimming pool''); Tab. 2–6 relate the regeneration share to this ''total water area''. Supplementary areas (paths, rest areas) are not water area. The ''zones'' register sums all rows including supplementary areas in total_pool_area_calc (D1); the two values agree only when no supplementary row is entered. Gate REQ-13 requires the value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'total_pool_area_m2';
UPDATE fields x SET description = 'Besiedelbare Bodenfläche des Schwimmbereichs in m² (Grundriss), eine der beiden Eingaben von EQ-PUWS für die Unterwasserfläche. Beispiel 2 in Anhang 5: Becken 5 × 10 m, ''Ground area: 50 m²''. Nur für die 50-fach-Regel des Typs IV von Bedeutung (§ 10.2.3).
[EN] Colonisable ground area of the swimming area in m² (plan), one of the two inputs of EQ-PUWS for the underwater surface. Example 2 in Appendix 5: pool 5 × 10 m, ''Ground area: 50 m²''. Relevant only for the 50-times rule of Type IV (§ 10.2.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'pool_ground_area_m2';
UPDATE fields x SET description = 'Unter Wasser liegende Wandfläche des Schwimmbereichs in m² (Umfang × Wassertiefe aus Grundriss und Schnitt), zweite Eingabe von EQ-PUWS. Beispiel 2 in Anhang 5: Becken 5 × 10 m, Tiefe 1,5 m, ''Wall area: 45 m²''. Nur für die 50-fach-Regel des Typs IV von Bedeutung (§ 10.2.3).
[EN] Submerged wall area of the swimming area in m² (perimeter × water depth from plan and section), second input of EQ-PUWS. Example 2 in Appendix 5: pool 5 × 10 m, depth 1.5 m, ''Wall area: 45 m²''. Relevant only for the 50-times rule of Type IV (§ 10.2.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'pool_submerged_wall_area_m2';
UPDATE fields x SET description = 'Register der Teilflächen: eine Zeile je Zone mit Art (Schwimmbereich, Regenerationsbereich, Ergänzungsfläche), Fläche in m², Wassertiefe, Boden- und Wandfläche unter Wasser sowie — bei Regenerationszonen — der Aufbereitungstechnik (submers/emers hydrobotanisch, Substratfilter langsam/schnell, Technikeinheit). Daraus werden Gesamtfläche (D1), Regenerationsanteil an der Wasserfläche (D2, nur Schwimm- + Regenerationszonen), Unterwasserfläche (D3) und der submerse Anteil des Regenerationsbereichs (D4, Tab. 2/3 ''at least half'') berechnet. Begriffe nach § 3.
[EN] Register of partial areas: one row per zone with kind (swimming area, regeneration area, supplementary area), area in m², water depth, ground and wall area under water and — for regeneration zones — the purification technique (submerged/emersed hydrobotanical, slow/quick substrate filter, technical unit). It yields the total area (D1), the regeneration share of the water area (D2, swimming + regeneration zones only), the underwater surface (D3) and the submerged share of the regeneration area (D4, Tab. 2/3 ''at least half''). Terms per § 3.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'zonen';
UPDATE fields x SET description = 'Berechnet (FLLNT-06-D1): Summe der Flächen aller Zeilen des Registers ''Zonen'' in m² — Schwimm-, Regenerations- und Ergänzungsflächen. Achtung: Ergänzungsflächen gehören nach § 3 nicht zur Wasserfläche; für den Regenerationsanteil zählt D2 nur Schwimm- + Regenerationszonen. Keine Eingabe.
[EN] Computed (FLLNT-06-D1): sum of the areas of all rows of the ''zones'' register in m² — swimming, regeneration and supplementary areas. Note: supplementary areas are not water area per § 3; for the regeneration share D2 counts swimming + regeneration zones only. No entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'total_pool_area_calc';
UPDATE fields x SET description = 'Berechnet (FLLNT-06-D2): Anteil des Regenerationsbereichs an der Gesamtwasserfläche in % = Σ Regenerationszonen ÷ Σ (Schwimm- + Regenerationszonen) × 100, entsprechend ''Regeneration area in % of the total water area'' in Tab. 2–6. Vergleichswert: Tab. 1 ≥ 50 % (Typ I/II), ≥ 30 % (Typ III); Tab. 2/3 ''> 50%''. Zur Kontrolle des manuell eingegebenen Anteils in FLLNT-03 (Tor REQ-07). Keine Eingabe.
[EN] Computed (FLLNT-06-D2): share of the regeneration area in the total water area in % = Σ regeneration zones ÷ Σ (swimming + regeneration zones) × 100, matching ''Regeneration area in % of the total water area'' in Tab. 2–6. Reference: Tab. 1 ≥ 50 % (Types I/II), ≥ 30 % (Type III); Tab. 2/3 ''> 50%''. For cross-checking the share entered manually in FLLNT-03 (gate REQ-07). No entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'regeneration_share_calc';
UPDATE fields x SET description = 'Berechnet (FLLNT-06-D3): Summe der Unterwasserflächen (Boden + Wände unter Wasser) aller Zonen-Zeilen in m². Entspricht der ''surface that can be colonized'' des Beispiels 2 in Anhang 5 (50 + 45 = 95 m²), die für Typ IV mit 50 multipliziert die erforderliche Filteroberfläche ergibt (§ 10.2.3). Keine Eingabe.
[EN] Computed (FLLNT-06-D3): sum of the underwater surfaces (ground + walls under water) of all zone rows in m². Corresponds to the ''surface that can be colonized'' of Example 2 in Appendix 5 (50 + 45 = 95 m²), which multiplied by 50 gives the required filter surface for Type IV (§ 10.2.3). No entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'pool_underwater_surface_calc';
UPDATE fields x SET description = 'Berechnet (FLLNT-06-D4): Anteil der Regenerationszonen mit submersem hydrobotanischem System an allen Regenerationszonen in %. Tab. 2 (Typ I) und Tab. 3 (Typ II) verlangen ''therefrom at least half as submerged hydrobotanical system'', also ≥ 50 % — Tor REQ-37. Ohne Regenerationszeile nicht berechenbar. Keine Eingabe.
[EN] Computed (FLLNT-06-D4): share of regeneration zones with a submerged hydrobotanical system in all regeneration zones in %. Tab. 2 (Type I) and Tab. 3 (Type II) require ''therefrom at least half as submerged hydrobotanical system'', i.e. ≥ 50 % — gate REQ-37. Not computable without a regeneration row. No entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'submerged_hydrobot_share_calc';
UPDATE fields x SET description = 'Gesamtwasservolumen des Naturteichs in m³ (Schwimm- und Regenerationsbereich), aus Flächen und Tiefen der Ausführungsplanung. Bezugsgröße der Filterbeschickung: Tab. 4 (Typ III) ''filter feed rate > 25% of the total water volume/day'', Tab. 5 (Typ IV) ''> 80% of the total water volume/day'', Tab. 6 (Typ V) ''filtration rate > 80 % …/day'' — geprüft in FLLNT-11. Zur Plausibilität: empfohlen sind mindestens 10 m³ je Nutzer (§ 6.5).
[EN] Total water volume of the natural pool in m³ (swimming and regeneration areas), from the areas and depths of the execution design. Reference quantity for the filter feed: Tab. 4 (Type III) ''filter feed rate > 25% of the total water volume/day'', Tab. 5 (Type IV) ''> 80% of the total water volume/day'', Tab. 6 (Type V) ''filtration rate > 80 % …/day'' — checked in FLLNT-11. Plausibility: at least 10 m³ per user is recommended (§ 6.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'total_water_volume_m3';
UPDATE equations x SET description = 'pool_underwater_surface = pool_ground_area_m2 + pool_submerged_wall_area_m2 — besiedelbare Unterwasserfläche (m²) = Bodenfläche (m²) + Unterwasser-Wandfläche (m²). Nachgerechnet aus Beispiel 2 in Anhang 5: ''Ground area 50 m²'' + ''Wall area 45 m²'' = ''Total 95 m²''. Das Ergebnis ist die Bezugsfläche der 50-fach-Regel für die Filteroberfläche bei Typ IV (§ 10.2.3; FLLNT-10/11).
[EN] pool_underwater_surface = pool_ground_area_m2 + pool_submerged_wall_area_m2 — colonisable underwater surface (m²) = ground area (m²) + submerged wall area (m²). Reproduces Example 2 in Appendix 5: ''Ground area 50 m²'' + ''Wall area 45 m²'' = ''Total 95 m²''. The result is the reference surface of the 50-times rule for the filter surface in Type IV (§ 10.2.3; FLLNT-10/11).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.equation_number = 'EQ-PUWS';
UPDATE equations x SET description = 'total_pool_area_calc = Σ area_m2 über alle Zeilen des Registers ''Zonen'' (m²) — Schwimm-, Regenerations- und Ergänzungsflächen zusammen. Dient als Gesamtfläche des Blatts; für den Regenerationsanteil nach Tab. 2–6 (''of the total water area'') werden Ergänzungsflächen in D2 ausgeschlossen, da sie nach § 3 nicht zum Teich gehören.
[EN] total_pool_area_calc = Σ area_m2 over all rows of the ''zones'' register (m²) — swimming, regeneration and supplementary areas together. Serves as the sheet''s total area; for the regeneration share per Tab. 2–6 (''of the total water area'') D2 excludes supplementary areas, since per § 3 they do not belong to the pool.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.equation_number = 'FLLNT-06-D1';
UPDATE equations x SET description = 'regeneration_share_calc = Σ area_m2 (Zone = Regeneration) × 100 ÷ Σ area_m2 (Zone = Schwimmen oder Regeneration), in %. Setzt ''Regeneration area in % of the total water area'' (Tab. 2–6) um; Ergänzungsflächen bleiben außen vor (§ 3). Vergleich mit Tab. 1: ≥ 50 % für Typ I/II, ≥ 30 % für Typ III (Tab. 2/3: ''> 50%''); Typ IV/V ohne Prozentvorgabe. Ergebnis zur Kontrolle von regeneration_area_share (REQ-07).
[EN] regeneration_share_calc = Σ area_m2 (zone = regeneration) × 100 ÷ Σ area_m2 (zone = swimming or regeneration), in %. Implements ''Regeneration area in % of the total water area'' (Tab. 2–6); supplementary areas are left out (§ 3). Compare with Tab. 1: ≥ 50 % for Types I/II, ≥ 30 % for Type III (Tab. 2/3: ''> 50%''); Types IV/V without a percentage. Result cross-checks regeneration_area_share (REQ-07).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.equation_number = 'FLLNT-06-D2';
UPDATE equations x SET description = 'pool_underwater_surface_calc = Σ underwater_m2 über alle Zonen-Zeilen (m²) — Boden- plus Wandfläche unter Wasser je Zone, aufsummiert. Entspricht Anhang 5 Beispiel 2: ''Ground area 50 m²'' + ''Wall area 45 m²'' = 95 m²; × 50 = 4750 m² erforderliche besiedelbare Filteroberfläche bei Typ IV (§ 10.2.3). Ergebnis für FLLNT-10/11.
[EN] pool_underwater_surface_calc = Σ underwater_m2 over all zone rows (m²) — ground plus wall area under water per zone, summed. Matches Appendix 5 Example 2: ''Ground area 50 m²'' + ''Wall area 45 m²'' = 95 m²; × 50 = 4750 m² required colonisable filter surface for Type IV (§ 10.2.3). Result feeds FLLNT-10/11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.equation_number = 'FLLNT-06-D3';
UPDATE equations x SET description = 'submerged_hydrobot_share_calc = Σ area_m2 (Regenerationszonen mit Technik ''hydrobotanical_submergent'') × 100 ÷ Σ area_m2 (alle Regenerationszonen), in %. Setzt die Forderung der Tab. 2 (Typ I) und Tab. 3 (Typ II) um: vom Regenerationsbereich ''therefrom at least half as submerged hydrobotanical system''. Ohne Regenerationszeile Division durch null — nicht berechenbar. Ergebnis für Tor REQ-37.
[EN] submerged_hydrobot_share_calc = Σ area_m2 (regeneration zones with technique ''hydrobotanical_submergent'') × 100 ÷ Σ area_m2 (all regeneration zones), in %. Implements the requirement of Tab. 2 (Type I) and Tab. 3 (Type II): of the regeneration area ''therefrom at least half as submerged hydrobotanical system''. Without a regeneration row it divides by zero — not computable. Result feeds gate REQ-37.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.equation_number = 'FLLNT-06-D4';
UPDATE compliance_requirements x SET description = 'Besteht, wenn Gesamtwasserfläche, Regenerationsfläche und Schwimmfläche eingetragen sind (Zahlenwerte, nicht leer). Grund: § 8.2 verlangt die Bemessung von Schwimmbereich (Richtwert ≥ 8,0 × 4,0 m bzw. Ø 5,0 m, § 8.2.1), Regenerationsbereich (nach Teichtyp, § 8.2.2 → Tab. 1) und Ergänzungsflächen (§ 8.2.3); Anhang 3 nennt ''Space requirements – minimum sizes'' für alle drei. Die Größenprüfung selbst erfolgt in REQ-07 (Anteil) und FLLNT-09/10.
[EN] Passes when total water area, regeneration area and swimming area are entered (numeric, not empty). Reason: § 8.2 requires the sizing of the swimming area (guide ≥ 8.0 × 4.0 m or Ø 5.0 m, § 8.2.1), the regeneration area (by pool type, § 8.2.2 → Tab. 1) and the supplementary areas (§ 8.2.3); Appendix 3 lists ''Space requirements – minimum sizes'' for all three. The size check itself happens in REQ-07 (share) and FLLNT-09/10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.code = 'REQ-13';
UPDATE compliance_requirements x SET description = 'Besteht, wenn der Nachweis § 9.1 angehakt ist. Dafür muss der Untergrund tragfähig sein oder verdichtet/verbessert werden (ggf. mit statischem Nachweis), bei Grund- oder Schichtenwasser müssen Maßnahmen wie Drainagen vorgesehen sein, die Regeln ATV DIN 18300, DIN 1054, DIN 18196, DIN 4020, DIN 4124 und DIN EN ISO 14688-1 sind einzuhalten, und Sohle wie Böschungen des Aushubs dürfen das vorgesehene Abdichtungsmaterial nicht beschädigen (§ 9.1, § 9.3).
[EN] Passes when the attestation § 9.1 is ticked. This requires the subsoil to be load-bearing or compacted/improved (structurally verified where necessary), drainage or similar measures where groundwater or stratum water is expected, compliance with ATV DIN 18300, DIN 1054, DIN 18196, DIN 4020, DIN 4124 and DIN EN ISO 14688-1, and an excavation surface (bottom and sides) that does not damage the designated sealing material (§ 9.1, § 9.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.code = 'REQ-14';
UPDATE compliance_requirements x SET description = 'Besteht, wenn der Nachweis § 9.5.1–3 angehakt ist. Dafür müssen die Oberflächen des Schwimmbereichs leicht zu pflegen sein, keine scharfen Kanten und möglichst keine Pflanzen aufweisen (§ 9.5.1); Bodenbeläge, Stufen und Leitern trittsicher und rutschhemmend sein, der Boden im gefüllten Zustand reinigbar, Sand/Kies gewaschen (§ 9.5.2); mindestens ein Ein-/Ausstieg vorhanden, Metallleitern nach DIN VDE 0100-702 geerdet, Sprungbretter nach DIN EN 13451-10 / DGUV 107-001 (§ 9.5.3).
[EN] Passes when the attestation § 9.5.1–3 is ticked. This requires surfaces of the swimming area that are easy to maintain, without sharp edges and preferably without plants (§ 9.5.1); ground coverings, steps and ladders safe to walk on and slip resistant, the bottom cleanable when filled, washed sand/gravel only (§ 9.5.2); at least one entry/exit point, metal ladders earthed per DIN VDE 0100-702, diving boards per DIN EN 13451-10 / DGUV 107-001 (§ 9.5.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.code = 'REQ-18';
UPDATE compliance_requirements x SET description = 'Gilt nur für Typ I und II. Besteht, wenn der berechnete submerse Anteil (FLLNT-06-D4) mindestens 50 % beträgt — genau die Hälfte besteht. Einzugeben: im Register ''Zonen'' mindestens eine Regenerationszeile mit Fläche und Aufbereitungstechnik; die Zeilen mit ''Hydrobotanik (submers)'' zählen. Grund: Tab. 2 (Typ I) und Tab. 3 (Typ II) fordern beim Regenerationsbereich ''therefrom at least half as submerged hydrobotanical system'', weil submerse Makrophyten dort die Hauptreinigung leisten (''submerged macrophytes +++'').
[EN] Applies only to Types I and II. Passes when the computed submerged share (FLLNT-06-D4) is at least 50 % — exactly half passes. Enter: in the ''zones'' register at least one regeneration row with area and purification technique; rows with ''Hydrobotanical (submergent)'' count. Reason: Tab. 2 (Type I) and Tab. 3 (Type II) require of the regeneration area ''therefrom at least half as submerged hydrobotanical system'', because submerged macrophytes do the main purification there (''submerged macrophytes +++'').' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.code = 'REQ-37';
UPDATE fields x SET description = 'Beschreiben Sie, wie Schwimm- und Regenerationsbereich getrennt sind (z. B. Erdmodellierung, Holz, Naturstein, Beton, Werkstein oder Kunststoff-/Edelstahlelemente). §9.2 verlangt mindestens eine überstaute Barriere („inundated barrier“), die dauerhaft standsicher ist und das Abrutschen von Schüttungen und Substraten in den Schwimmbereich verhindert; bei Typ I–III muss sie Turbulenzen und Wasserbewegung im Regenerationsbereich minimieren, Typ IV/V erlauben andere Lösungen. Tor REQ-15 verlangt einen Eintrag.
[EN] Describe how the swimming and regeneration areas are separated (e.g. earth modelling, wood, natural stone, concrete, dimension stone or synthetic/stainless-steel elements). §9.2 requires at least an inundated barrier that is structurally durable and stable and prevents rock fill and substrates from slipping into the swimming area; in types I–III it must minimise turbulence and water movement in the regeneration area, types IV/V allow other designs. Gate REQ-15 needs an entry.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'area_separation_method';
UPDATE fields x SET description = 'Beschreiben Sie die Ausbildung des Beckenrandes: wie die Dichtung geschützt ist (z. B. mineralische Abdeckung mit Korngröße > 8 mm oder feste Einfassung), wie eine Kapillarsperre mit verschleißfester Umrandung den Wasseraustritt in die Umgebung verhindert und wie Oberflächenwasser baulich ferngehalten wird (Rinnen, Drainage, Gefälle). Der Rand muss dauerhaft standsicher sein und die vorgesehenen Lasten tragen (§9.4). Tor REQ-17 verlangt einen Eintrag; die Zahlenwerte stehen in den beiden Nachbarfeldern.
[EN] Describe the pool edge: how the sealing is protected (e.g. mineral cover with grain size > 8 mm or solid edging/enclosure), how a capillary block with a hard-wearing surround prevents water discharge into the surroundings, and how surface water is kept out structurally (gutters, drainage systems, gradients). The edge must be permanently stable and withstand the intended loads (§9.4). Gate REQ-17 needs an entry; the numeric limits sit in the two neighbouring fields.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'edge_design';
UPDATE fields x SET description = 'Betrag der größten Abweichung der Randenden von der geplanten Sollhöhe in mm, aus dem Nivellement der fertigen Beckenkante. §9.4 lässt an den Enden der Kanten höchstens +/- 10 mm zu; Tor REQ-31 prüft ≤ 10 mm.
[EN] Magnitude of the largest deviation of the edge ends from the planned nominal height in mm, from the levelling survey of the finished pool edge. §9.4 allows a maximum deviation of +/- 10 mm at the ends of the edges; gate REQ-31 checks ≤ 10 mm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'edge_height_tolerance_mm';
UPDATE fields x SET description = 'Beschreiben Sie Ein-/Ausstiege, Stege und ggf. Sprunganlagen im Schwimmbereich. §9.5.3: trittsicher und rutschhemmend, mindestens eine Ein-/Ausstiegsstelle, Stegstützen so, dass sie die Reinigung möglichst wenig behindern; Ein-/Ausstiegsleitern aus Metall nach DIN VDE 0100-702 erden. Für Sprungbretter in Privatbädern gibt es keine eigenen Vorgaben – empfohlen werden die Sicherheitsmaße nach DIN EN 13451-10 und DGUV-Regel 107-001. Die Anzahl der Einstiege gehört in das Zählfeld (REQ-39).
[EN] Describe entry/exit points, walkways and any diving boards in the swimming area. §9.5.3: safe to walk on with a non-slip finish, at least one entry/exit point, walkway supports arranged to hinder cleaning as little as possible; metal entry/exit ladders earthed per DIN VDE 0100-702. No specific requirements exist for diving boards in private pools; the safety dimensions of DIN EN 13451-10 and DGUV rule 107-001 are recommended. The number of entry points goes in the count field (REQ-39).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'entry_exit_provision';
UPDATE fields x SET description = 'Tiefe des Aushubs in m unter Gelände, aus den Ausführungsplänen. Die Richtlinie nennt keinen Zahlenwert; §9.1 verlangt tragfähigen (sonst verdichteten oder verbesserten) Baugrund, ggf. einen statischen Nachweis, Maßnahmen wie Drainagen bei Grund- oder Schichtenwasser und eine Aushubsohle/-wände, die das Dichtungsmaterial nicht beschädigen (ATV DIN 18300, DIN 1054, DIN 18196, DIN 4020, DIN 4124, DIN EN ISO 14688-1). Nur Dokumentation, keine Prüfung.
[EN] Excavation depth in m below ground, from the construction drawings. The guideline prints no numeric value; §9.1 requires load-bearing (otherwise compacted or improved) subsoil, structural verification if necessary, measures such as drainage where groundwater or stratum water is expected, and an excavation surface (bottom and sides) that cannot damage the sealing material (ATV DIN 18300, DIN 1054, DIN 18196, DIN 4020, DIN 4124, DIN EN ISO 14688-1). Documentation only, no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'excavation_depth';
UPDATE fields x SET description = 'Senkrechter Abstand in cm vom dauerhaft gehaltenen Wasserspiegel bis zur Oberkante des Dichtungssystems, aus Planung oder Aufmaß. §9.4: Der Wasserspiegel muss – je nach erwartetem Wellenschlag – ständig mindestens 5 cm unter der Dichtungsoberkante liegen; das gilt nicht für technische Einbauten zur Wasserentnahme. Tor REQ-31 prüft ≥ 5 cm.
[EN] Vertical distance in cm from the consistently held water level to the upper edge of the sealing system, from the design or survey. §9.4: depending on the expected wash of the waves, the water level must remain consistently at least 5 cm below the upper edge of the sealing system; this does not apply to technical equipment installed for water extraction. Gate REQ-31 checks ≥ 5 cm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'freeboard_water_to_seal';
UPDATE fields x SET description = 'Bodenbelag des Schwimmbereichs. §9.5.2: Beläge einschließlich Stufen und Leitern müssen trittsicher und rutschhemmend sein; der Beckenboden muss auch im gefüllten Zustand mit einem geeigneten Gerät zu reinigen sein; für Sand- und Kiesflächen nur gewaschenes Material, Bodenneigung so, dass sich Material möglichst nicht verlagert. Die Optionen Kies, Sand, Mörtel/Estrich, Kunststoffmatte, Andere sind eine Auswahlhilfe der Software – die Richtlinie nennt auf dieser Seite nur Sand und Kies ausdrücklich.
[EN] Ground covering of the swimming area. §9.5.2: coverings including steps on stairs and ladders must be safe to walk on and slip resistant; the pool bottom must be cleanable with a suitable device even when the pool is filled; only washed material for sand and gravel areas, with a bottom slope that largely prevents shifting of material. The options gravel, sand, mortar/screed, plastic mat, other are a software selection aid – the guideline names only sand and gravel explicitly on this page.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'ground_covering_type';
UPDATE fields x SET description = 'Bestätigen Sie, dass Dichtung und Schutzlagen nicht biozid ausgerüstet sind und dass sich auf der Dichtungsoberfläche ein Biofilm bilden kann – §9.3 lässt nur solche Dichtungen zu („only sealings that allow biofilm to form“). Grundlage: Datenblatt/Herstellerangaben des Dichtungssystems. Tor REQ-32 blockiert ohne Haken.
[EN] Confirm that the sealing and protective layers are not treated with biocides and that biofilm can form on the sealing surface – §9.3 permits only sealings that allow biofilm to form. Basis: the data sheet / manufacturer''s information for the sealing system. Gate REQ-32 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'sealing_biocide_free_biofilm_ok';
UPDATE fields x SET description = 'Art der Abdichtung des Beckens. §9.3: dauerhaft dicht gegen den Untergrund (kein Wasseraustritt, kein Eintritt von Grund-/Schichtenwasser); das System richtet sich nach den FLL-„Empfehlungen … Abdichtungssysteme für Gewässer …“; Dicke nach Material, Größe/Tiefe und Nutzungsintensität; wurzelfest, chemisch und biologisch beständig, Schutzlagen unter der Dichtung, Schutz vor mechanischer Beschädigung bei Schüttungen; Edelstahlbecken nach VDE 0100-702 erden. Bei EPDM/PVC werden die Faltenfelder eingeblendet (REQ-38). Die Optionen sind eine Auswahlhilfe der Software; Tor REQ-16 verlangt eine Wahl.
[EN] Type of basin sealing. §9.3: durably sealed against the subsoil (no water escaping, no groundwater or stratum water entering); the system follows the FLL ''Recommendations … sealing systems for bodies of water …''; thickness depends on material, size/depth and intensity of use; root resistant, chemically and biologically resistant, protective layers beneath the sealing, protection against mechanical damage under granular materials; stainless-steel pools grounded per VDE 0100-702. For EPDM/PVC the crease fields appear (REQ-38). The options are a software selection aid; gate REQ-16 needs a choice.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'sealing_type';
UPDATE fields x SET description = 'Nur bei EPDM-/PVC-Folie: Haken, wenn die Folie in Sichtbereichen auf ebenem, standfestem Untergrund aus Beton liegt. §9.3 verlangt dort eine faltenfreie Verlegung („crease-free on level and stable subsoil“); mit dem Haken gilt der faltenfreie Fall und Tor REQ-38 ist erfüllt. Ohne Betonuntergrund Haken leer lassen und die drei Faltenmaße plus die Kreuzungsfrage ausfüllen.
[EN] Only for EPDM/PVC liners: tick when the liner in visible areas lies on level, stable subsoil made of concrete. §9.3 requires a crease-free installation there; with the tick the crease-free case applies and gate REQ-38 passes. Without a concrete subsoil leave it unticked and fill in the three crease dimensions and the crossing question.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'liner_on_concrete_base';
UPDATE fields x SET description = 'Höhe der höchsten Falte in cm, gemessen am gefüllten Teich in Sichtbereichen (nur ohne Betonuntergrund). §9.3 toleriert Falten mit einer Höhe bis 1,0 cm; Tor REQ-38 prüft ≤ 1,0 cm. Falten dürfen den Einsatz von Wartungsgeräten nicht behindern.
[EN] Height of the highest crease in cm, measured on the filled pool in visible areas (only without a concrete subsoil). §9.3 tolerates creases with a height of up to 1.0 cm; gate REQ-38 checks ≤ 1.0 cm. Creases cannot hinder the use of maintenance equipment.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'crease_height_max_cm';
UPDATE fields x SET description = 'Länge der längsten Falte in m, gemessen am gefüllten Teich in Sichtbereichen (nur ohne Betonuntergrund). §9.3 toleriert Falten mit einer Länge bis 2,0 m; Tor REQ-38 prüft ≤ 2,0 m.
[EN] Length of the longest crease in m, measured on the filled pool in visible areas (only without a concrete subsoil). §9.3 tolerates creases with a length of up to 2.0 m; gate REQ-38 checks ≤ 2.0 m.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'crease_length_max_m';
UPDATE fields x SET description = 'Kleinster Abstand zwischen zwei Falten in m, gemessen am gefüllten Teich (nur ohne Betonuntergrund). §9.3 verlangt einen Mindestabstand von 2,0 m zwischen den Falten; Tor REQ-38 prüft ≥ 2,0 m.
[EN] Smallest distance between two creases in m, measured on the filled pool (only without a concrete subsoil). §9.3 requires a minimum distance of 2.0 m between creases; gate REQ-38 checks ≥ 2.0 m.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'crease_min_distance_m';
UPDATE fields x SET description = 'Haken nur, wenn sich Falten der Folie kreuzen. §9.3: „Creases are not permitted to cross over each other“ – Falten dürfen sich nicht kreuzen; Tor REQ-38 verlangt daher „nein“ (Haken leer).
[EN] Tick only if liner creases cross over each other. §9.3: creases are not permitted to cross over each other; gate REQ-38 therefore requires ''no'' (unticked).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'creases_crossing';
UPDATE fields x SET description = 'Anzahl der Ein-/Ausstiegsstellen im Schwimmbereich (Leitern, Treppen, Einstiegsbereiche), aus dem Plan. §9.5.3: „There must be at least one entry/exit point in the swimming area“; Tor REQ-39 prüft ≥ 1. Die Beschreibung der Anlagen steht im Textfeld daneben.
[EN] Number of entry/exit points in the swimming area (ladders, stairs, entry zones), from the plan. §9.5.3: there must be at least one entry/exit point in the swimming area; gate REQ-39 checks ≥ 1. The description of the installations goes in the text field beside it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'entry_exit_point_count';
UPDATE compliance_requirements x SET description = 'Besteht, wenn das Feld „Trennung Schwimm-/Regenerationsbereich“ ausgefüllt ist. §9.2: Naturteiche müssen in Schwimm- und Regenerationsbereich getrennt sein, mindestens durch eine überstaute, dauerhaft standsichere Barriere, die das Abrutschen von Schüttungen/Substraten in den Schwimmbereich verhindert (Typ I–III: Turbulenzen im Regenerationsbereich minimieren). Tragen Sie die gewählte Bauart ein.
[EN] Passes when the field ''Separation of swimming and regeneration areas'' is filled. §9.2: natural pools must be separated into a swimming area and a regeneration area, at least by an inundated, structurally durable barrier that prevents rock fill/substrates slipping into the swimming area (types I–III: minimise turbulence in the regeneration area). Enter the chosen construction.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-15';
UPDATE compliance_requirements x SET description = 'Besteht, wenn eine Abdichtungsart gewählt ist. §9.3: Der Naturteich muss dauerhaft gegen den Untergrund abgedichtet sein – kein Wasseraustritt in Boden und Grundwasser, kein Eintritt von Grund- oder Schichtenwasser; das Dichtungssystem folgt den FLL-Empfehlungen für Abdichtungssysteme für Gewässer. Wählen Sie die Abdichtungsart; bei EPDM/PVC gilt zusätzlich REQ-38.
[EN] Passes when a sealing type is selected. §9.3: the natural pool must be durably sealed against the subsoil – no water escaping into subsoil and groundwater, no groundwater or stratum water entering; the sealing system follows the FLL recommendations for sealing systems for bodies of water. Select the sealing type; for EPDM/PVC gate REQ-38 applies in addition.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-16';
UPDATE compliance_requirements x SET description = 'Besteht, wenn das Feld „Beckenrandgestaltung“ ausgefüllt ist. §9.4: Der Beckenrand muss die Dichtung schützen, Wasseraustritt in die Umgebung durch eine Kapillarsperre verhindern, dauerhaft standsicher sein und Oberflächenwasser baulich fernhalten. Beschreiben Sie die Randausbildung; die Zahlenwerte (≥ 5 cm Freibord, ± 10 mm Höhentoleranz) prüft REQ-31.
[EN] Passes when the field ''Edge design'' is filled. §9.4: the pool edge must protect the sealing, prevent water discharge into the surroundings by a capillary block, be permanently stable and keep surface water out structurally. Describe the edge construction; the numeric limits (≥ 5 cm freeboard, +/- 10 mm height tolerance) are checked by REQ-31.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-17';
UPDATE compliance_requirements x SET description = 'Besteht, wenn der Wasserspiegel-Abstand zur Dichtungsoberkante ≥ 5 cm UND die Beckenkanten-Höhentoleranz ≤ 10 mm ist; beide Felder müssen ausgefüllt sein. §9.4: Der Wasserspiegel muss je nach Wellenschlag ständig mindestens 5 cm unter der Dichtungsoberkante bleiben (ausgenommen Einbauten zur Wasserentnahme), und die Enden der Kanten dürfen höchstens +/- 10 mm von der Sollhöhe abweichen.
[EN] Passes when the freeboard from water level to the top edge of the sealing is ≥ 5 cm AND the edge height tolerance is ≤ 10 mm; both fields must be filled. §9.4: depending on the wash of the waves the water level must remain consistently at least 5 cm below the upper edge of the sealing system (except equipment for water extraction), and the ends of the edges may deviate at most +/- 10 mm from the planned nominal height.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-31';
UPDATE compliance_requirements x SET description = 'Besteht, wenn „Dichtung biozidfrei und biofilm-tolerant“ bestätigt ist. §9.3: Dichtungen und Schutzlagen dürfen nicht biozid behandelt sein; zulässig sind nur Dichtungen, auf deren Oberfläche sich ein Biofilm bilden kann. Setzen Sie den Haken nur, wenn das Datenblatt des Dichtungssystems beides belegt.
[EN] Passes when ''Sealing biocide-free and biofilm-permissive'' is confirmed. §9.3: sealings and protective layers cannot be treated with biocides; only sealings that allow biofilm to form on the surface are permissible. Tick only when the sealing system''s data sheet proves both.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-32';
UPDATE compliance_requirements x SET description = 'Gilt nur bei EPDM- oder PVC-Folie. Besteht, wenn entweder „Folie auf Betonuntergrund“ bestätigt ist (dann faltenfrei gefordert) ODER alle vier Faltenwerte eingetragen sind und einhalten: Höhe ≤ 1,0 cm, Länge ≤ 2,0 m, Abstand ≥ 2,0 m, keine Kreuzungen. §9.3: Folien in Sichtbereichen sind auf ebenem, standfestem Untergrund (z. B. Beton) faltenfrei zu verlegen; ohne Beton sind Falten bis 1,0 cm Höhe und 2,0 m Länge mit mindestens 2,0 m Abstand tolerierbar, Kreuzungen sind nicht zulässig – Maße am gefüllten Teich.
[EN] Applies only to EPDM or PVC liners. Passes when either ''liner on concrete subsoil'' is confirmed (crease-free required there) OR all four crease values are entered and comply: height ≤ 1.0 cm, length ≤ 2.0 m, distance ≥ 2.0 m, no crossings. §9.3: liners in visible areas are to be installed crease-free on level and stable subsoil (e.g. concrete); without concrete, creases up to 1.0 cm high and 2.0 m long with a minimum distance of 2.0 m can be tolerated, crossings are not permitted – measured on the filled pool.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-38';
UPDATE compliance_requirements x SET description = 'Besteht, wenn die Anzahl der Ein-/Ausstiegsstellen im Schwimmbereich ≥ 1 ist. §9.5.3: „There must be at least one entry/exit point in the swimming area“; die Stellen müssen trittsicher und rutschhemmend sein. Tragen Sie die Anzahl aus dem Plan ein.
[EN] Passes when the number of entry/exit points in the swimming area is ≥ 1. §9.5.3: there must be at least one entry/exit point in the swimming area; they must be safe to walk on with a non-slip finish. Enter the count from the plan.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-39';
UPDATE fields x SET description = 'Register der Anlagenausstattung: eine Zeile je Element mit Typ/Hersteller und Bemerkung. §8.3 nennt als Beispiele Stege, Leitern/Treppen, Plattformen, Duschen, Sprungfelsen/-bretter, Unterwasserbeleuchtung, Abdeckungen, Gegenstromanlage, Fontänen/Bachläufe, Heizung. Bei der Planung sind Statik, Dauerhaftigkeit, Korrosion und Rutschhemmung sowie DIN EN 16582-1 zu beachten; Duschwasser darf nicht in den Teich geleitet werden; elektrische Ausstattung nach DIN VDE 0100-702.
[EN] Register of equipment elements: one row per element with type/manufacturer and remark. §8.3 lists as examples walkways, ladders/stairs, platforms, showers, diving rocks/boards, underwater lighting, covers, counter current system, fountains/streams, heater. Planning must consider structural analysis, durability, corrosion and slip resistance as well as DIN EN 16582-1; shower water cannot be discharged into the natural pool; electrically operated elements per DIN VDE 0100-702.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-08' AND x.symbol = 'equipment_elements_list';
UPDATE fields x SET description = 'Bestätigen Sie, dass eine Leistungsbeschreibung für den Bauvertrag vorliegt. §8.4: Die Abschnitte 0 der ATV (VOB Teil C) geben die Hinweise zum Aufstellen der Leistungsbeschreibung; allgemein gilt ATV DIN 18299, je nach Fall ergänzt um DIN 18300 (Erdarbeiten), 18301, 18302, 18303, 18304, 18307, 18308 (Drainarbeiten), 18318, 18320 (Landschaftsbau), 18331 (Betonarbeiten), 18334 (Zimmerarbeiten).
[EN] Confirm that a description of services for the works contract exists. §8.4: sections 0 of the ATV (VOB part C) contain the instructions for drawing up the description of services; in general ATV DIN 18299 applies, supplemented as needed by DIN 18300 (ground work), 18301, 18302, 18303, 18304, 18307, 18308 (drainage work), 18318, 18320 (landscape works), 18331 (concrete work), 18334 (carpentry).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-08' AND x.symbol = 'service_description_provided';
UPDATE fields x SET description = 'Bestätigen Sie, dass die Wasserzirkulation nach §10.3 geplant ist: Oberflächenabzug über frei überströmte Überlaufwehre (starr, z. B. Gully, oder flexibel, z. B. Skimmer), damit Laub und Pollen nicht absinken; Anzahl, Art und Anordnung der Entnahmestellen nach Umwälzstrom, örtlichen Verhältnissen und Teichtyp, in Hauptwindrichtung, mit Zugang zur Reinigung und Rückhaltung für Amphibien und Grobschmutz; Überlauf für Überschusswasser (§10.3.2); Zu-/Ableitungen im Schwimmbereich nach DGfdB R 60.03 (§10.3.3); Rücklauf ohne direkte Anströmung von Boden und Wänden (§10.3.4). Tor REQ-23 blockiert ohne Haken.
[EN] Confirm that water circulation is designed per §10.3: surface discharge over freely overflowed weirs (rigid, e.g. gully, or flexible, e.g. skimmer) so leaves and pollen do not sink; number, type and arrangement of the extraction devices chosen by recirculation current, local conditions and pool type, placed in the primary wind direction, with access for cleaning and a device to hold back amphibians and coarse dirt; an overflow for excess water (§10.3.2); intake/discharge in the swimming area per DGfdB R 60.03 (§10.3.3); water return without direct flow against bottom or walls (§10.3.4). Gate REQ-23 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'attest_fllnt_09_req_23';
UPDATE fields x SET description = 'Beschickungsrate der hydrobotanischen Zone in m³ je m² Zonenfläche und Tag: geplanter Umwälzvolumenstrom durch die Zone geteilt durch ihre Fläche. Tab. 10 Zeile 12 setzt Qmax = 5 m³/(m² x Tag) für submerse wie emerse Systeme; Tor REQ-19 prüft ≤ 5. Fließt kein gepumpter Umwälzstrom durch die Zone (natürliche Zirkulation, Tab. 1, Typ I/II), ist die Beschickungsrate 0.
[EN] Feed rate of the hydrobotanical zone in m³ per m² of zone area per day: the planned recirculation flow through the zone divided by its area. Table 10 row 12 sets Qmax = 5 m³/(m² x day) for submergent and emersed systems alike; gate REQ-19 checks ≤ 5. If no pumped recirculation flow passes through the zone (natural circulation, Table 1, types I/II), the feed rate is 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'hydrobot_feed_rate';
UPDATE fields x SET description = 'Größtkorn des Pflanzsubstrats in mm, aus der Sieblinie des Lieferanten. Tab. 10 Zeile 5 („Location of the plant“): ≤ 8 mm; §7.2.4 bestätigt, dass das größte Korn 8 mm nicht überschreiten soll, weil gröberes Material Wurzelbildung erschwert. Fußnote 1 der Tab. 10: Die Sieblinie darf abweichen, wenn die genannten Eigenschaften dadurch nicht maßgeblich beeinflusst werden. Tor REQ-19 prüft ≤ 8 mm.
[EN] Maximum grain of the plant substrate in mm, from the supplier''s grading curve. Table 10 row 5 (''Location of the plant''): ≤ 8 mm; §7.2.4 confirms the largest grain should not exceed 8 mm because coarser material makes rooting more difficult. Footnote 1 of Table 10: the grain distribution curve can deviate if the listed properties are not decisively influenced. Gate REQ-19 checks ≤ 8 mm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'hydrobot_grain_size_max';
UPDATE fields x SET description = 'Dicke der Substratschicht (Vegetationstragschicht) der hydrobotanischen Zone in cm, aus dem Schnitt. Tab. 10 Zeile 3: submers 10–20 cm, emers 10–30 cm; §10.2.1 nennt für die Vegetationstragschicht mindestens 10 cm (Soll) und lässt flächige oder punktuelle Ausführung (Pflanzinseln) zu. Tor REQ-19 prüft den Bereich je nach gewähltem Typ.
[EN] Thickness of the substrate layer (vegetation support layer) of the hydrobotanical zone in cm, from the section drawing. Table 10 row 3: submergent 10–20 cm, emersed 10–30 cm; §10.2.1 says the vegetation support layer should be at least 10 cm and allows whole-area or point-wise application (plant islands). Gate REQ-19 checks the range for the selected type.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'hydrobot_substrate_thickness';
UPDATE fields x SET description = 'Art des hydrobotanischen Systems: „submergent“ = Unterwasserpflanzen (submerse Hydrophyten) mit ≥ 80 cm Wassersäule, „Emersed“ = Sumpfpflanzen (Helophyten) mit 10–50 cm Wassersäule (Tab. 10, Spalten 2/3; §6.2.2). Die Wahl steuert die Grenzwerte von REQ-19 und die Nachschlagefelder dieser Seite. Bei Typ I/II muss mindestens die Hälfte des Regenerationsbereichs submers sein (Tab. 2/3, geprüft in FLLNT-06).
[EN] Type of hydrobotanical system: ''submergent'' = aquatic plants living under water (submergent hydrophytes) with ≥ 80 cm water column, ''Emersed'' = marsh plants (helophytes) with 10–50 cm water column (Table 10 columns 2/3; §6.2.2). The choice sets the limits of REQ-19 and the lookup fields on this sheet. For types I/II at least half of the regeneration area must be submergent (Tables 2/3, checked in FLLNT-06).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'hydrobot_type';
UPDATE fields x SET description = 'Höhe der Wassersäule über der Substratschicht in cm („Überstauwasser“, Abb. 1/2), aus dem Schnitt. Tab. 10 Zeile 2: submers ≥ 80 cm, emers 10–50 cm. Tor REQ-19 prüft den Bereich je nach gewähltem Typ.
[EN] Height of the water column above the substrate layer in cm (''Überstauwasser'', Fig. 1/2), from the section drawing. Table 10 row 2: submergent ≥ 80 cm, emersed 10–50 cm. Gate REQ-19 checks the range for the selected type.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'hydrobot_water_column';
UPDATE fields x SET description = 'Wird aus Tab. 10 Zeile 2 nachgeschlagen, nicht eingegeben: Mindest-Wassersäule für den gewählten Typ – 80 cm submers, 10 cm emers. Dient dem Vergleich mit Ihrer Wassersäule (Tor REQ-19).
[EN] Looked up from Table 10 row 2, not entered: minimum water column for the selected type – 80 cm submergent, 10 cm emersed. Used to compare with your water column (gate REQ-19).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'hydrobot_water_column_min_tab10';
UPDATE fields x SET description = 'Wird aus Tab. 10 Zeile 2 nachgeschlagen, nur bei emersem System: höchste Wassersäule 50 cm. Submerse Systeme haben nach Tab. 10 keine Obergrenze. Dient dem Vergleich mit Ihrer Wassersäule (Tor REQ-19).
[EN] Looked up from Table 10 row 2, only for an emersed system: maximum water column 50 cm. Submergent systems have no upper limit in Table 10. Used to compare with your water column (gate REQ-19).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'hydrobot_water_column_max_tab10';
UPDATE fields x SET description = 'Wird aus Tab. 10 Zeile 3 nachgeschlagen, nicht eingegeben: Mindestdicke der Substratschicht 10 cm für submerse wie emerse Systeme (§10.2.1: „at least 10 cm“). Dient dem Vergleich mit Ihrer Schichtdicke (Tor REQ-19).
[EN] Looked up from Table 10 row 3, not entered: minimum substrate layer thickness 10 cm for submergent and emersed systems alike (§10.2.1: ''at least 10 cm''). Used to compare with your layer thickness (gate REQ-19).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'hydrobot_substrate_min_tab10';
UPDATE fields x SET description = 'Wird aus Tab. 10 Zeile 3 nachgeschlagen, nicht eingegeben: größte Substratschichtdicke 20 cm (submers) bzw. 30 cm (emers). Dient dem Vergleich mit Ihrer Schichtdicke (Tor REQ-19).
[EN] Looked up from Table 10 row 3, not entered: maximum substrate layer thickness 20 cm (submergent) or 30 cm (emersed). Used to compare with your layer thickness (gate REQ-19).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'hydrobot_substrate_max_tab10';
UPDATE fields x SET description = 'Wird aus Tab. 10 Zeile 5 nachgeschlagen, nicht eingegeben: Größtkorn des Pflanzsubstrats ≤ 8 mm, für beide Typen gleich. Dient dem Vergleich mit Ihrem Größtkorn (Tor REQ-19).
[EN] Looked up from Table 10 row 5, not entered: maximum grain of the plant substrate ≤ 8 mm, identical for both types. Used to compare with your maximum grain (gate REQ-19).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'hydrobot_grain_max_tab10';
UPDATE fields x SET description = 'Wird aus Tab. 10 Zeile 12 nachgeschlagen, nicht eingegeben: Qmax = 5 m³/(m² x Tag) für beide Typen. Dient dem Vergleich mit Ihrer Beschickungsrate (Tor REQ-19).
[EN] Looked up from Table 10 row 12, not entered: Qmax = 5 m³/(m² x day) for both types. Used to compare with your feed rate (gate REQ-19).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.symbol = 'hydrobot_feed_qmax_tab10';
UPDATE compliance_requirements x SET description = 'Gilt nur, wenn in FLLNT-10 „Langsamströmung“ gewählt ist; besteht dann, wenn in FLLNT-03 „Phosphorbindungsstufe erforderlich“ bestätigt ist. §10.2.2: Substratfilter mit kontrollierter Langsamströmung müssen eine nachgeschaltete phosphorbindende Reinigungsstufe haben – ein submerses hydrobotanisches System oder adsorbierendes Filtermaterial (Typ III, Tab. 1/4). Bei Schnellströmung ist das Tor ohne Wirkung.
[EN] Applies only when ''slow flow'' is selected in FLLNT-10; then passes when ''phosphorus-binding stage required'' is confirmed in FLLNT-03. §10.2.2: substrate filters with a controlled slow flow must be equipped with a downstream phosphorus-binding purification stage – a submergent hydrobotanical system or adsorbing filter material (type III, Tables 1/4). For quick flow the gate has no effect.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.code = 'REQ-08';
UPDATE compliance_requirements x SET description = 'Besteht, wenn alle Werte der hydrobotanischen Zone in den Bereichen der Tab. 10 liegen: Größtkorn ≤ 8 mm und Beschickung ≤ 5 m³/(m² x Tag) für beide Typen; submers: Wassersäule ≥ 80 cm und Substrat 10–20 cm; emers: Wassersäule 10–50 cm und Substrat 10–30 cm. Einzugeben sind Typ, Wassersäule, Substratdicke, Größtkorn und Beschickungsrate. Grundlage: Tab. 10 „Structural requirements for hydrobotanical systems“ (§10.2.1).
[EN] Passes when all values of the hydrobotanical zone lie within the Table 10 ranges: maximum grain ≤ 8 mm and feed rate ≤ 5 m³/(m² x day) for both types; submergent: water column ≥ 80 cm and substrate 10–20 cm; emersed: water column 10–50 cm and substrate 10–30 cm. Enter the type, water column, substrate thickness, maximum grain and feed rate. Basis: Table 10 ''Structural requirements for hydrobotanical systems'' (§10.2.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.code = 'REQ-19';
UPDATE compliance_requirements x SET description = 'Prüft einen Substratfilter mit Langsamströmung gegen Tab. 11 („controlled slow flow“); gilt nur bei vertikaler Durchströmung – horizontal verlangt Tab. 11 eine Einzelprüfung. Besteht, wenn: filterwirksame Schicht ≥ 40 cm, Größtkorn ≤ 16 mm, Überkorn ≤ 15 Gew.-%, abschlämmbare Anteile ≤ 2 Gew.-% (beide in FLLNT-05), Frostbeständigkeit bestätigt, Schichtdickentoleranz ≤ 10 %, k_f ≥ 10⁻⁴ m/s; mit durchgehendem Vollüberlauf zusätzlich Wassersäule ≥ 10 cm und Qmax ≤ 5 m³/(m² x Tag), ohne Überlauf Qmax ≤ 8. Die Eingaben stehen in FLLNT-10 und FLLNT-05.
[EN] Checks a slow-flow substrate filter against Table 11 (''controlled slow flow''); applies only to vertical flow – for horizontal flow Table 11 requires individual verification. Passes when: filter-effective layer ≥ 40 cm, maximum grain ≤ 16 mm, oversized grain ≤ 15 % by weight, elutriated parts ≤ 2 % by weight (both in FLLNT-05), frost resistance confirmed, layer thickness tolerance ≤ 10 %, k_f ≥ 10⁻⁴ m/s; with continuous full-surface overflow additionally water column ≥ 10 cm and Qmax ≤ 5 m³/(m² x day), without overflow Qmax ≤ 8. The inputs live in FLLNT-10 and FLLNT-05.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.code = 'REQ-20';
UPDATE compliance_requirements x SET description = 'Prüft einen Substratfilter mit Schnellströmung gegen Tab. 12 („controlled quick flow“); gilt nur bei vertikaler Durchströmung – horizontal verlangt Tab. 12 eine Einzelprüfung. Besteht, wenn: filterwirksame Schicht ≥ 50 cm, Größtkorn ≤ 32 mm, Überkorn ≤ 15 Gew.-%, abschlämmbare Anteile ≤ 0,5 Gew.-% (beide in FLLNT-05), Frostbeständigkeit bestätigt, Schichtdickentoleranz ≤ 10 %, k_f ≥ 10⁻³ m/s und Beschickung Qmin ≥ 15 m³/(m² x Tag). §10.2.3 (S. 52) lässt kleinere Beschickungen zu, wenn die Funktion des Teichs gesichert ist – dann ist das Tor nicht erfüllbar und der Nachweis gesondert zu führen.
[EN] Checks a quick-flow substrate filter against Table 12 (''controlled quick flow''); applies only to vertical flow – for horizontal flow Table 12 requires individual verification. Passes when: filter-effective layer ≥ 50 cm, maximum grain ≤ 32 mm, oversized grain ≤ 15 % by weight, elutriated parts ≤ 0.5 % by weight (both in FLLNT-05), frost resistance confirmed, layer thickness tolerance ≤ 10 %, k_f ≥ 10⁻³ m/s and feed rate Qmin ≥ 15 m³/(m² x day). §10.2.3 (p. 52) permits smaller feed rates if the functionality of the pool is ensured – then the gate cannot pass and the proof must be given separately.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.code = 'REQ-21';
UPDATE compliance_requirements x SET description = 'Besteht, wenn der Nachweis „§10.3“ bestätigt ist. Was zutreffen muss: Oberflächenabzug über frei überströmte starre oder flexible Überlaufwehre, Anzahl/Art/Anordnung der Entnahmestellen nach Umwälzstrom, Örtlichkeit und Teichtyp, Zugang zur Reinigung, Rückhaltung für Amphibien und Grobschmutz, Überlauf für Überschusswasser (§10.3.2), Zu-/Ableitungen nach DGfdB R 60.03 (§10.3.3), Rücklauf ohne direkte Anströmung von Boden und Wänden (§10.3.4). Die Zahlenwerte (Kantenlänge, Toleranz, Schwallwasser) prüfen REQ-33/40/41 in FLLNT-11.
[EN] Passes when the attestation ''§10.3'' is confirmed. What must be true: surface discharge over freely overflowed rigid or flexible weirs, number/type/arrangement of extraction devices chosen by recirculation current, local conditions and pool type, access for cleaning, a device holding back amphibians and coarse dirt, an overflow for excess water (§10.3.2), intake/discharge per DGfdB R 60.03 (§10.3.3), water return without direct flow against bottom or walls (§10.3.4). The numeric values (edge length, tolerance, splash water) are checked by REQ-33/40/41 in FLLNT-11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-09' AND x.code = 'REQ-23';
UPDATE fields x SET description = 'Bestätigen Sie, dass die Filteranlage aerob betrieben wird (ständige Durchströmung mit sauerstoffhaltigem Wasser, keine stagnierenden Zonen). §10.1: „The filtration systems must operate aerobically in order to avoid a redissolution of phosphate“ – in anaerobem Substrat geht gebundener Phosphor wieder in Lösung. Tor REQ-30 blockiert ohne Haken.
[EN] Confirm that the filtration system operates aerobically (continuous flow of oxygenated water, no stagnant zones). §10.1: the filtration systems must operate aerobically in order to avoid a redissolution of phosphate – in anaerobic substrate bound phosphorus goes back into solution. Gate REQ-30 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'aerobic_filtration_confirmed';
UPDATE fields x SET description = 'Ergebnis der 50×-Regel: Haken, wenn die besiedelbare Kornoberfläche im Filter mindestens das 50-Fache der belichteten, überstauten Unterwasserflächen (Boden + Wände, aus FLLNT-06) beträgt – Gleichung EQ-01. §10.2.3 und Anhang 5: Die äußeren Kornoberflächen im Filterkörper sollen erfahrungsgemäß mindestens das 50-Fache dieser Flächen erreichen; Dekorflächen (Kies ohne Durchströmung, Zierfelsen) zählen zu den Teichflächen. Tor REQ-22 blockiert ohne Haken; setzen Sie ihn nur, wenn EQ-01 die Bedingung erfüllt.
[EN] Result of the 50× rule: tick when the colonisable grain surface in the filter is at least 50 times the inundated underwater surfaces exposed to light (bottom + walls, from FLLNT-06) – equation EQ-01. §10.2.3 and Appendix 5: the outer grain surfaces in the filter body should, as experience shows, amount to at least 50 times these surfaces; decorative surfaces (gravel with no flow, design rocks) count among the pool surfaces. Gate REQ-22 blocks until ticked; tick only when EQ-01 satisfies the condition.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_50x_rule_met';
UPDATE fields x SET description = 'Besiedelbare Kornoberfläche des Filterkörpers in m², berechnet nach EQ-02 als spezifische Kornoberfläche (Tab. 15) × Filterquerschnitt × Filterhöhe. Anhang 5 Beispiel 1: 600 m²/m³ × 15 m² × 0,7 m = 6 300 m². Wird in EQ-01 mit dem 50-Fachen der Unterwasserfläche verglichen.
[EN] Colonisable grain surface of the filter body in m², computed by EQ-02 as grain specific surface (Table 15) × filter cross-section × filter height. Appendix 5 Example 1: 600 m²/m³ × 15 m² × 0.7 m = 6,300 m². Compared in EQ-01 with 50 times the underwater surface.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_colonized_surface_actual';
UPDATE fields x SET description = 'Nur bei Schnellströmung: geplante Beschickung in m³ je m² Filterfläche und Tag (Umwälzstrom durch den Filter ÷ Filterfläche). §10.2.3 und Tab. 12 Zeile 14: Qmin ≥ 15 m³/(m² x Tag) für vertikale Filter; horizontal nur Einzelprüfung. Kleinere Beschickungen sind zulässig, wenn die Funktion des Teichs gesichert ist (S. 52) – dann gesonderter Nachweis. Tor REQ-21 prüft ≥ 15.
[EN] Quick flow only: planned feed rate in m³ per m² of filter area per day (recirculation flow through the filter ÷ filter area). §10.2.3 and Table 12 row 14: Qmin ≥ 15 m³/(m² x day) for vertical filters; horizontal flow needs individual verification. Smaller feed rates are permissible if the functionality of the pool is ensured (p. 52) – then a separate proof. Gate REQ-21 checks ≥ 15.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_feed_rate_quick_qmin';
UPDATE fields x SET description = 'Nur bei Langsamströmung: geplante Beschickung in m³ je m² Filterfläche und Tag. Tab. 11 Zeile 14: Qmax 5 m³/(m² x Tag) bei vertikaler Durchströmung mit durchgehendem Vollüberlauf, 8 m³/(m² x Tag) bei vertikaler Durchströmung ohne Überlauf; horizontal nur Einzelprüfung. §10.2.2: Pflanzen können die erforderliche Beschickung nicht verringern. Tor REQ-20 prüft die Grenze je Spalte.
[EN] Slow flow only: planned feed rate in m³ per m² of filter area per day. Table 11 row 14: Qmax 5 m³/(m² x day) for vertical flow with continuous full-surface overflow, 8 m³/(m² x day) for vertical flow with no overflow; horizontal flow needs individual verification. §10.2.2: plants cannot reduce the required feed rate. Gate REQ-20 checks the limit per column.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_feed_rate_slow_qmax';
UPDATE fields x SET description = 'Durchströmung des Filterkörpers – die Spalte der Tab. 11/12: „vertical flow, continuous full-surface overflow“ (Spalte 2, Abb. 3/4), „vertical flow, no overflow“ (Spalte 3) oder „horizontal flow“ (Spalte 4). Für horizontale Filter drucken beide Tabellen nur „Individual verification – no further information“; dann werden k_f und Wassersäule ausgeblendet und REQ-20/21 prüfen keine Grenzwerte. §10.2.2/10.2.3: Der Filterkörper muss vollständig durchströmt sein.
[EN] Flow through the filter body – the column of Tables 11/12: ''vertical flow, continuous full-surface overflow'' (column 2, Fig. 3/4), ''vertical flow, no overflow'' (column 3) or ''horizontal flow'' (column 4). For horizontal filters both tables print only ''Individual verification – no further information''; k_f and water column are then hidden and REQ-20/21 check no limits. §10.2.2/10.2.3: the filter body must have a fully engaged flow.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_flow_direction';
UPDATE fields x SET description = 'Strömungsart des Substratfilters: „Langsamströmung“ = kontrollierte Langsamströmung nach §10.2.2/Tab. 11 (Teichtyp III, braucht eine nachgeschaltete P-Bindungsstufe, REQ-08) oder „Schnellströmung“ = kontrollierte Schnellströmung nach §10.2.3/Tab. 12 (Teichtyp IV, Biofilm auf den Kornoberflächen, 50×-Regel). Die Wahl bestimmt, welche Tabelle gilt.
[EN] Flow type of the substrate filter: ''slow flow'' = controlled slow flow per §10.2.2/Table 11 (pool type III, needs a downstream P-binding stage, REQ-08) or ''quick flow'' = controlled quick flow per §10.2.3/Table 12 (pool type IV, biofilm on the grain surfaces, 50× rule). The choice determines which table applies.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_flow_type';
UPDATE fields x SET description = 'Bestätigen Sie die Frostbeständigkeit des Filtersubstrats laut Lieferantenangabe. Tab. 11 und Tab. 12 Zeile 8: „is mandatory“ für vertikale Filter (ebenso Tab. 9 für Filtersubstrate Typ III/IV). Tore REQ-20/21 verlangen den Haken.
[EN] Confirm the frost resistance of the filter substrate per the supplier''s declaration. Table 11 and Table 12 row 8: ''is mandatory'' for vertical filters (likewise Table 9 for type III/IV filter substrates). Gates REQ-20/21 require the tick.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_frost_resistance';
UPDATE fields x SET description = 'Größtkorn der filterwirksamen Schicht in mm, aus der Sieblinie des Lieferanten. Tab. 11 Zeile 5 (Filter): ≤ 16 mm bei Langsamströmung; Tab. 12 Zeile 5: ≤ 32 mm bei Schnellströmung (Tab. 9 nennt dieselben Werte als empfohlenes Größtkorn). Fußnote 1: Die Sieblinie muss den geforderten k_f erreichen; bei Abweichung müssen k_f und Filterstabilität dauerhaft gegeben sein. Tore REQ-20/21 prüfen die jeweilige Grenze.
[EN] Maximum grain of the filter-effective layer in mm, from the supplier''s grading curve. Table 11 row 5 (filters): ≤ 16 mm for slow flow; Table 12 row 5: ≤ 32 mm for quick flow (Table 9 gives the same values as recommended maximum grain size). Footnote 1: the grain distribution curve must allow the specified permeability; on deviation k_f and filter stability must be maintained continuously. Gates REQ-20/21 check the respective limit.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_grain_size_max';
UPDATE fields x SET description = 'Durchlässigkeitsbeiwert des Filtersubstrats in m/s, aus dem Prüfzeugnis des Lieferanten (z. B. 0,0001 für 10⁻⁴ m/s). Tab. 11 Zeile 13: ≥ 10⁻⁴ m/s bei Langsamströmung; Tab. 12 Zeile 13: ≥ 10⁻³ m/s bei Schnellströmung; horizontal nur Einzelprüfung (Feld ausgeblendet). Tore REQ-20/21 prüfen die jeweilige Grenze.
[EN] Permeability coefficient of the filter substrate in m/s, from the supplier''s test certificate (e.g. 0.0001 for 10⁻⁴ m/s). Table 11 row 13: ≥ 10⁻⁴ m/s for slow flow; Table 12 row 13: ≥ 10⁻³ m/s for quick flow; horizontal flow needs individual verification (field hidden). Gates REQ-20/21 check the respective limit.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_kf';
UPDATE fields x SET description = 'Dicke der filterwirksamen Schicht in cm (ohne Deckschicht und Drain-/Verteilerschicht, Abb. 3/4), aus dem Schnitt. Tab. 11 Zeile 3: ≥ 40 cm bei Langsamströmung; Tab. 12 Zeile 3: ≥ 50 cm bei Schnellströmung; horizontal nur Einzelprüfung. Tore REQ-20/21 prüfen die jeweilige Grenze.
[EN] Thickness of the filter-effective layer in cm (excluding cover layer and drain/distribution layer, Fig. 3/4), from the section drawing. Table 11 row 3: ≥ 40 cm for slow flow; Table 12 row 3: ≥ 50 cm for quick flow; horizontal flow needs individual verification. Gates REQ-20/21 check the respective limit.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_layer_thickness';
UPDATE fields x SET description = 'Zulässige Abweichung der ausgeführten Schichtdicke von der geplanten in %, wie in der Leistungsbeschreibung festgelegt bzw. im Aufmaß festgestellt. Tab. 11 und Tab. 12 Zeile 11: „10% deviation“ bei vertikalen Filtern; horizontal nur Einzelprüfung. Tore REQ-20/21 prüfen ≤ 10 %.
[EN] Permitted deviation of the built layer thickness from the specified one in %, as fixed in the description of services or found in the survey. Table 11 and Table 12 row 11: ''10% deviation'' for vertical filters; horizontal flow needs individual verification. Gates REQ-20/21 check ≤ 10 %.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_layer_tolerance_pct';
UPDATE fields x SET description = 'Erforderliches Filtervolumen in m³, berechnet nach EQ-03: 50 × Unterwasserfläche (FLLNT-06) ÷ spezifische Kornoberfläche. Anhang 5 Beispiel 2: 95 m² × 50 = 4 750 m²; bei Korn 8–16 mm (600 m²/m³) ≈ 8 m³, bei Korn 4–8 mm (1 200 m²/m³) ≈ 4 m³. Vergleichen Sie mit dem geplanten Volumen F × h.
[EN] Required filter volume in m³, computed by EQ-03: 50 × underwater surface (FLLNT-06) ÷ grain specific surface. Appendix 5 Example 2: 95 m² × 50 = 4,750 m²; with grain 8–16 mm (600 m²/m³) approx. 8 m³, with grain 4–8 mm (1,200 m²/m³) approx. 4 m³. Compare with the planned volume F × h.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_volume_required';
UPDATE fields x SET description = 'Wassersäule über der filterwirksamen Schicht in cm (Abb. 3/4), aus dem Schnitt; nur bei vertikaler Durchströmung. Tab. 11 Zeile 2: ≥ 10 cm bei Langsamströmung mit durchgehendem Vollüberlauf, ohne Überlauf keine Angabe („—“); Tab. 12 Zeile 2: ≥ 0 cm bei Schnellströmung mit Vollüberlauf. Tor REQ-20 prüft ≥ 10 cm im Vollüberlauf-Fall.
[EN] Water column above the filter-effective layer in cm (Fig. 3/4), from the section drawing; vertical flow only. Table 11 row 2: ≥ 10 cm for slow flow with continuous full-surface overflow, no value (''—'') without overflow; Table 12 row 2: ≥ 0 cm for quick flow with full-surface overflow. Gate REQ-20 checks ≥ 10 cm in the full-surface-overflow case.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_water_column';
UPDATE fields x SET description = 'Spezifische Kornoberfläche des Filtermaterials in m²/m³ nach Tab. 15 (Dolomitkies): 4/6 → 1 400, 4/8 → 1 200, 6/8 → 1 000, 8/12 → 700, 8/16 → 600, 12/16 → 500, 16/22 → 350, 16/32 → 300, 22/32 → 250. Wählen Sie den Wert zur Kornklasse Ihres Filters; ein abweichender Produktwert braucht eine Begründung. Geht in EQ-02 und EQ-03 ein. Hinweis: Anhang 5 verweist auf „Table 1“, die Werte stehen in Tab. 15.
[EN] Grain specific surface of the filter material in m²/m³ per Table 15 (dolomite gravel): 4/6 → 1,400, 4/8 → 1,200, 6/8 → 1,000, 8/12 → 700, 8/16 → 600, 12/16 → 500, 16/22 → 350, 16/32 → 300, 22/32 → 250. Pick the value for your filter''s grain class; a differing product value needs a justification. Feeds EQ-02 and EQ-03. Note: Appendix 5 refers to ''Table 1'', the values are printed in Table 15.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'grain_specific_surface';
UPDATE fields x SET description = 'Durchströmter Filterquerschnitt in m² (bei vertikaler Durchströmung die Filterfläche in der Draufsicht), aus dem Plan. Anhang 5 Beispiel 1 rechnet mit „Filter cross-section F: 15 m²“. Geht in EQ-02 ein (Kornoberfläche = spez. Oberfläche × F × h).
[EN] Filter cross-section through which the water flows in m² (for vertical flow the filter plan area), from the drawing. Appendix 5 Example 1 uses ''Filter cross-section F: 15 m²''. Feeds EQ-02 (grain surface = specific surface × F × h).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'F_filter';
UPDATE fields x SET description = 'Höhe des Filterkörpers in m (filterwirksame Schicht, Abb. 3/4), aus dem Schnitt. Anhang 5 Beispiel 1 rechnet mit „Filter height: 0.7 m“. Geht in EQ-02 ein; achten Sie auf Meter, während die Schichtdicke oben in cm steht.
[EN] Height of the filter body in m (filter-effective layer, Fig. 3/4), from the section drawing. Appendix 5 Example 1 uses ''Filter height: 0.7 m''. Feeds EQ-02; note the unit is metres while the layer thickness above is in cm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'h_filter';
UPDATE fields x SET description = 'Register der Reinigungseinheiten: eine Zeile je Einheit mit Art (hydrobotanisch submers/emers, Substratfilter langsam/schnell mit Strömungsrichtung, technische Einheit), Fläche, wirksamer Schicht, Kornklasse nach Tab. 15 mit spezifischer Oberfläche (Produktwert nur mit Begründung) und Beschickung in m³/(m² x Tag). Je Zeile ergeben sich die besiedelbare Oberfläche (Anhang 5 Beispiel 1: 600 × 15 × 0,7 = 6 300 m²; technische Einheiten nach Herstellerangabe, §10.2.4) und die Beschickungsgrenze aus Tab. 10 (Qmax 5), Tab. 11 (Qmax 5/8) bzw. Tab. 12 (Qmin 15). Summen in den beiden Feldern darunter.
[EN] Register of purification units: one row per unit with kind (hydrobotanical submergent/emersed, substrate filter slow/quick with flow direction, technical unit), area, effective layer, grain class per Table 15 with specific surface (product value only with justification) and feed rate in m³/(m² x day). Each row yields its colonisable surface (Appendix 5 Example 1: 600 × 15 × 0.7 = 6,300 m²; technical units per manufacturer''s data, §10.2.4) and its feed limit from Table 10 (Qmax 5), Table 11 (Qmax 5/8) or Table 12 (Qmin 15). Totals appear in the two fields below.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filtereinheiten';
UPDATE fields x SET description = 'Wird berechnet (FLLNT-10-D1), nicht eingegeben: Summe der besiedelbaren Kornoberflächen aller Zeilen des Registers in m² (hydrobotanische Zeilen zählen 0). Vergleichswert für die 50×-Regel nach §10.2.3/Anhang 5: Σ soll ≥ 50 × belichtete Unterwasserfläche sein.
[EN] Computed (FLLNT-10-D1), not entered: sum of the colonisable grain surfaces of all register rows in m² (hydrobotanical rows count 0). Reference value for the 50× rule of §10.2.3/Appendix 5: Σ should be ≥ 50 × the underwater surface exposed to light.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_colonized_surface_total';
UPDATE fields x SET description = 'Wird berechnet (FLLNT-10-D2), nicht eingegeben: Anzahl der Registerzeilen, deren Beschickung über Qmax liegt (Tab. 10: 5; Tab. 11: 5 bzw. 8 m³/(m² x Tag)) oder unter Qmin (Tab. 12: 15 m³/(m² x Tag)). Horizontale Filter („Individual verification“), technische Einheiten und Zeilen ohne Beschickung zählen nicht. Ziel: 0.
[EN] Computed (FLLNT-10-D2), not entered: number of register rows whose feed rate exceeds Qmax (Table 10: 5; Table 11: 5 or 8 m³/(m² x day)) or falls below Qmin (Table 12: 15 m³/(m² x day)). Horizontal filters (''Individual verification''), technical units and rows without a feed rate are not counted. Target: 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.symbol = 'filter_feed_violations';
UPDATE equations x SET description = '50×-Regel: besiedelbare Kornoberfläche im Filter (m², EQ-02) ≥ 50 × belichtete, überstaute Unterwasserfläche des Teichs (m², Boden + Wände, aus FLLNT-06). §10.2.3: Die äußeren Kornoberflächen im Filterkörper sollen erfahrungsgemäß mindestens das 50-Fache dieser Flächen erreichen; Anhang 5 Beispiel 2: 95 m² × 50 = 4 750 m². Das Ergebnis ist der Haken „50×-Regel erfüllt“ (Tor REQ-22).
[EN] 50× rule: colonisable grain surface in the filter (m², EQ-02) ≥ 50 × the inundated underwater surface of the pool exposed to light (m², bottom + walls, from FLLNT-06). §10.2.3: the outer grain surfaces in the filter body should, as experience shows, amount to at least 50 times these surfaces; Appendix 5 Example 2: 95 m² × 50 = 4,750 m². The result is the tick ''50× rule satisfied'' (gate REQ-22).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.equation_number = 'EQ-01';
UPDATE equations x SET description = 'Besiedelbare Kornoberfläche des Filterkörpers = spezifische Kornoberfläche (m²/m³, Tab. 15) × Filterquerschnitt F (m²) × Filterhöhe h (m). Anhang 5 Beispiel 1: 600 m²/m³ × 15 m² × 0,7 m = 6 300 m² („Surface of the filter body“). Das Ergebnis geht in EQ-01 ein.
[EN] Colonisable grain surface of the filter body = grain specific surface (m²/m³, Table 15) × filter cross-section F (m²) × filter height h (m). Appendix 5 Example 1: 600 m²/m³ × 15 m² × 0.7 m = 6,300 m² (''Surface of the filter body''). The result feeds EQ-01.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.equation_number = 'EQ-02';
UPDATE equations x SET description = 'Erforderliches Filtervolumen (m³) = Unterwasserfläche (m², FLLNT-06) × 50 ÷ spezifische Kornoberfläche (m²/m³, Tab. 15). Anhang 5 Beispiel 2: 4 750 m² ÷ 600 m²/m³ ≈ 8 m³ bei Korn 8–16 mm, 4 750 ÷ 1 200 ≈ 4 m³ bei Korn 4–8 mm. Dient dem Vergleich mit dem geplanten Volumen F × h.
[EN] Required filter volume (m³) = underwater surface (m², FLLNT-06) × 50 ÷ grain specific surface (m²/m³, Table 15). Appendix 5 Example 2: 4,750 m² ÷ 600 m²/m³ approx. 8 m³ for grain 8–16 mm, 4,750 ÷ 1,200 approx. 4 m³ for grain 4–8 mm. Used to compare with the planned volume F × h.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.equation_number = 'EQ-03';
UPDATE equations x SET description = 'Summe der besiedelbaren Kornoberflächen über alle Zeilen des Registers „Filter-/Hydrobotanik-Einheiten“ in m²: je Substratfilter-Zeile spezifische Oberfläche nach Tab. 15 × Fläche × wirksame Schicht (Anhang 5 Beispiel 1: 600 × 15 × 0,7 = 6 300 m²), technische Einheiten nach Herstellerangabe, hydrobotanische Zeilen 0. Ergebnis: Σ besiedelbare Oberfläche, Vergleichswert der 50×-Regel (§10.2.3).
[EN] Sum of the colonisable grain surfaces over all rows of the register ''Filter / hydrobotanical units'' in m²: per substrate-filter row specific surface per Table 15 × area × effective layer (Appendix 5 Example 1: 600 × 15 × 0.7 = 6,300 m²), technical units per manufacturer''s data, hydrobotanical rows 0. Result: Σ colonisable surface, the reference value of the 50× rule (§10.2.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.equation_number = 'FLLNT-10-D1';
UPDATE equations x SET description = 'Zählt die Zeilen des Registers, deren Beschickung die gedruckte Grenze verletzt: über Qmax = 5 m³/(m² x Tag) (Tab. 10, hydrobotanisch), über 5 bzw. 8 m³/(m² x Tag) (Tab. 11, Langsamströmung mit/ohne Vollüberlauf) oder unter Qmin = 15 m³/(m² x Tag) (Tab. 12, Schnellströmung). Horizontale Filter, technische Einheiten und Zeilen ohne Beschickung zählen nicht. Ergebnis: Anzahl Verletzungen, Ziel 0.
[EN] Counts the register rows whose feed rate violates the printed limit: above Qmax = 5 m³/(m² x day) (Table 10, hydrobotanical), above 5 or 8 m³/(m² x day) (Table 11, slow flow with/without full-surface overflow) or below Qmin = 15 m³/(m² x day) (Table 12, quick flow). Horizontal filters, technical units and rows without a feed rate are not counted. Result: number of violations, target 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.equation_number = 'FLLNT-10-D2';
UPDATE compliance_requirements x SET description = 'Besteht, wenn „50×-Regel erfüllt“ bestätigt ist. Dafür müssen die Unterwasserfläche (FLLNT-06), die spezifische Kornoberfläche (Tab. 15), Filterquerschnitt und Filterhöhe eingetragen sein, sodass EQ-02/EQ-01 zeigen: Kornoberfläche im Filter ≥ 50 × belichtete Unterwasserfläche. §10.2.3/Anhang 5: Erfahrungswert für Schnellströmungsfilter (Typ IV) – die Biofilmfläche im Filter muss die zu reinigenden Teichflächen deutlich übertreffen.
[EN] Passes when ''50× rule satisfied'' is confirmed. For that, enter the underwater surface (FLLNT-06), the grain specific surface (Table 15), filter cross-section and filter height so that EQ-02/EQ-01 show: grain surface in the filter ≥ 50 × the underwater surface exposed to light. §10.2.3/Appendix 5: an experience value for quick-flow filters (type IV) – the biofilm surface in the filter must clearly exceed the pool surfaces to be purified.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.code = 'REQ-22';
UPDATE compliance_requirements x SET description = 'Besteht, wenn „Aerobe Filtration bestätigt“ gesetzt ist. §10.1: Filteranlagen müssen aerob betrieben werden, um eine Rücklösung von Phosphat zu vermeiden. Setzen Sie den Haken, wenn Durchströmung und Betriebsweise (Beschickung, Laufzeiten) stagnierende, sauerstofffreie Zonen im Filter ausschließen.
[EN] Passes when ''Aerobic filtration confirmed'' is ticked. §10.1: the filtration systems must operate aerobically in order to avoid a redissolution of phosphate. Tick when the flow and the operating regime (feed rate, running times) rule out stagnant, oxygen-free zones in the filter.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-10' AND x.code = 'REQ-30';
UPDATE fields x SET description = 'Beschreiben Sie das technische Strömungsregime durch den Schwimmbereich: Oberflächenabzug über Überlaufwehre, Lage der Entnahmestellen in der örtlichen Hauptwindrichtung, kontrollierte Rückführung, sodass eine durchgehende Strömung den eingetragenen Schmutz abführt (§10.3.1). Nennen Sie auch Pumpe und Umwälzvolumenstrom, nach denen Anzahl, Art und Anordnung der Entnahmestellen gewählt sind.
[EN] Describe the technical flow regime through the swimming area: surface discharge over overflow weirs, extraction devices positioned in the local primary wind direction, carefully controlled recirculation so that a continuous flow removes the dirt that has entered (§10.3.1). Also name the pump and recirculation flow by which number, type and arrangement of the extraction devices were chosen.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'circulation_type';
UPDATE fields x SET description = 'Bestätigen Sie, dass Zu-, Ab- und Einspeiseleitungen geplant und ausgeführt sind. §10.3.3: Werden Zu-/Ab- oder Einspeisesysteme im Schwimmbereich eingebaut, ist DGfdB R 60.03 zu beachten; §10.3.4: Der Rücklauf darf Boden-, Wand- und Einbauflächen nicht direkt anströmen (übermäßiger Biofilm- und Algenwuchs).
[EN] Confirm that intake, discharge and feed systems are designed and installed. §10.3.3: DGfdB R 60.03 is to be observed if an intake, discharge and/or feed system is installed in the swimming area; §10.3.4: the water return must not flow directly against bottom, wall or installation surfaces (excessive biofilm and algae growth).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'intake_discharge_provided';
UPDATE fields x SET description = 'Richtwert der erforderlichen Überlaufkantenlänge in m, berechnet nach EQ-04 als 1 % der Schwimmbereichsfläche. §10.3.1: Als Anhalt für flexible und starre Überlaufwehre gilt „1% of the surface area of the swimming area in metres“ – Beispiel: 30 m² Schwimmbereich → 0,3 m Kantenlänge. Die tatsächlich eingebauten Kanten erfassen Sie im Register darunter; Tor REQ-41 (Warnung) vergleicht die Summe mit diesem Wert.
[EN] Guide value of the required overflow edge length in m, computed by EQ-04 as 1 % of the swimming-area surface. §10.3.1: as a guide for flexible and rigid overflow weirs, ''1% of the surface area of the swimming area in metres'' – example: swimming area 30 m² → overflow edge 0.3 m. Record the edges actually installed in the register below; gate REQ-41 (warning) compares their sum with this value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'overflow_edge_length';
UPDATE fields x SET description = 'Größte gemessene horizontale Abweichung der Überlaufkante vom Nivellement in mm. §10.3.1: Überlaufwehre sind so einzubauen, dass die Kante horizontal um nicht mehr als +/- 2 mm abweicht, bei Kanten bis 1 m um nicht mehr als +/- 1 mm. Das Feld dient der Dokumentation; die Prüfung je Kante erfolgt über das Register (Tor REQ-40).
[EN] Largest measured horizontal deviation of the overflow edge from level in mm. §10.3.1: overflow weirs are to be installed so that the edge does not deviate horizontally by more than +/- 2 mm, or by more than +/- 1 mm for edges up to 1 m. This field documents; the per-edge check runs through the register (gate REQ-40).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'overflow_horizontal_tolerance_mm';
UPDATE fields x SET description = 'Art des Oberflächenabzugs und Überlaufs: starres Überlaufwehr (z. B. Gully/Rinne) oder flexibles Überlaufwehr (z. B. Skimmer) nach §10.3.1, dazu der Überlauf für Überschusswasser nach §10.3.2 (an geeigneter Stelle, kontrollierte Ableitung; bei Anschluss an die Entwässerung die Abflüsse aller angeschlossenen Dach- und Freiflächen ohne Rückstau berücksichtigen). Starre Wehre machen den Schwallwasserbehälter zwingend.
[EN] Kind of surface discharge and overflow: rigid overflow weir (e.g. gully) or flexible overflow weir (e.g. skimmer) per §10.3.1, plus the overflow for excess water per §10.3.2 (at a suitable point, controlled discharge; when fed into a drainage system consider the drain pipe of all connected roof and open areas to avoid backwater). Rigid weirs make the splash water tank mandatory.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'overflow_type';
UPDATE fields x SET description = 'Haken, wenn ergänzend physikalische oder chemische Verfahren eingesetzt werden (z. B. Algenentfernung durch Filtration, adsorbierende Stoffe zur Nährstoff-/Salzentnahme). §10.2.5/§10.1: Solche Verfahren sind nur zusammen mit biologischen Verfahren und nur als Ergänzung zulässig; sie zählen nicht für die Bemessung der Wasseraufbereitung, und die hydraulische Beschickung adsorbierender Stoffe muss bemessen und wissenschaftlich begründet sein. Tor REQ-24 prüft, dass sie nicht die Haupttechnik sind.
[EN] Tick if supplementary physical or chemical techniques are used (e.g. algae removal by filtration, adsorbing substances to remove nutrients or salts). §10.2.5/§10.1: such techniques can only be used in conjunction with biological techniques and only as supplementary methods; they are not taken into account for dimensioning the water purification, and the hydraulic feed of adsorbing substances must be dimensioned and scientifically justified. Gate REQ-24 checks they are not the main technique.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'physical_chemical_used';
UPDATE fields x SET description = 'Haken, wenn mindestens ein starres Überlaufwehr (z. B. Gully, Überlaufrinne) eingesetzt wird; bei nur flexiblen Wehren (Skimmer) leer lassen. §10.3.1: „A water reservoir is mandatory when using rigid overflow weirs“ – mit dem Haken werden das Schwallwasservolumen und die angeschlossene Wasserfläche verlangt (Tor REQ-33).
[EN] Tick if at least one rigid overflow weir (e.g. gully, overflow channel) is used; leave empty with flexible weirs (skimmers) only. §10.3.1: a water reservoir is mandatory when using rigid overflow weirs – with the tick the splash water tank volume and the connected water surface are required (gate REQ-33).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'rigid_overflow_used';
UPDATE fields x SET description = 'Nutzvolumen des Schwallwasser-/Ausgleichsbehälters in Litern, aus der Behälterplanung (Bemessung und Technik nach DGfdB R 65.06 und DIN 19643-1). §10.3.1: mindestens 150 l je m² überstauter Wasserfläche des an das Wehr angeschlossenen Bereichs; der Behälter hält den Wasserspiegel, die Überströmung starrer Wehre und Verdunstungsreserve und nimmt verdrängtes Wasser auf; Notüberlauf, Zugänglichkeit, Nährstofffreiheit und Tierausstieg sind sicherzustellen. Tor REQ-33 prüft ≥ 150 × Fläche.
[EN] Usable volume of the splash water / compensating tank in litres, from the tank design (dimensioning and equipment per DGfdB R 65.06 and DIN 19643-1). §10.3.1: at least 150 l per m² of inundated water surface of the area connected to the weir; the tank maintains the water level, keeps up the flow over rigid weirs, holds an evaporation reserve and absorbs displaced water; emergency overflow, accessibility, freedom from nutrients and an exit for animals must be ensured. Gate REQ-33 checks ≥ 150 × area.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'splash_water_tank_volume';
UPDATE fields x SET description = 'Haken nur, wenn eines der nach §10.1 unzulässigen Verfahren eingesetzt wird: Desinfektionsmittel (Chlor, Chlordioxid, Ozon), Biozide/Biozidprodukte (Insektizide, Fungizide, Algizide), schwermetallhaltige Produkte, Silber-/Kupfertechniken (diese Metalle dürfen in keiner Form eingebracht werden), UV-Desinfektion, Beschallung. Diese Anwendungen sind ungeeignet und unzulässig, weil sie die Reinigungstechnik gefährden. Tor REQ-29 verlangt „nein“.
[EN] Tick only if any of the applications impermissible under §10.1 is used: disinfectants (chlorine, chlorine dioxide, ozone), biocides and biocidal products (insecticides, fungicides, algicides), products containing heavy metals, techniques based on silver and copper (these metals cannot be introduced in any form), UV disinfection, sonification. These are deemed unsuitable and impermissible because they can endanger the purification technique. Gate REQ-29 requires ''no''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'treatment_impermissible_used';
UPDATE fields x SET description = 'Fläche des Schwimmbereichs in m² (Wasseroberfläche, aus dem Plan); gleicher Wert wie in FLLNT-06. Dient EQ-04: Richtwert der Überlaufkantenlänge = 1 % dieser Fläche in Metern (§10.3.1, Beispiel 30 m² → 0,3 m).
[EN] Surface area of the swimming area in m² (water surface, from the plan); the same value as in FLLNT-06. Used by EQ-04: guide value of the overflow edge length = 1 % of this area in metres (§10.3.1, example 30 m² → 0.3 m).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'swimming_area_m2';
UPDATE fields x SET description = 'Register der Überlauf-/Ablaufeinrichtungen: eine Zeile je Wehr mit Art (starr/flexibel), Kantenlänge in m und gemessener horizontaler Abweichung in mm. §10.3.1 erlaubt höchstens +/- 2 mm, bei Kanten bis 1 m höchstens +/- 1 mm; je Zeile ergibt sich daraus „Toleranz eingehalten“. Die Summe der Kantenlängen wird mit dem Richtwert 1 % der Schwimmbereichsfläche verglichen (REQ-41), die Toleranzverletzungen zählt REQ-40.
[EN] Register of overflow / discharge devices: one row per weir with kind (rigid/flexible), edge length in m and measured horizontal deviation in mm. §10.3.1 allows at most +/- 2 mm, for edges up to 1 m at most +/- 1 mm; each row yields ''tolerance met''. The sum of edge lengths is compared with the guide value 1 % of the swimming-area surface (REQ-41); tolerance violations are counted by REQ-40.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'ueberlaufeinrichtungen';
UPDATE fields x SET description = 'Wird berechnet (FLLNT-11-D1), nicht eingegeben: Summe der Kantenlängen aller Zeilen des Registers in m. Vergleichswert zum Richtwert nach §10.3.1 (1 % der Schwimmbereichsfläche in Metern, EQ-04); Tor REQ-41 warnt, wenn die Summe darunter liegt.
[EN] Computed (FLLNT-11-D1), not entered: sum of the edge lengths of all register rows in m. Compared with the guide value of §10.3.1 (1 % of the swimming-area surface in metres, EQ-04); gate REQ-41 warns when the sum falls short.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'overflow_edge_length_total';
UPDATE fields x SET description = 'Wird berechnet (FLLNT-11-D2), nicht eingegeben: Anzahl der Registerzeilen, deren horizontale Abweichung die Toleranz nach §10.3.1 überschreitet (+/- 2 mm, bei Kanten bis 1 m +/- 1 mm); Zeilen ohne Messwert zählen nicht. Tor REQ-40 verlangt 0.
[EN] Computed (FLLNT-11-D2), not entered: number of register rows whose horizontal deviation exceeds the §10.3.1 tolerance (+/- 2 mm, for edges up to 1 m +/- 1 mm); rows without a measurement are not counted. Gate REQ-40 requires 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'overflow_tolerance_violations';
UPDATE fields x SET description = 'Nur bei Teichtyp II: tägliche Laufzeit des Oberflächenabzugs (Skimmer/Überlaufwehr) im Intervallbetrieb in h/Tag, aus der Steuerung/Betriebsanleitung. Tab. 3 definiert Typ II mit „surface water discharge in interval operation < 10 h/day“ und ohne Filter; Tor REQ-34 prüft < 10 h/Tag. Längere Laufzeiten entsprechen einem anderen Teichtyp.
[EN] Type II only: daily running time of the surface discharge (skimmer/overflow weir) in interval operation in h/day, from the control settings / operating manual. Table 3 defines type II with ''surface water discharge in interval operation < 10 h/day'' and no filter; gate REQ-34 checks < 10 h/day. Longer running times correspond to another pool type.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'surface_discharge_hours_per_day';
UPDATE fields x SET description = 'Nur Typ III–V: tägliches Beschickungsvolumen des Filters in m³/Tag = Umwälzvolumenstrom der Pumpe × tägliche Betriebsstunden, aus Pumpenkennlinie und Betriebsplan. Dient FLLNT-11-D3, die den Anteil am Gesamtwasservolumen (FLLNT-06) bildet; Tab. 4 verlangt für Typ III > 25 % des Gesamtwasservolumens je Tag, Tab. 5/6 für Typ IV/V > 80 %.
[EN] Types III–V only: daily filter feed volume in m³/day = pump recirculation flow × daily operating hours, from the pump curve and operating plan. Feeds FLLNT-11-D3, which forms the share of the total water volume (FLLNT-06); Table 4 requires > 25 % of the total water volume per day for type III, Tables 5/6 > 80 % for types IV/V.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'filter_feed_volume_per_day_m3';
UPDATE fields x SET description = 'Wird berechnet (FLLNT-11-D3), nicht eingegeben: tägliches Beschickungsvolumen × 100 ÷ Gesamtwasservolumen (FLLNT-06) in %. Grenzen aus den Typdefinitionen: Typ III „filter feed rate > 25% of the total water volume/day“ (Tab. 4), Typ IV „> 80%“ (Tab. 5), Typ V „filtration rate > 80%“ (Tab. 6). Tor REQ-35 prüft den Wert.
[EN] Computed (FLLNT-11-D3), not entered: daily feed volume × 100 ÷ total water volume (FLLNT-06) in %. Limits from the type definitions: type III ''filter feed rate > 25% of the total water volume/day'' (Table 4), type IV ''> 80%'' (Table 5), type V ''filtration rate > 80%'' (Table 6). Gate REQ-35 checks the value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'feed_share_of_volume_pct';
UPDATE fields x SET description = 'Nur Typ III–V: Betriebsstunden des Filters je Tag während der Badesaison, aus Steuerung/Betriebsplan. Tab. 4: Typ III „filter operation > 12 h/day“; Tab. 5 und 6: Typ IV und V „filter operation 24 h/day“ (Dauerbetrieb). Tor REQ-36 prüft > 12 bzw. = 24.
[EN] Types III–V only: filter operating hours per day during the swimming season, from the control settings / operating plan. Table 4: type III ''filter operation > 12 h/day''; Tables 5 and 6: types IV and V ''filter operation 24 h/day'' (continuous). Gate REQ-36 checks > 12 or = 24.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'filter_operation_hours_per_day';
UPDATE fields x SET description = 'Nur Typ III: längste zusammenhängende Stillstandszeit des Filters in Stunden (Pausen im Intervallbetrieb, aus der Steuerung). Tab. 4 definiert Typ III mit „maximum downtime 1 h“; Tor REQ-36 prüft ≤ 1 h.
[EN] Type III only: longest continuous filter downtime in hours (pauses in interval operation, from the control settings). Table 4 defines type III with ''maximum downtime 1 h''; gate REQ-36 checks ≤ 1 h.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'filter_max_downtime_h';
UPDATE fields x SET description = 'Nur bei starrem Überlaufwehr: Wasseroberfläche (Grundrissfläche) des Bereichs in m², der an das Wehr angeschlossen ist – bei einem Einbereichssystem die gesamte Wasseroberfläche, bei Mehrbereichssystemen nur der angeschlossene Bereich (§10.3.1: „only the water surface of the area to which the overflow weir is connected“). Multiplikator der 150-l/m²-Regel in EQ-05/REQ-33; nicht die Unterwasserfläche (Boden + Wände) aus FLLNT-06.
[EN] Rigid overflow weir only: water surface (plan area) in m² of the area connected to the weir – for a single-area system the total water surface, for multi-area systems only the connected area (§10.3.1: ''only the water surface of the area to which the overflow weir is connected''). Multiplier of the 150 l/m² rule in EQ-05/REQ-33; not the underwater surface (bottom + walls) from FLLNT-06.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'overflow_connected_water_surface_m2';
UPDATE equations x SET description = 'Richtwert der Überlaufkantenlänge (m) = 0,01 × Schwimmbereichsfläche (m²). §10.3.1: Als Anhalt für flexible und starre Überlaufwehre „1% of the surface area of the swimming area in metres“; Beispiel: 30 m² → 0,3 m. Das Ergebnis ist der Vergleichswert für die Summe der eingebauten Kanten (Tor REQ-41, Warnung).
[EN] Guide value of the overflow edge length (m) = 0.01 × swimming-area surface (m²). §10.3.1: as a guide for flexible and rigid overflow weirs, ''1% of the surface area of the swimming area in metres''; example: 30 m² → 0.3 m. The result is the reference for the sum of installed edges (gate REQ-41, warning).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.equation_number = 'EQ-04';
UPDATE equations x SET description = 'Schwallwasserbehälter: Nutzvolumen (l) ≥ 150 × angeschlossene Wasseroberfläche (m²). §10.3.1: Das Nutzvolumen muss so bemessen sein, dass mindestens 150 l je m² überstauter Wasserfläche bereitstehen; bei Mehrbereichssystemen zählt nur die Wasserfläche des an das Wehr angeschlossenen Bereichs. Ergebnis: Mindestvolumen, geprüft in REQ-33.
[EN] Splash water tank: usable volume (l) ≥ 150 × connected water surface (m²). §10.3.1: the usable volume must be dimensioned so that at least 150 l per square metre can be provided to the inundated water surface; in multi-area systems only the water surface of the area to which the weir is connected counts. Result: minimum volume, checked in REQ-33.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.equation_number = 'EQ-05';
UPDATE equations x SET description = 'Summe der Kantenlängen (m) über alle Zeilen des Registers „Überlauf-/Ablaufeinrichtungen“. Ergebnis: eingebaute Überlaufkantenlänge, die mit dem Richtwert nach §10.3.1 (1 % der Schwimmbereichsfläche, EQ-04) verglichen wird (Tor REQ-41).
[EN] Sum of the edge lengths (m) over all rows of the register ''Overflow / discharge devices''. Result: installed overflow edge length, compared with the guide value of §10.3.1 (1 % of the swimming-area surface, EQ-04) (gate REQ-41).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.equation_number = 'FLLNT-11-D1';
UPDATE equations x SET description = 'Zählt die Registerzeilen, deren horizontale Abweichung die Toleranz nach §10.3.1 überschreitet: mehr als +/- 2 mm, bei Überlaufkanten bis 1 m mehr als +/- 1 mm. Zeilen ohne Messwert zählen nicht. Ergebnis: Anzahl Toleranzverletzungen (Tor REQ-40 verlangt 0).
[EN] Counts the register rows whose horizontal deviation exceeds the §10.3.1 tolerance: more than +/- 2 mm, or for overflow edges up to 1 m more than +/- 1 mm. Rows without a measurement are not counted. Result: number of tolerance violations (gate REQ-40 requires 0).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.equation_number = 'FLLNT-11-D2';
UPDATE equations x SET description = 'Beschickungsanteil (%) = tägliches Filterbeschickungsvolumen (m³/Tag) × 100 ÷ Gesamtwasservolumen des Naturteichs (m³, FLLNT-06). Entspricht der Typdefinition „filter feed rate … % of the total water volume/day“: Typ III > 25 % (Tab. 4), Typ IV/V > 80 % (Tab. 5/6). Ergebnis wird in REQ-35 geprüft.
[EN] Feed share (%) = daily filter feed volume (m³/day) × 100 ÷ total water volume of the natural pool (m³, FLLNT-06). Corresponds to the type definition ''filter feed rate … % of the total water volume/day'': type III > 25 % (Table 4), types IV/V > 80 % (Tables 5/6). The result is checked in REQ-35.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.equation_number = 'FLLNT-11-D3';
UPDATE compliance_requirements x SET description = 'Gilt nur, wenn „Physikalisch-chemische Verfahren verwendet“ gesetzt ist; besteht dann, wenn die Regenerationstechnik in FLLNT-03 nicht „physikalisch-chemisch“ ist. §10.2.5/§10.1: Solche Verfahren dürfen nur zusammen mit biologischen Verfahren und nur als Ergänzung eingesetzt werden; die Wasseraufbereitung muss die Anforderungen nach Abschnitt 5 auch ohne sie erfüllen. Wählen Sie in FLLNT-03 die biologische Haupttechnik (hydrobotanisch, Substratfilter, technische Einheit).
[EN] Applies only when ''Physical/chemical techniques used'' is ticked; then passes when the regeneration technique in FLLNT-03 is not ''physical-chemical''. §10.2.5/§10.1: such techniques can only be applied in conjunction with biological techniques and only as supplementary methods; water purification must meet the section 5 requirements without them. Select the biological main technique in FLLNT-03 (hydrobotanical, substrate filter, technical unit).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-24';
UPDATE compliance_requirements x SET description = 'Besteht, wenn „Unzulässige Behandlung verwendet“ auf „nein“ steht. §10.1 erklärt folgende Anwendungen für ungeeignet und unzulässig: Desinfektionsmittel (Chlor, Chlordioxid, Ozon), Biozide/Biozidprodukte (Insektizide, Fungizide, Algizide), schwermetallhaltige Produkte, Silber-/Kupfertechniken, UV-Desinfektion, Beschallung. Es sind Verbote, keine Ergänzungsverfahren; prüfen Sie die gesamte Anlagentechnik und die Wasserpflegemittel.
[EN] Passes when ''Impermissible treatment used'' is ''no''. §10.1 deems the following applications unsuitable and impermissible: disinfectants (chlorine, chlorine dioxide, ozone), biocides and biocidal products (insecticides, fungicides, algicides), products containing heavy metals, silver- and copper-based techniques, UV disinfection, sonification. These are prohibitions, not supplementary techniques; check all plant equipment and water care products.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-29';
UPDATE compliance_requirements x SET description = 'Gilt nur bei starrem Überlaufwehr; besteht dann, wenn das Schwallwasser-Nutzvolumen ≥ 150 l × angeschlossene Wasseroberfläche (m²) ist – beide Felder eintragen. §10.3.1: Ein Wasserspeicher ist bei starren Überlaufwehren zwingend und muss mindestens 150 l je m² überstauter Wasserfläche bereitstellen; bei Mehrbereichssystemen zählt nur die Fläche des angeschlossenen Bereichs. Bei nur flexiblen Wehren (Skimmer) ist das Tor ohne Wirkung.
[EN] Applies only with a rigid overflow weir; then passes when the usable splash water volume ≥ 150 l × connected water surface (m²) – enter both fields. §10.3.1: a water reservoir is mandatory when using rigid overflow weirs and must provide at least 150 l per m² of inundated water surface; in multi-area systems only the surface of the connected area counts. With flexible weirs (skimmers) only, the gate has no effect.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-33';
UPDATE compliance_requirements x SET description = 'Gilt nur bei Teichtyp II (FLLNT-03); besteht dann, wenn die Betriebsdauer des Oberflächenabzugs im Intervallbetrieb < 10 h/Tag ist. Tab. 3 definiert Typ II als Naturteich mit Oberflächenreinigung über Skimmer oder Überlaufwehr, ohne Filter, mit „surface water discharge in interval operation < 10 h/day“. Tragen Sie die tägliche Laufzeit aus der Steuerung ein.
[EN] Applies only to pool type II (FLLNT-03); then passes when the surface discharge running time in interval operation is < 10 h/day. Table 3 defines type II as a natural pool with surface purification by skimmer or overflow weir, no filter, with ''surface water discharge in interval operation < 10 h/day''. Enter the daily running time from the control settings.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-34';
UPDATE compliance_requirements x SET description = 'Gilt bei Typ III, IV und V; besteht, wenn der berechnete Beschickungsanteil (FLLNT-11-D3) bei Typ III > 25 % und bei Typ IV/V > 80 % des Gesamtwasservolumens je Tag ist. Einzugeben: tägliches Beschickungsvolumen hier und Gesamtwasservolumen in FLLNT-06. Grundlage sind die Typdefinitionen: Tab. 4 „filter feed rate > 25% of the total water volume/day“, Tab. 5 „> 80%“, Tab. 6 „filtration rate > 80%“.
[EN] Applies to types III, IV and V; passes when the computed feed share (FLLNT-11-D3) is > 25 % for type III and > 80 % for types IV/V of the total water volume per day. Enter the daily feed volume here and the total water volume in FLLNT-06. Basis: the type definitions – Table 4 ''filter feed rate > 25% of the total water volume/day'', Table 5 ''> 80%'', Table 6 ''filtration rate > 80%''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-35';
UPDATE compliance_requirements x SET description = 'Gilt bei Typ III, IV und V; besteht bei Typ III, wenn der Filter > 12 h/Tag läuft UND die längste Stillstandszeit ≤ 1 h ist, bei Typ IV/V, wenn der Filter 24 h/Tag läuft. Tab. 4: „filter operation > 12 h/day“, „maximum downtime 1 h“; Tab. 5/6: „filter operation 24 h/day“. Tragen Sie Betriebsstunden (und bei Typ III die Stillstandszeit) aus dem Betriebsplan ein.
[EN] Applies to types III, IV and V; passes for type III when the filter runs > 12 h/day AND the longest downtime is ≤ 1 h, for types IV/V when the filter runs 24 h/day. Table 4: ''filter operation > 12 h/day'', ''maximum downtime 1 h''; Tables 5/6: ''filter operation 24 h/day''. Enter the operating hours (and for type III the downtime) from the operating plan.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-36';
UPDATE compliance_requirements x SET description = 'Besteht, wenn keine Zeile des Registers „Überlauf-/Ablaufeinrichtungen“ die Toleranz überschreitet (Verletzungen = 0). §10.3.1: Überlaufwehre sind so einzubauen, dass die Kante horizontal um nicht mehr als +/- 2 mm abweicht, bei Kanten bis 1 m um nicht mehr als +/- 1 mm. Tragen Sie je Wehr Kantenlänge und gemessene Abweichung ein; ein leeres Register ergibt 0 Verletzungen.
[EN] Passes when no row of the register ''Overflow / discharge devices'' exceeds the tolerance (violations = 0). §10.3.1: overflow weirs are to be installed so that the edge does not deviate horizontally by more than +/- 2 mm, or by more than +/- 1 mm for edges up to 1 m. Enter edge length and measured deviation per weir; an empty register yields 0 violations.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-40';
UPDATE compliance_requirements x SET description = 'Warnung, kein Block: erfüllt, wenn die Summe der Kantenlängen im Register ≥ dem Richtwert aus EQ-04 (1 % der Schwimmbereichsfläche in Metern) ist. §10.3.1 nennt den Wert als Anhalt („As a guide … can be used“), Beispiel 30 m² → 0,3 m; Anzahl, Art und Anordnung der Entnahmestellen richten sich nach Umwälzstrom, Örtlichkeit und Teichtyp. Einzugeben: Schwimmbereichsfläche und die Kanten im Register.
[EN] Warning, not a block: satisfied when the sum of edge lengths in the register ≥ the guide value from EQ-04 (1 % of the swimming-area surface in metres). §10.3.1 gives the value as a guide (''As a guide … can be used''), example 30 m² → 0.3 m; number, type and arrangement of the extraction devices depend on recirculation current, local conditions and pool type. Enter the swimming-area surface and the edges in the register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-41';
UPDATE fields x SET description = 'Bestätigen Sie, dass die Bepflanzung nach §10.4 ausgeführt ist: Pflanzenwahl nach Teichtyp (§6.2.2: heimische Arten, keine invasiven Neophyten; Typ I–III besonders strenge Anforderungen an Arten, Saat-/Pflanzgut und Substrat, §10.4.1), Pflanzenqualität nach DIN 18916/„Gütebestimmungen für Stauden“ (mineralisch kultiviert, ohne Depotdünger, frei von Fremdbewuchs), Pflanzung in der Vegetationsperiode (§10.4.3), Fertigstellungspflege bis „ready for acceptance inspection“ (§10.4.4) und Anwuchskontrolle auf Fremdbewuchs (§10.4.5). Tor REQ-25 blockiert ohne Haken.
[EN] Confirm that planting is executed per §10.4: plant selection by pool type (§6.2.2: species native to Central Europe, no invasive alien species; types I–III with particularly strict requirements on species, seed stock and substrate, §10.4.1), plant quality per DIN 18916 / ''Gütebestimmungen für Stauden'' (cultivated in mineral substrate, no feeding fertiliser, free of foreign growth), planting during the vegetation period (§10.4.3), care until the status ''ready for acceptance inspection'' (§10.4.4) and pre-maturity checks for foreign growth (§10.4.5). Gate REQ-25 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'attest_fllnt_12_req_25';
UPDATE fields x SET description = 'Gewählte Pflanzdichte für mittelhohe bis hohe Sumpf- und Wasserpflanzen in Pflanzen je m² Pflanzfläche. §10.4.3 nennt als Anhaltswert „medium height to tall marsh and aquatic plants 5 – 7 plants“ je m², bezogen auf Topfware P 0,5 (500 cm³). Tragen Sie den Wert aus dem Pflanzplan ein; er fließt in die Pflanzenzahl ein.
[EN] Chosen planting density for medium-height to tall marsh and aquatic plants in plants per m² of planting surface. §10.4.3 gives as an approximate value ''medium height to tall marsh and aquatic plants 5 – 7 plants'' per m², for pot plants P 0.5 (500 cm³). Enter the value from the planting plan; it feeds the plant count.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'plant_density_marsh_medium_per_m2';
UPDATE fields x SET description = 'Gewählte Pflanzdichte für halbhohe bis hohe Sumpf- und Wasserpflanzen in Pflanzen je m² Pflanzfläche. §10.4.3 nennt als Anhaltswert „half-height to tall marsh and aquatic plants 3 – 5 plants“ je m², bezogen auf Topfware P 0,5 (500 cm³). Tragen Sie den Wert aus dem Pflanzplan ein.
[EN] Chosen planting density for half-height to tall marsh and aquatic plants in plants per m² of planting surface. §10.4.3 gives as an approximate value ''half-height to tall marsh and aquatic plants 3 – 5 plants'' per m², for pot plants P 0.5 (500 cm³). Enter the value from the planting plan.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'plant_density_marsh_small_per_m2';
UPDATE fields x SET description = 'Gewählte Pflanzdichte für Unterwasserpflanzen (submerse Hydrophyten) in Pflanzen je m² Pflanzfläche. §10.4.3 nennt als Anhaltswert „submerged plants 6 – 10 plants“ je m², bezogen auf Topfware P 0,5 (500 cm³); Seerosen je nach Art. Tragen Sie den Wert aus dem Pflanzplan ein.
[EN] Chosen planting density for underwater plants (submerged hydrophytes) in plants per m² of planting surface. §10.4.3 gives as an approximate value ''submerged plants 6 – 10 plants'' per m², for pot plants P 0.5 (500 cm³); lilies depending on type. Enter the value from the planting plan.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'plant_density_submerged_per_m2';
UPDATE fields x SET description = 'Register der Pflanzenliste: eine Zeile je Art mit Zone/Teichbereich (submers, emers/Sumpf, Filter), Pflanzfläche in m², gewählter Dichte und Anzahl/Bemerkung. §6.2.2: Arten nach Standort, angestrebt niedrigen Nährstoffgehalten und pflanzensoziologischen Eigenschaften wählen, heimische Arten bevorzugen, keine invasiven Neophyten; in Filtern dürfen Wurzeln die Filterfunktion nicht beeinträchtigen. §10.4.1/10.4.2: Qualität nach DIN 18916. Die Software legt keine Artenliste vor.
[EN] Register of the plant list: one row per species with zone/pool area (submerged, emersed/marsh, filter), planting area in m², chosen density and count/remark. §6.2.2: select species by locational conditions, the aspired low nutrient concentrations and plant-sociological properties, favour species native to Central Europe, no invasive alien species; in filters roots must not compromise the filter function. §10.4.1/10.4.2: quality per DIN 18916. The software provides no species list.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'plant_species_list';
UPDATE fields x SET description = 'Datum, an dem die Pflanzung abgeschlossen und der Zustand „ready for acceptance inspection“ erreicht ist. §10.4.4: Pflanzung schließt die Fertigstellungspflege bis zur Abnahmereife ein; Pflanzen gelten als angewachsen, wenn sie Fuß gefasst haben bzw. Unterwasserpflanzen sich vermehren – in der Regel nach 4–8 Wochen bei Pflanzung in der Vegetationsperiode, sonst 4–6 Wochen nach Beginn der nächsten. §10.4.3: beste Pflanzzeit Ende April/Anfang Mai bis Mitte Juli, Ballenware spätestens Ende September.
[EN] Date on which planting is completed and the status ''ready for acceptance inspection'' is attained. §10.4.4: planting includes pre-maturity care until that status; plants are deemed mature once they have established a footing or, for underwater plants, started to propagate – usually after 4–8 weeks when planted in the vegetation period, otherwise 4–6 weeks after the next one begins. §10.4.3: best planting time end of April/beginning of May to mid-July, root-ball plants no later than the end of September.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'planting_completion_date';
UPDATE fields x SET description = 'Bestätigen Sie, dass die Fertigstellungs-/Anwuchspflege erbracht ist (empfohlen durch die ausführende Firma). §10.4.5: Während der Anwuchspflege Neupflanzungen auf unerwünschten Fremdbewuchs kontrollieren – einmal bei Pflanzung im Frühjahr/in der Vegetationsperiode, einmal im Herbst und einmal im Frühjahr bei Pflanzung außerhalb; hemmender Fremdbewuchs ist mechanisch zu entfernen. Hat der Auftraggeber vertraglich darauf verzichtet, ist er über Art, Umfang und Zeitpunkt der nötigen Arbeiten zu informieren (§10.4.4).
[EN] Confirm that pre-maturity care has been provided (recommended to be done by the installation firm). §10.4.5: during the pre-maturity care period check new plantings for unwanted foreign growth – once if planted in spring or during the vegetation period, once in autumn and once in spring if planted outside it; foreign growth that inhibits the designated plants is removed mechanically. If the purchaser waived this care by contract, he must be informed about type, scope and timing of the work required (§10.4.4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'pre_maturity_care_provided';
UPDATE fields x SET description = 'Wird berechnet (FLLNT-12-D1), nicht eingegeben: Summe über die Pflanzenliste aus Pflanzfläche × gewählter Dichte je Zeile, in Stück. Anhaltswerte je Gruppe nach §10.4.3: submers 6–10, halbhoch bis hoch 3–5, mittelhoch bis hoch 5–7 Pflanzen je m² (Topfware P 0,5). Dient der Mengenermittlung für Bestellung und Leistungsbeschreibung.
[EN] Computed (FLLNT-12-D1), not entered: sum over the plant list of planting area × chosen density per row, in pieces. Approximate values per group per §10.4.3: submerged 6–10, half-height to tall 3–5, medium height to tall 5–7 plants per m² (pot plants P 0.5). Used for quantity take-off for ordering and the description of services.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'plant_count_total';
UPDATE equations x SET description = 'Pflanzenzahl gesamt (Stück) = Summe über die Zeilen der Pflanzenliste von Pflanzfläche (m²) × gewählte Dichte (Pflanzen/m²). Die Dichte je Gruppe folgt den Anhaltswerten in §10.4.3: Unterwasserpflanzen 6–10, halbhohe bis hohe Sumpf-/Wasserpflanzen 3–5, mittelhohe bis hohe 5–7 je m², Seerosen je nach Art; bezogen auf Topfware P 0,5 (500 cm³). Ergebnis: Mengenermittlung.
[EN] Total plant count (pieces) = sum over the rows of the plant list of planting area (m²) × chosen density (plants/m²). The density per group follows the approximate values in §10.4.3: submerged plants 6–10, half-height to tall marsh and aquatic plants 3–5, medium height to tall 5–7 per m², lilies depending on type; for pot plants P 0.5 (500 cm³). Result: quantity take-off.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.equation_number = 'FLLNT-12-D1';
UPDATE compliance_requirements x SET description = 'Besteht, wenn der Nachweis „§10.4 / §6.2.2“ bestätigt ist. Was zutreffen muss: Pflanzen typgerecht und standortgerecht gewählt (heimische Arten, keine invasiven Neophyten, §6.2.2), Qualität nach DIN 18916 ohne Depotdünger und Fremdbewuchs (§10.4.1/10.4.2), Pflanzung in der Vegetationsperiode (§10.4.3), Fertigstellungspflege bis zur Abnahmereife (§10.4.4) und Anwuchskontrolle auf Fremdbewuchs (§10.4.5). Füllen Sie Pflanzenliste, Pflanztermin und Anwuchspflege aus, bevor Sie bestätigen.
[EN] Passes when the attestation ''§10.4 / §6.2.2'' is confirmed. What must be true: plants selected for the pool type and location (native species, no invasive alien species, §6.2.2), quality per DIN 18916 without feeding fertiliser or foreign growth (§10.4.1/10.4.2), planting during the vegetation period (§10.4.3), care until ready for acceptance inspection (§10.4.4) and pre-maturity checks for foreign growth (§10.4.5). Fill in the plant list, completion date and pre-maturity care before confirming.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.code = 'REQ-25';
UPDATE fields x SET description = 'Datum der Abnahme der Bauleistung. §11.1: In sich abgeschlossene Teilleistungen sollen auf Verlangen nach § 12 Nr. 2 VOB/B gesondert abgenommen werden – technische und bauliche Anlagen nach Fertigstellung, die Bepflanzung nach Erreichen der Abnahmereife (§10.4.4) oder nach Fertigstellung, wenn der Auftraggeber auf die Fertigstellungspflege verzichtet hat. Tragen Sie das Datum des Abnahmeprotokolls ein.
[EN] Date of the acceptance inspection of the building work. §11.1: parts completed in themselves should be inspected and accepted separately on demand per § 12 no. 2 VOB/B – technical and structural installations after completion, planting once ''ready for acceptance inspection'' (§10.4.4) or after completion if the purchaser waived pre-maturity care. Enter the date of the acceptance record.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.symbol = 'acceptance_date';
UPDATE fields x SET description = 'Ergebnis der Abnahme: Haken, wenn der Auftraggeber die Leistung körperlich abgenommen und als im Wesentlichen vertragsgemäß anerkannt hat (§11.1, „physical acceptance … accepts the work as specified in the contract“). Abnahme und Verjährung der Mängelansprüche richten sich nach dem Vertrag, sonst nach dem Gesetz (BGB/VOB, §11.2). Tor REQ-26 blockiert ohne Haken; festgestellte Mängel in das Mängelfeld.
[EN] Result of the acceptance inspection: tick when the purchaser has physically accepted the service and asserted that the work is basically as specified in the contract (§11.1). Acceptance and the periods of limitation for claims due to defects follow the contract, otherwise the legal provisions (BGB/VOB, §11.2). Gate REQ-26 blocks until ticked; record defects found in the defects field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.symbol = 'acceptance_passed';
UPDATE fields x SET description = 'Bestätigen Sie, dass Reparaturen, die bei Kontrollen oder Wartung festgestellt werden, im vereinbarten Umfang ausgeführt werden – §12.4 nennt z. B. Ersatz von Filtermaterial, Austausch defekter Technik, Ersatz und Ergänzung von Pflanzen, Instandsetzung baulicher Einbauten – und dass bei einem unvermeidbaren umfassenden oder vollständigen Wasserwechsel berücksichtigt ist, dass sich das biologische System in der Regel erst nach 1 bis 2 Monaten wieder stabilisiert. Tor REQ-28 blockiert ohne Haken.
[EN] Confirm that repairs found necessary during checks or maintenance are performed within the agreed scope – §12.4 lists e.g. replacing filter materials, replacing defective technical systems, replacing and supplementing plants, repairing structural installations – and that, if a comprehensive or complete change of water is unavoidable, it is taken into account that the biological system will usually need 1 to 2 months to stabilise again. Gate REQ-28 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.symbol = 'attest_fllnt_13_req_28';
UPDATE fields x SET description = 'Vorlauf in Werktagen, mit dem der Auftragnehmer den Auftraggeber über den bevorstehenden Fertigstellungstermin informiert hat. §11.1: „no later than 3 working days before the respective completion date“; Tor REQ-42 prüft ≥ 3. Tragen Sie die tatsächliche Anzahl Werktage zwischen Anzeige und Fertigstellung ein.
[EN] Advance notice in working days with which the supplier informed the purchaser of the pending completion date. §11.1: ''no later than 3 working days before the respective completion date''; gate REQ-42 checks ≥ 3. Enter the actual number of working days between the notice and completion.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.symbol = 'completion_notice_days_advance';
UPDATE fields x SET description = 'Bei der Abnahme festgestellte Mängel mit Ort, Beschreibung und vereinbarter Frist; leer lassen, wenn keine. §11.2: Mängelansprüche richten sich nach BGB und VOB in der jeweils geltenden Fassung; §11.1 verweist zusätzlich auf den FLL-Musterbauvertrag für Privatauftraggeber. Grundlage für die Nachbesserung und das Abnahmeprotokoll.
[EN] Defects found at acceptance with location, description and agreed deadline; leave empty if none. §11.2: claims due to defects follow the effective versions of the BGB and the VOB; §11.1 additionally refers to the FLL sample building contract for private purchasers. Basis for rectification and the acceptance record.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.symbol = 'defects_noted';
UPDATE compliance_requirements x SET description = 'Besteht, wenn „Abnahme bestanden“ gesetzt ist. §11.1: Die Abnahme ist die körperliche Entgegennahme der Leistung durch den Auftraggeber mit der Erklärung, dass er das Werk im Wesentlichen als vertragsgemäß anerkennt; Teilleistungen (Technik, bauliche Anlagen, Bepflanzung nach Abnahmereife) können gesondert abgenommen werden. Tragen Sie Datum, Ergebnis und etwaige Mängel ein.
[EN] Passes when ''Acceptance passed'' is ticked. §11.1: the acceptance inspection is the physical acceptance of the service by the purchaser combined with the assertion that he basically accepts the work as specified in the contract; parts (technical installations, structural installations, planting once ready) can be accepted separately. Enter date, result and any defects.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.code = 'REQ-26';
UPDATE compliance_requirements x SET description = 'Besteht, wenn der Nachweis „§12.4“ bestätigt ist. Was zutreffen muss: Reparaturen aus Kontrollen und Wartung werden im vereinbarten Umfang ausgeführt (Filtermaterial, Technik, Pflanzen, bauliche Einbauten), und ein unvermeidbarer umfassender oder vollständiger Wasserwechsel ist mit der Wiederstabilisierung des biologischen Systems von in der Regel 1 bis 2 Monaten eingeplant.
[EN] Passes when the attestation ''§12.4'' is confirmed. What must be true: repairs found during checks and maintenance are performed within the agreed scope (filter materials, technical systems, plants, structural installations), and an unavoidable comprehensive or complete change of water is planned with the re-stabilisation of the biological system of usually 1 to 2 months.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.code = 'REQ-28';
UPDATE compliance_requirements x SET description = 'Besteht, wenn der Vorlauf der Fertigstellungsanzeige ≥ 3 Werktage ist. §11.1: Der Auftragnehmer muss den Auftraggeber spätestens 3 Werktage vor dem jeweiligen Fertigstellungstermin über den Termin informieren. Tragen Sie die tatsächlichen Werktage zwischen Anzeige und Fertigstellung ein.
[EN] Passes when the completion notice advance is ≥ 3 working days. §11.1: the supplier must inform the purchaser of pending completion dates no later than 3 working days before the respective completion date. Enter the actual working days between notice and completion.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.code = 'REQ-42';
UPDATE fields x SET description = 'Beschreiben Sie Intervalle und Umfang der Kontrollen. §12.2 nennt regelmäßig zu prüfen: Wassertransparenz, Wasserchemie (messen und dokumentieren), Beckenrand (Standsicherheit, Kapillarsperre, Oberflächenwasser), ungewöhnliche Wasserverluste, Dichtungssystem, Funktion von Leitungen/Überläufen/Technik, Algen, Vegetationsentwicklung, Tiere, Schädlinge; der Auftragnehmer soll die Kontrollen während der Gewährleistung einmal jährlich durchführen, danach Routinekontrollen z. B. einmal jährlich durch einen Fachkundigen. Tab. 13: Wasseranalyse 1–2× jährlich (Typ I–III) bzw. 3–5× (Typ IV–V), Schmutzfänger täglich leeren.
[EN] Describe intervals and scope of the checks. §12.2 lists regular checks of water transparency, water chemistry (measure and document), pool edge (stability, capillary block, surface water), unusually high water losses, sealing system, working condition of pipes/overflows/technical installations, algae, growth of the planned vegetation, animals, pests; the supplier should perform the checks once annually during the warranty period, afterwards routine checks e.g. once a year by a specialist. Table 13: water analysis 1–2 times a year (types I–III) or 3–5 times (types IV–V), empty dirt strainers daily.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-14' AND x.symbol = 'inspection_frequency';
UPDATE fields x SET description = 'Bestätigen Sie, dass ein Wartungsvertrag oder ein verbindlicher Pflege-/Wartungsplan vorliegt. §12.1: Ein Naturteich funktioniert dauerhaft nur bei regelmäßiger, fachgerechter Instandhaltung (Kontrollen, Pflege von Vegetation, Wasser, Substrat und Dichtung, Wartung der Technik, Reparaturen); kann oder will der Eigentümer das nicht selbst leisten, soll er eine qualifizierte Firma beauftragen. Eine schriftliche Betriebsanleitung mit Kontrollen, Pflegearbeiten und Intervallen ist Pflicht (§12.1, §8.1.5). Tor REQ-27 blockiert ohne Haken.
[EN] Confirm that a maintenance contract or a binding care/maintenance schedule exists. §12.1: a natural pool only works in the long run if maintained regularly and properly (checks, maintenance of vegetation, water, substrate and sealing, maintenance of technical installations, repairs); if the owner is unwilling or incapable of doing this, he should contract a suitably qualified company. Written operating instructions with checks, maintenance work and intervals are mandatory (§12.1, §8.1.5). Gate REQ-27 blocks until ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-14' AND x.symbol = 'maintenance_contract_in_place';
UPDATE fields x SET description = 'Beschreiben Sie die Regelungen für Reparaturen: Wer führt im vereinbarten Umfang Reparaturen aus, die bei Kontrollen oder Wartung festgestellt werden (§12.4: Ersatz von Filtermaterial, Austausch defekter Technik, Ersatz/Ergänzung von Pflanzen, Instandsetzung baulicher Einbauten), und wie ist ein umfassender oder vollständiger Wasserwechsel geplant, nach dem sich das biologische System in der Regel erst nach 1 bis 2 Monaten wieder stabilisiert.
[EN] Describe the repair arrangements: who performs, within the agreed scope, repairs found necessary during checks or maintenance (§12.4: replacing filter materials, replacing defective technical systems, replacing/supplementing plants, repairing structural installations), and how a comprehensive or complete change of water is planned, after which the biological system usually needs 1 to 2 months to stabilise again.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-14' AND x.symbol = 'repair_provisions';
UPDATE compliance_requirements x SET description = 'Besteht, wenn „Wartungsvertrag“ bestätigt ist. Was zutreffen muss: Regelmäßige Instandhaltung nach §12.1–12.3 ist organisiert – Kontrollen (§12.2), Pflege und Wartung von Vegetation, Wasser, Substrat, Dichtung und Technik nach Tab. 13 (z. B. Rückschnitt Spätsommer bis Frühjahr, Schmutzfänger täglich, Wasseranalyse 1–2× bzw. 3–5× jährlich, Winterschutz nach der Badesaison), schriftliche Betriebsanleitung vorhanden. Wasserpflegemittel unter der Biozidverordnung nur mit Zulassung für Naturteiche und nur vorübergehend (§12.3).
[EN] Passes when ''Maintenance contract in place'' is confirmed. What must be true: regular maintenance per §12.1–12.3 is organised – checks (§12.2), care and maintenance of vegetation, water, substrate, sealing and technical installations per Table 13 (e.g. cutting back late summer to spring, dirt strainers daily, water analysis 1–2 or 3–5 times a year, winter protection after the swimming season), written operating instructions exist. Water care products under the biocidal products regulation only with approval for natural pools and only temporarily (§12.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-14' AND x.code = 'REQ-27';
UPDATE fields x SET description = 'Zusammenfassendes Urteil über Phase 1 (FLLNT-01 Anwendungsbereich/Projekt, FLLNT-02 Grundlagen): „bestanden“, wenn alle Tore dieser Blätter erfüllt sind, „nicht bestanden“ bei offenen Blocks, „bedingt“ bei dokumentierten Abweichungen, „nicht zutreffend“ oder „ausstehend“. Reines Übersichtsfeld der Software ohne eigene Prüfung; tragen Sie den Stand aus den Blättern ein.
[EN] Summary verdict for phase 1 (FLLNT-01 scope/project, FLLNT-02 basics): ''pass'' when all gates of these sheets are met, ''fail'' with open blocks, ''conditional'' with documented deviations, ''not applicable'' or ''pending''. A software overview field with no check of its own; enter the status from the sheets.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_1_gate';
UPDATE fields x SET description = 'Zusammenfassendes Urteil über Phase 2 (FLLNT-03 Teichtyp, FLLNT-04 Wasserqualität, FLLNT-05 Substrate): „bestanden“, wenn alle Tore erfüllt sind, „nicht bestanden“ bei offenen Blocks, „bedingt“, „nicht zutreffend“ oder „ausstehend“. Übersichtsfeld ohne eigene Prüfung.
[EN] Summary verdict for phase 2 (FLLNT-03 pool type, FLLNT-04 water quality, FLLNT-05 substrates): ''pass'' when all gates are met, ''fail'' with open blocks, ''conditional'', ''not applicable'' or ''pending''. Overview field with no check of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_2_gate';
UPDATE fields x SET description = 'Zusammenfassendes Urteil über Phase 3 (FLLNT-06 Flächen, FLLNT-07 Bau/Konstruktion, FLLNT-08 Ausstattung/Leistungsbeschreibung): „bestanden“, wenn alle Tore erfüllt sind, „nicht bestanden“ bei offenen Blocks, „bedingt“, „nicht zutreffend“ oder „ausstehend“. Übersichtsfeld ohne eigene Prüfung.
[EN] Summary verdict for phase 3 (FLLNT-06 areas, FLLNT-07 building/structural, FLLNT-08 equipment/description of services): ''pass'' when all gates are met, ''fail'' with open blocks, ''conditional'', ''not applicable'' or ''pending''. Overview field with no check of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_3_gate';
UPDATE fields x SET description = 'Zusammenfassendes Urteil über Phase 4 (FLLNT-09 Hydrobotanik, FLLNT-10 Substratfilter, FLLNT-11 Wasserzirkulation): „bestanden“, wenn alle Tore erfüllt sind, „nicht bestanden“ bei offenen Blocks, „bedingt“, „nicht zutreffend“ (z. B. kein Filter bei Typ I/II) oder „ausstehend“. Übersichtsfeld ohne eigene Prüfung.
[EN] Summary verdict for phase 4 (FLLNT-09 hydrobotanical system, FLLNT-10 substrate filter, FLLNT-11 water circulation): ''pass'' when all gates are met, ''fail'' with open blocks, ''conditional'', ''not applicable'' (e.g. no filter for types I/II) or ''pending''. Overview field with no check of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_4_gate';
UPDATE fields x SET description = 'Zusammenfassendes Urteil über Phase 5 (FLLNT-12 Pflanzplan): „bestanden“, wenn Tor REQ-25 erfüllt ist, „nicht bestanden“ bei offenem Block, „bedingt“, „nicht zutreffend“ oder „ausstehend“. Übersichtsfeld ohne eigene Prüfung.
[EN] Summary verdict for phase 5 (FLLNT-12 planting plan): ''pass'' when gate REQ-25 is met, ''fail'' with an open block, ''conditional'', ''not applicable'' or ''pending''. Overview field with no check of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_5_gate';
UPDATE fields x SET description = 'Zusammenfassendes Urteil über Phase 6 (FLLNT-13 Abnahme, FLLNT-14 Instandhaltung): „bestanden“, wenn alle Tore erfüllt sind, „nicht bestanden“ bei offenen Blocks, „bedingt“, „nicht zutreffend“ oder „ausstehend“. Übersichtsfeld ohne eigene Prüfung.
[EN] Summary verdict for phase 6 (FLLNT-13 acceptance, FLLNT-14 maintenance): ''pass'' when all gates are met, ''fail'' with open blocks, ''conditional'', ''not applicable'' or ''pending''. Overview field with no check of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_6_gate';
UPDATE fields x SET description = 'Ingenieurmäßiges Gesamturteil über alle sechs Phasen: „konform“, wenn alle Phasen bestanden sind; „konform mit Auflagen“, wenn Abweichungen dokumentiert und begründet sind; „nicht konform“ bei offenen Blocks; „unzureichende Daten“, wenn Pflichtangaben fehlen. Das Feld fasst zusammen und ersetzt keine Prüfung der Einzelblätter.
[EN] Engineering verdict over all six phases: ''compliant'' when every phase passes; ''compliant with conditions'' when deviations are documented and justified; ''not compliant'' with open blocks; ''insufficient data'' when required inputs are missing. The field summarises and does not replace the checks on the individual sheets.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'compliance_verdict_overall';
COMMIT;
